.cy-dock-new { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 12px; color: #fff;
  background: linear-gradient(135deg, #2f7eef, #8c3ae9 70%); box-shadow: 0 8px 24px -10px rgba(140, 58, 233, .9), inset 0 1px 0 rgba(255,255,255,.25); transition: transform .18s var(--cy-ease), box-shadow .2s; }
