.cy-dock-i.on::before { content: ""; position: absolute; left: -10px; top: 12px; bottom: 12px; width: 3px; border-radius: 3px; background: linear-gradient(var(--cy-n1), var(--cy-n3)); }
.cy-dock-fav { position: absolute; right: 5px; top: 5px; width: 6px; height: 6px; border-radius: 50%; background: #ffcf6b; box-shadow: 0 0 6px #ffcf6b; }
.cy-dock-tip { position: absolute; left: calc(100% + 14px); top: 50%; transform: translate(-4px, -50%); white-space: nowrap; pointer-events: none; opacity: 0;
  font-size: 12px; font-weight: 550; color: var(--cy-ink); padding: 6px 10px; border-radius: 9px; background: var(--cy-glass-solid); border: 1px solid var(--cy-line2); box-shadow: var(--cy-shadow); transition: opacity .15s, transform .15s var(--cy-ease); }
