.cy-dock-lib { display: grid; place-items: center; gap: 2px; width: 40px; padding: 6px 0; border-radius: 12px; color: var(--cy-ink3); transition: background .18s, color .18s; }
.cy-dock-lib span { font: 600 10px/1 var(--font-mono); }
.cy-dock-lib:hover, .cy-dock-lib.on { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-drawer { width: 300px; display: flex; flex-direction: column; border-radius: 20px; padding: 14px 10px 10px; opacity: 0; transform: translateX(-12px) scale(.985); transform-origin: left center; pointer-events: none; visibility: hidden;
  transition: opacity .22s var(--cy-ease), transform .26s var(--cy-ease), visibility 0s .26s; background: var(--cy-glass2); }
.dock-open .cy-drawer { opacity: 1; transform: none; pointer-events: auto; visibility: visible; transition: opacity .22s var(--cy-ease), transform .26s var(--cy-ease); }
.cy-drawer-h { display: flex; align-items: baseline; justify-content: space-between; padding: 0 8px 10px; }
.cy-drawer-t { font-size: 15px; font-weight: 650; letter-spacing: -.01em; }
.cy-drawer-n { font-size: 11.5px; color: var(--cy-ink3); }
.cy-drawer-q { display: flex; align-items: center; gap: 8px; height: 36px; margin: 0 4px 8px; padding: 0 11px; border-radius: 11px; color: var(--cy-ink3); background: var(--cy-raise); border: 1px solid var(--cy-line); }
