/* glyph (per-mod constellation) */
.cy-glyph { position: relative; display: inline-grid; place-items: center; flex: none; border-radius: 50%; background: radial-gradient(circle at 40% 35%, rgba(255,255,255,.06), rgba(5, 8, 30, .7)); box-shadow: inset 0 0 0 1px var(--cy-line); }
