.cy-seed { height: 30px; padding: 0 12px; border-radius: 999px; font-size: 12.5px; font-weight: 500; color: var(--cy-ink2); border: 1px solid var(--cy-line); background: rgba(10, 14, 42, .72); transition: color .18s, border-color .18s, background .18s, transform .18s var(--cy-ease); }
.cy-seed:hover, .cy-seed:focus-visible { color: var(--cy-ink); border-color: rgba(165, 92, 240, .5); background: rgba(140, 58, 233, .16); transform: translateY(-1px); }
.cy-seed.more { display: inline-flex; align-items: center; gap: 3px; color: var(--cy-ink3); border-style: dashed; }
.cy-legal { position: absolute; left: 0; right: 0; bottom: 14px; text-align: center; font-size: 10.5px; color: var(--cy-ink4); pointer-events: none; }

/* ── composer + rotating rim ─────────────────────────────────────────── */
.cy-composer { position: relative; width: 100%; max-width: 760px; text-align: left; }
.cy-composer-box { position: relative; isolation: isolate; border-radius: 22px; }
.cy-composer-box::before { content: ""; position: absolute; inset: -6px; z-index: -1; border-radius: 28px; filter: blur(18px); opacity: 0;
  background: conic-gradient(from var(--cy-ang), transparent 0deg 190deg, var(--cy-n1) 250deg, var(--cy-n2) 285deg, var(--cy-n3) 315deg, var(--cy-n5) 340deg, transparent 360deg);
  animation: cy-rim 9s linear infinite paused; transition: opacity .4s var(--cy-ease); }
.cy-rim { position: absolute; inset: 0; z-index: 2; border-radius: inherit; padding: 1px; pointer-events: none; opacity: .55;
  background: conic-gradient(from var(--cy-ang), rgba(150,165,255,.18) 0deg 190deg, var(--cy-n1) 250deg, var(--cy-n2) 285deg, var(--cy-n3) 315deg, var(--cy-n5) 340deg, rgba(150,165,255,.18) 360deg);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  animation: cy-rim 9s linear infinite paused; transition: opacity .3s; }
.cy-composer:focus-within .cy-rim, .cy-composer.listening .cy-rim { opacity: 1; animation-play-state: running; }
.cy-composer:focus-within .cy-composer-box::before { opacity: .38; animation-play-state: running; }
.cy-composer.listening .cy-composer-box::before { opacity: .75; animation-play-state: running; animation-duration: 3s; }
.cy-composer.listening .cy-rim { animation-duration: 3s; }
.cy-composer.drag .cy-composer-in { border-color: var(--cy-n1); box-shadow: var(--cy-shadow), inset 0 0 0 1px var(--cy-n1); }
.cy-composer-in { position: relative; z-index: 1; border-radius: inherit; display: flex; flex-direction: column; background: linear-gradient(180deg, rgba(18, 23, 64, .82), rgba(9, 13, 42, .86)); border-color: transparent;
  box-shadow: 0 24px 70px -28px rgba(70, 50, 200, .65), 0 2px 0 rgba(0, 0, 0, .2), inset 0 1px 0 rgba(255, 255, 255, .07); }
:root.nx-portal[data-theme="light"] .cy-composer-in { background: linear-gradient(180deg, rgba(52, 58, 138, .8), rgba(36, 42, 108, .84)); }
.cy-composer textarea { width: 100%; min-height: 76px; resize: none; background: transparent; border: 0; outline: 0; display: block;
  color: var(--cy-ink); font-size: 16px; line-height: 1.55; font-weight: 420; letter-spacing: -.005em; padding: 18px 20px 6px; }
.cy-composer.compact textarea { min-height: 46px; padding: 13px 16px 2px; font-size: 14.5px; }
.cy-composer textarea::placeholder { color: var(--cy-ink4); }
.cy-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 10px 10px 12px; }
.cy-bar-l, .cy-bar-r { display: flex; align-items: center; gap: 4px; min-width: 0; }
.cy-bar-r { margin-left: auto; gap: 8px; }
.cy-bar-sep { width: 1px; height: 18px; background: var(--cy-line2); margin: 0 6px; }
.cy-tool { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: var(--cy-ink3); transition: color .15s, background .15s; }
.cy-tool:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-mic.on { color: #031319; background: linear-gradient(135deg, var(--cy-n1), var(--cy-n2)); box-shadow: 0 0 0 4px rgba(20, 197, 228, .2), 0 0 22px rgba(20, 197, 228, .55); animation: cy-mic 1.6s ease-in-out infinite; }
.cy-mic.unsupported { opacity: .5; }
.cy-pick { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 9px 0 10px; border-radius: 10px; font-size: 12.5px; font-weight: 550; color: var(--cy-ink2); white-space: nowrap; transition: background .15s, color .15s; }
.cy-pick:hover, .cy-pick[aria-expanded="true"] { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-pick-k { color: var(--cy-ink); }
.cy-pick-v { color: var(--cy-ink3); font-weight: 450; }
.cy-pick svg { color: var(--cy-ink4); }
.cy-spend { display: inline-flex; gap: 2px; align-items: flex-end; }
.cy-spend i { width: 3px; border-radius: 2px; background: var(--cy-line2); }
.cy-spend i:nth-child(1) { height: 6px; } .cy-spend i:nth-child(2) { height: 9px; } .cy-spend i:nth-child(3) { height: 12px; }
.cy-spend i.on { background: linear-gradient(var(--cy-n5), var(--cy-n3)); }
.cy-est { display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; color: var(--cy-ink3); white-space: nowrap; }
.cy-est-sep { opacity: .5; }
.cy-kbd-hint { font: 500 11px/1 var(--font-mono); color: var(--cy-ink4); }
.cy-go { position: relative; display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 16px 0 14px; border-radius: 11px; font-size: 13.5px; font-weight: 600; color: #fff; white-space: nowrap;
  background: linear-gradient(110deg, #2f7eef, #8c3ae9 60%, #b13fe6); background-size: 150% 100%;
  box-shadow: 0 10px 28px -12px rgba(120, 80, 255, .95), inset 0 1px 0 rgba(255,255,255,.22); transition: background-position .4s var(--cy-ease), transform .15s, opacity .2s, box-shadow .2s; }
.cy-go:hover:not(:disabled) { background-position: 100% 0; transform: translateY(-1px); box-shadow: 0 14px 32px -12px rgba(140, 90, 255, 1), inset 0 1px 0 rgba(255,255,255,.3); }
.cy-go:disabled { opacity: .4; box-shadow: none; }
.cy-composer-msg { padding: 10px 8px 0; font-size: 12.5px; line-height: 1.5; text-align: center; text-shadow: 0 1px 16px rgba(4,6,26,.9); }
.cy-composer.compact .cy-composer-msg { text-align: left; }
.cy-composer-msg .bad { color: #ff9ab6; font-weight: 550; }
.cy-composer-msg .warn { color: var(--cy-warn); }
