.cy-atts { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 14px 16px 0; }
.cy-att { position: relative; width: 60px; height: 60px; border-radius: 12px; overflow: hidden; border: 1px solid var(--cy-line2); background: var(--cy-raise); animation: cy-pop .35s cubic-bezier(.2,.9,.3,1.3) both; }
.cy-att img { width: 100%; height: 100%; object-fit: cover; }
