.cy-att-veil.err { background: rgba(120, 10, 40, .55); }
.cy-att.err { border-color: var(--cy-bad); }
.cy-att-note { flex: 1 1 200px; display: inline-flex; align-items: center; gap: 6px; font-size: 12px; line-height: 1.45; color: #9fe9f7; }
