.cy-wave i { width: 3px; height: 40px; border-radius: 3px; transform: scaleY(.15); background: linear-gradient(var(--cy-n1), var(--cy-n2) 45%, var(--cy-n3) 80%, var(--cy-n5)); box-shadow: 0 0 8px rgba(20, 197, 228, .5); }
