.cy-pop { position: relative; display: inline-flex; }
.cy-pop-back { display: none; }
.cy-pop-panel { position: absolute; bottom: calc(100% + 10px); left: 0; z-index: 60; width: 340px; }
.cy-panel { display: flex; flex-direction: column; gap: 4px; padding: 8px; border-radius: 16px; background: var(--cy-pop); animation: cy-in .18s var(--cy-ease) both; }
.cy-panel-h { display: flex; align-items: center; gap: 8px; font: 600 9.5px/1 var(--font-mono); letter-spacing: .16em; text-transform: uppercase; color: var(--cy-ink4); padding: 8px 8px 4px; }
.cy-panel-hn { letter-spacing: .02em; text-transform: none; font-family: inherit; font-weight: 500; }
