describe("cyrus web scenes", () => {
  const many = Array.from({ length: 11 }, (_, i) => view(`r${i}`, { createdAt: `2026-10-0${(i % 7) + 1}T00:00:00.000Z` }));
  it("home: at most 8 mods + versions as satellites, a ghost and template seeds", () => {
    const sc = homeScene(groupProjects(many), CYRUS_TEMPLATES);
    assert.equal(sc.mode, "home");
    assert.equal(sc.nodes.filter((n) => n.kind === "mod").length, 8);
    assert.equal(sc.nodes.filter((n) => n.kind === "ghost").length, 1);
    assert.equal(sc.nodes.filter((n) => n.kind === "seed").length, 8);
    const mods = new Set(sc.nodes.filter((n) => n.kind === "mod").map((n) => n.id));
    for (const v of sc.nodes.filter((n) => n.kind === "ver")) assert.ok(mods.has(v.parent!), "every version hangs off a mod on the web");
    assert.equal(modColor("r1"), modColor("r1"));
  });
  it("home: a running mod sorts first and carries its progress", () => {
    const ps = groupProjects([view("a"), view("b", { status: "coding", createdAt: "2026-10-01T00:00:00.000Z" })]);
    const sc = homeScene(ps, []);
    const run = sc.nodes.find((n) => n.id === "m:b")!;
    assert.equal(run.status, "running");
    assert.ok((run.progress ?? 0) > 0 && (run.progress ?? 0) < 1);
    assert.ok((run.weight ?? 0) > (sc.nodes.find((n) => n.id === "m:a")!.weight ?? 0));
  });
  it("project: files become orbs, plugin.yml carries commands + permissions, config keys hang off config.yml", () => {
