        permissions: [{ node: "heal.use", description: "Use it", default: "true" }],
        config: [{ key: "cooldown", description: "Seconds", default: "60" }],
      },
    });
    const [p] = groupProjects([b]);
    const sc = projectScene(p, b, webFiles(b.result!.files));
    assert.deepEqual(sc.nodes.filter((n) => n.kind === "file" || n.kind === "res").map((n) => n.label), ["HealPlus", "plugin.yml", "config.yml"]);
    assert.equal(sc.nodes.find((n) => n.kind === "cmd")!.parent, "f:src/main/resources/plugin.yml");
    assert.equal(sc.nodes.find((n) => n.kind === "perm")!.parent, "f:src/main/resources/plugin.yml");
    assert.equal(sc.nodes.find((n) => n.kind === "cfg")!.parent, "f:src/main/resources/config.yml");
    assert.equal(sc.nodes.find((n) => n.label === "HealPlus")!.weight, 3, "the main class is a key file");
    assert.deepEqual(sc.stage, { status: "succeeded", repairs: 0, seen: ["coding"] });
