private fitK = 1;
private userMoved = false;
private trans: { t0: number; dur: number; from: N | null; next: WebScene } | null = null;

// activity
private energy = 0; private energyS = 0;
private emitAcc = 0;
private scanR = -1;
private bloomT = -1;
private focusId: string | null = null;
private showSats = false;

// interaction
private hovered: N | null = null;
private pointer = { x: 0, y: 0, px: 0, py: 0 };
private pointers = new Map<number, P>();
private drag: { mode: "pan" | "pinch"; sx: number; sy: number; moved: boolean; camX: number; camY: number; dist?: number; k0?: number; node?: N | null } | null = null;
private captionEl: HTMLElement | null = null;
private captionDy = 0;
private hoverEl: HTMLElement | null = null;
private ro: ResizeObserver;
private io: IntersectionObserver | null = null;
private mo: MutationObserver | null = null;

constructor(canvas: HTMLCanvasElement, cb: WebCallbacks = {}) {
  this.canvas = canvas;
  this.ctx = canvas.getContext("2d", { alpha: false })!;
  this.cb = cb;
  this.reduced = typeof matchMedia !== "undefined" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  this.core = this.mkNode({ id: "__core", kind: "core", label: "Cyrus", color: "#8c3ae9" });
  this.core.alpha = 1;
  try {
    const cs = getComputedStyle(document.body);
    if (cs.fontFamily) this.font = cs.fontFamily;
    const m = getComputedStyle(document.documentElement).getPropertyValue("--font-mono").trim();
    if (m) this.mono = m;
  } catch { /* defaults */ }
  this.readTheme();
  this.ro = new ResizeObserver(() => this.resize());
  this.ro.observe(canvas);
  if (typeof IntersectionObserver !== "undefined") {
    this.io = new IntersectionObserver((es) => { this.visible = es.some((e) => e.isIntersecting); if (this.visible) this.start(); else this.stop(); });
    this.io.observe(canvas);
  }
  this.mo = new MutationObserver(() => this.readTheme());
  this.mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme", "class"] });
  this.resize();
  this.makeStars();
  this.buildWeb();
  this.bind();
  document.addEventListener("visibilitychange", this.onVis);
  document.fonts?.ready.then(() => { this.labels.clear(); this.dirty = true; }).catch(() => {});
  this.start();
}

// ------------------------------------------------------------------ API --
/** Replace the scene. Same key = in-place update (nodes animate); new key = fly-through transition. */
setScene(scene: WebScene, opts: { fromId?: string } = {}) {
  const prev = this.scene;
  // an update for the scene we are already flying to: just swap the payload
  if (this.trans && this.trans.next.key === scene.key) { this.trans.next = scene; return; }
  // changed course mid-flight (e.g. back pressed): land straight on the new scene
  if (this.trans) { this.trans = null; this.core.alpha = 1; this.apply(scene, true); return; }
  if (prev && prev.key !== scene.key && !this.reduced) {
    const from = opts.fromId ? this.byId.get(opts.fromId) ?? null : null;
    this.trans = { t0: performance.now(), dur: 520, from, next: scene };
    for (const n of [...this.nodes, ...this.sats]) n.dying = true;
    this.userMoved = false;
    const t = TILT[scene.mode];
    if (from) this.animateTo({ x: from.x, y: from.y, k: this.cam.k * 2.1, t }, 520);
    else this.animateTo({ x: this.cam.x, y: this.cam.y, k: this.cam.k * 0.82, t }, 520);
    this.dirty = true;
    return;
  }
  this.apply(scene, !prev || prev.key !== scene.key);
}

/** Screen box (canvas px) the web should be fitted into; coreY = where the core sits (0..1 of the box). */
setRegion(r: { x: number; y: number; w: number; h: number; coreY?: number; fit?: "inner" | "all" }) {
  const n = { x: r.x, y: r.y, w: Math.max(80, r.w), h: Math.max(80, r.h), coreY: r.coreY ?? 0.5, fit: r.fit ?? "all" };
  const o = this.region;
  if (o.fit === n.fit && Math.abs(o.x - n.x) + Math.abs(o.y - n.y) + Math.abs(o.w - n.w) + Math.abs(o.h - n.h) + Math.abs(o.coreY - n.coreY) * 100 < 2) return;
  this.region = n;
  if (!this.userMoved) this.fit(!this.scene || this.reduced);
}

/** Composer activity 0..1 (typing bursts, live mic level). */
setEnergy(e: number) { this.energy = Math.max(0, Math.min(1, e)); }
setFocus(id: string | null) { if (this.focusId !== id) { this.focusId = id; this.dirty = true; } }
setSatellites(on: boolean) { this.showSats = on; this.dirty = true; }
setTheme(t: WebTheme) { if (t !== this.theme) { this.theme = t; this.bg = null; this.dirty = true; } }

/** Light from the core to a node (or inward from it). Unknown id = along a random spoke. */
emit(id: string | null, o: { count?: number; rgb?: Rgb; size?: number; inward?: boolean } = {}) {
  const n = id ? this.byId.get(id) : undefined;
  if (n) { n.flash = Math.min(1.4, n.flash + 0.35); }
  if (this.reduced) { this.dirty = true; return; }
  const st = n ? (n.owner ? this.satStrands.find((s) => s.node === n) : this.strands.find((s) => s.node === n)) : this.spokes[Math.floor(Math.random() * this.spokes.length)];
  if (!st) return;
  const c = o.count ?? 1;
  for (let i = 0; i < c; i++) this.spawn(st, o.inward ? -1 : 1, o.rgb ?? (n ? n.rgb : HOT_V), o.size ?? 1, -i * 0.07);
}
/** Compiling: light flows inward from every file to the core. */
gather() {
  if (this.reduced) return;
  for (const s of this.strands) if (s.node && (s.node.kind === "file" || s.node.kind === "res")) this.spawn(s, -1, s.node.rgb, 1, -Math.random() * 0.3);
}
/** Safety check: a scan ring sweeps outward over every node. */
scan() { this.scanR = this.reduced ? -1 : 0; this.dirty = true; }
/** Success: one bloom from the core. */
bloom() {
  this.core.flash = 1.4;
  for (const n of this.nodes) n.flash = Math.max(n.flash, 0.7);
  if (this.reduced) { this.dirty = true; return; }
  this.bloomT = 0;
  this.core.ripples.push(0, -0.25);
  for (const s of this.strands) this.spawn(s, 1, s.node?.rgb ?? HOT_V, 1.2, -Math.random() * 0.2);
}
ripple(id: string | null) {
  const n = id ? this.byId.get(id) : this.core;
  if (!n) return;
  n.flash = Math.min(1.4, n.flash + 0.6);
  if (!this.reduced) { n.ripples.push(0); if (n.ripples.length > 4) n.ripples.shift(); }
  this.dirty = true;
}

zoomBy(f: number) { this.userMoved = true; this.zoomAt(this.W / 2, this.H / 2, f); }
fit(instant = false) {
  const g = this.region;
  const t = TILT[this.scene?.mode ?? "home"];
  // "inner": the first ring (+ labels) must fit the box, outer rings may run behind the UI.
  const R = g.fit === "inner" ? this.innerR + 36 : this.ringMax + (this.sats.length ? 120 : 64);
  const k = Math.max(0.3, Math.min(1.7, (Math.min(g.w / 2, (g.h / 2) / t) / R) * 0.97));
  this.fitK = k;
  // world (0,0) at screen (g.x + g.w/2, g.y + g.h*coreY)
  const sx = g.x + g.w / 2, sy = g.y + g.h * g.coreY;
  const to = { k, t, x: -(sx - this.W / 2) / k, y: -(sy - this.H / 2) / (k * t) };
  this.animateTo(to, instant ? 0 : 750);
}
recenter() { this.userMoved = false; this.fit(); }

/** An element kept centred under the core (stage caption). dy = px below the core's rim. */
pinCaption(el: HTMLElement | null, dy = 34) { this.captionEl = el; this.captionDy = dy; this.dirty = true; }
/** The hover card; the engine positions it next to the hovered node every frame. */
pinHover(el: HTMLElement | null) { this.hoverEl = el; }
coreScreen() { return this.screenPos(this.core); }

dispose() {
  this.disposed = true;
  this.stop();
  this.ro.disconnect();
  this.io?.disconnect();
  this.mo?.disconnect();
  document.removeEventListener("visibilitychange", this.onVis);
  this.unbind();
}

// ------------------------------------------------------------- scene ----
private mkNode(spec: WebNodeSpec): N {
  const k = spec.kind;
  const r = k === "core" ? CORE_R : k === "mod" ? 20 : k === "file" ? 15 : k === "res" ? 13 : k === "ghost" ? 14 : k === "seed" ? 9 : k === "ver" ? 5 : 4;
  return {
    spec, id: spec.id, kind: k, rgb: hexRgb(spec.color), r, x: 0, y: 0, tx: 0, ty: 0,
    phase: (hashStr(spec.id) % 1000) / 1000 * TAU, flash: 0, ripples: [], born: this.time, alpha: 0, dying: false,
    slot: 0, slots: 1, expand: 0, holdUntil: 0, vis: 0, ring: 0,
  };
}

private apply(scene: WebScene, fresh: boolean) {
  this.scene = scene;
  this.core.spec = { id: "__core", kind: "core", label: scene.core.label, color: scene.core.color, glyph: scene.core.glyph };
  this.core.rgb = hexRgb(scene.core.color);
  const prev = fresh ? new Map<string, N>() : this.byId;
  const ring: N[] = [];
  const sats: N[] = [];
  const t = this.time;
  let stagger = 0;
  for (const spec of scene.nodes) {
    let n = prev.get(spec.id);
    if (!n || n.kind !== spec.kind) {
      n = this.mkNode(spec);
      n.born = t + (fresh && !this.reduced ? 0.12 + stagger * 0.045 : 0);
      stagger++;
    }
    n.spec = spec; n.rgb = hexRgb(spec.color); n.dying = false;
    (isSat(spec.kind) ? sats : ring).push(n);
  }
  this.layout(scene, ring, sats, fresh);
  this.nodes = ring;
  this.sats = sats;
  this.byId = new Map([...ring, ...sats].map((n) => [n.id, n]));
  this.byId.set("__core", this.core);
  for (const s of sats) s.owner = s.spec.parent ? this.byId.get(s.spec.parent) : undefined;
  const bySlot = new Map<string, N[]>();
  for (const s of sats) if (s.owner) { const l = bySlot.get(s.owner.id) || []; l.push(s); bySlot.set(s.owner.id, l); }
  for (const l of bySlot.values()) l.forEach((s, i) => { s.slot = i; s.slots = l.length; });
  this.sats = sats.filter((s) => s.owner);

  const old = new Map(this.strands.map((s) => [s.node!.id, s]));
  this.strands = ring.map((n) => old.get(n.id) && old.get(n.id)!.node === n ? old.get(n.id)! : { a: this.core, b: n, phase: n.phase, cx: 0, cy: 0, len: 0, kind: "core" as const, node: n });
  this.satStrands = this.sats.map((n) => ({ a: n.owner!, b: n, phase: n.phase, cx: 0, cy: 0, len: 0, kind: "sat" as const, node: n }));
  const live = new Set<Strand>([...this.strands, ...this.satStrands, ...this.spokes]);
  this.pulses = this.pulses.filter((p) => live.has(p.s));
  this.buildWeb();
  if (fresh) {
    this.userMoved = false;
    this.fit(true);
    if (!this.reduced) { const to = { ...this.target }; this.cam = { x: to.x, y: to.y, k: to.k * 1.55, t: this.cam.t }; this.animateTo(to, 900); }
  }
  this.dirty = true;
}

private layout(scene: WebScene, ring: N[], sats: N[], fresh: boolean) {
  const rings: N[][] = [];
  const add = (list: N[], first: number, step: number, cap0: number, capStep: number) => {
    let r = 0, cap = cap0, i = 0;
    for (const n of list) {
      if (!rings[first + r]) rings[first + r] = [];
      rings[first + r].push(n);
      n.ring = first + r;
      if (++i >= cap) { r++; i = 0; cap += capStep; }
    }
    void step;
    return first + (i === 0 ? r : r + 1);
  };
  let radius = (ri: number) => 175 + ri * 118;
  if (scene.mode === "home") {
    const mods = ring.filter((n) => n.kind === "mod").sort((a, b) => (b.spec.weight ?? 0) - (a.spec.weight ?? 0));
    const ghost = ring.filter((n) => n.kind === "ghost");
    const seeds = ring.filter((n) => n.kind === "seed");
    // one calm ring of mods (+ the ghost); seeds scattered on the ring outside it
    const next = add([...mods, ...ghost], 0, 0, 9, 7);
    add(seeds, Math.max(next, 1), 0, 12, 12);
  } else {
    // Java classes on the inner ring (big enough that labels never touch), resources outside.
    const java = ring.filter((n) => n.kind === "file");
    const res = ring.filter((n) => n.kind === "res");
    const one = java.length + res.length <= 6;
    const r0 = Math.max(150, ((one ? java.length + res.length : java.length) * 142) / TAU);
    radius = (ri: number) => (ri === 0 ? r0 : r0 + 112 * ri);
    if (one) add([...java, ...res], 0, 0, 99, 0);
    else { add(java, 0, 0, 99, 0); add(res, 1, 0, 99, 0); }
  }
  let maxR = 0;
  const key = scene.key;
  rings.forEach((list, ri) => {
    if (!list) return;
    const R = radius(ri);
    maxR = Math.max(maxR, R);
    const off = ((hashStr(key + ":" + ri) % 1000) / 1000) * TAU;
    list.forEach((n, i) => {
      // seeds avoid a strict even spread: a little jitter reads as "scattered seeds"
      const jitter = n.kind === "seed" ? ((hashStr(n.id) % 100) / 100 - 0.5) * 0.18 : 0;
      const a = off + (i / list.length) * TAU + jitter;
      const rr = R * (n.kind === "seed" ? 1.0 + ((hashStr(n.id + "r") % 100) / 100) * 0.12 : 1);
      n.tx = Math.cos(a) * rr; n.ty = Math.sin(a) * rr;
    });
  });
  // relax overlaps (targets only; deterministic)
  const all = ring;
  for (let it = 0; it < 40; it++) {
    for (let i = 0; i < all.length; i++) for (let j = i + 1; j < all.length; j++) {
      const a = all[i], b = all[j];
      const dx = b.tx - a.tx, dy = b.ty - a.ty, d = Math.hypot(dx, dy) || 0.01;
      const min = a.r + b.r + 62;
      if (d < min) { const f = (min - d) / 2 / d; a.tx -= dx * f; a.ty -= dy * f; b.tx += dx * f; b.ty += dy * f; }
    }
    for (const n of all) { const d = Math.hypot(n.tx, n.ty); if (d < 120) { const f = 120 / (d || 1); n.tx *= f; n.ty *= f; } }
  }
  for (const n of all) if (fresh || (n.x === 0 && n.y === 0)) { n.x = n.tx * 0.08; n.y = n.ty * 0.08; }
  for (const s of sats) if (fresh) { s.x = 0; s.y = 0; }

private sprite(rgb: Rgb, key = "p") {
  const id = key + rgb.join(",");
  let c = this.sprites.get(id);
  if (!c) {
    c = document.createElement("canvas");
    const S = key === "h" ? 128 : 64;
    c.width = c.height = S;
    const g = c.getContext("2d")!;
    const gr = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
    if (key === "h") { gr.addColorStop(0, rgba(rgb, 0.5)); gr.addColorStop(0.32, rgba(rgb, 0.17)); gr.addColorStop(1, rgba(rgb, 0)); }
    else { gr.addColorStop(0, "rgba(255,255,255,1)"); gr.addColorStop(0.13, rgba(mix(rgb, [255, 255, 255], 0.35), 0.95)); gr.addColorStop(0.42, rgba(rgb, 0.26)); gr.addColorStop(1, rgba(rgb, 0)); }
    g.fillStyle = gr; g.fillRect(0, 0, S, S);
    this.sprites.set(id, c);
  }
  return c;
}

private labelSprite(text: string, size: number, color: string, weight: number) {
  const key = `${text}|${size}|${color}|${weight}|${this.dpr}`;
  let c = this.labels.get(key);
  if (c) return c;
  if (this.labels.size > 400) this.labels.clear();
  const d = this.dpr;
  const m = document.createElement("canvas").getContext("2d")!;
  const font = `${weight} ${size}px ${this.font}`;
  m.font = font;
  const w = Math.ceil(m.measureText(text).width) + 16;
  const h = Math.ceil(size * 1.5) + 12;
  c = document.createElement("canvas");
  c.width = w * d; c.height = h * d;
  const g = c.getContext("2d")!;
  g.scale(d, d);
  g.font = font; g.textBaseline = "middle"; g.textAlign = "center";
  g.shadowColor = "rgba(2,4,20,0.95)"; g.shadowBlur = 7;
  g.fillStyle = color;
  g.fillText(text, w / 2, h / 2);
  g.shadowBlur = 0;
  g.fillText(text, w / 2, h / 2);
  this.labels.set(key, c);
  return c;
}

private resize() {
  const r = this.canvas.getBoundingClientRect();
  this.W = Math.max(1, r.width); this.H = Math.max(1, r.height);
  let dpr = Math.min(2, window.devicePixelRatio || 1);
  if (this.W * this.H * dpr * dpr > 4.6e6) dpr = Math.max(1, Math.sqrt(4.6e6 / (this.W * this.H)));
  this.dpr = dpr;
  this.canvas.width = Math.round(this.W * dpr);
  this.canvas.height = Math.round(this.H * dpr);
  this.bg = null;
  this.labels.clear();
  this.dirty = true;
  if (!this.userMoved && this.scene) this.fit(true);
  if (this.reduced || !this.running) this.frame(performance.now());
}

private onVis = () => { if (document.hidden) this.stop(); else if (this.visible) this.start(); };
private start() {
  if (this.running || this.disposed) return;
  this.running = true; this.last = performance.now();
  this.raf = requestAnimationFrame(this.loop);
}
private stop() { this.running = false; cancelAnimationFrame(this.raf); }
private loop = (now: number) => {
  if (!this.running) return;
  this.frame(now);
  this.raf = requestAnimationFrame(this.loop);
};

private animateTo(to: Cam, dur: number, done?: () => void) {
  if (dur <= 0 || this.reduced) { this.cam = { ...to }; this.target = { ...to }; this.tween = null; this.dirty = true; done?.(); return; }
  this.tween = { from: { ...this.cam }, to, t0: performance.now(), dur, done };
  this.target = { ...to };
}
private zoomAt(sx: number, sy: number, f: number) {
  const k0 = this.target.k;
  const k1 = Math.max(0.25, Math.min(4.5, k0 * f));
  const wx = (sx - this.W / 2) / k0 + this.target.x;
  const wy = (sy - this.H / 2) / (k0 * this.target.t) + this.target.y;
  this.target = { ...this.target, k: k1, x: wx - (sx - this.W / 2) / k1, y: wy - (sy - this.H / 2) / (k1 * this.target.t) };
  this.tween = null;
  if (this.reduced) this.cam = { ...this.target };
  this.dirty = true;
}
private ox() { return -this.pointer.px * 6; }
private oy() { return -this.pointer.py * 5; }
private screenPos(n: P) { return { x: (n.x - this.cam.x) * this.cam.k + this.W / 2 + this.ox(), y: (n.y - this.cam.y) * this.cam.k * this.cam.t + this.H / 2 + this.oy() }; }
/** Draw `fn` upright at n (undo the disc tilt for billboards: orbs, halos, glyphs). */
private upright(n: P, fn: () => void) {
  const t = this.cam.t;
  if (Math.abs(t - 1) < 0.001) { fn(); return; }
  const { ctx } = this;
  ctx.save(); ctx.translate(n.x, n.y); ctx.scale(1, 1 / t); ctx.translate(-n.x, -n.y);
  fn();
  ctx.restore();
}

private hit(sx: number, sy: number): N | null {
  let best: N | null = null, bd = Infinity;
  const k = this.cam.k;
  for (const n of this.sats) {
    if (n.vis < 0.55) continue;
    const p = this.screenPos(n);
    const d = Math.hypot(p.x - sx, p.y - sy);
    if (d < n.r * k + 7 && d < bd) { bd = d; best = n; }
  }
  if (best) return best;
  for (const n of [...this.nodes, this.core]) {
    if (n.alpha < 0.5) continue;
    const p = this.screenPos(n);
    const d = Math.hypot(p.x - sx, p.y - sy);
    if (d < n.r * k + 9 && d < bd) { bd = d; best = n; }
  }
  return best;
}
private setHover(n: N | null) {
  if (n === this.hovered) return;
  this.hovered = n;
  this.canvas.style.cursor = n && n.kind !== "core" ? "pointer" : this.drag ? "grabbing" : "grab";
  this.cb.onHover?.(n && n.kind !== "core" ? n.spec : null);
  this.dirty = true;
}

private bind() {
  const c = this.canvas;
  c.addEventListener("pointerdown", this.onDown);
  window.addEventListener("pointermove", this.onMove);
  window.addEventListener("pointerup", this.onUp);
  window.addEventListener("pointercancel", this.onUp);
  c.addEventListener("wheel", this.onWheel, { passive: false });
  c.addEventListener("dblclick", this.onDbl);
  c.addEventListener("pointerleave", this.onLeave);
  c.style.cursor = "grab";
  c.style.touchAction = "none";
}
private unbind() {
  const c = this.canvas;
  c.removeEventListener("pointerdown", this.onDown);
  window.removeEventListener("pointermove", this.onMove);
  window.removeEventListener("pointerup", this.onUp);
  window.removeEventListener("pointercancel", this.onUp);
  c.removeEventListener("wheel", this.onWheel);
  c.removeEventListener("dblclick", this.onDbl);
  c.removeEventListener("pointerleave", this.onLeave);
}
private local(e: { clientX: number; clientY: number }) { const r = this.canvas.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
private onDown = (e: PointerEvent) => {
  const p = this.local(e);
  this.pointers.set(e.pointerId, p);
  try { this.canvas.setPointerCapture(e.pointerId); } catch { /* noop */ }
  if (this.pointers.size === 2) {
    const [a, b] = [...this.pointers.values()];
    this.drag = { mode: "pinch", sx: (a.x + b.x) / 2, sy: (a.y + b.y) / 2, moved: true, camX: this.cam.x, camY: this.cam.y, dist: Math.hypot(a.x - b.x, a.y - b.y), k0: this.target.k };
    return;
  }
  this.tween = null;
  this.drag = { mode: "pan", sx: p.x, sy: p.y, moved: false, camX: this.target.x, camY: this.target.y, node: this.hit(p.x, p.y) };
};
private onMove = (e: PointerEvent) => {
  const p = this.local(e);
  this.pointer.x = Math.max(-1, Math.min(1, (p.x / this.W) * 2 - 1));
  this.pointer.y = Math.max(-1, Math.min(1, (p.y / this.H) * 2 - 1));
  if (this.pointers.has(e.pointerId)) this.pointers.set(e.pointerId, p);
  const d = this.drag;
  if (!d) { if (e.target === this.canvas) this.setHover(this.hit(p.x, p.y)); return; }
  if (d.mode === "pinch" && this.pointers.size >= 2) {
    const [a, b] = [...this.pointers.values()];
    const dist = Math.hypot(a.x - b.x, a.y - b.y);
    const k1 = Math.max(0.25, Math.min(4.5, (d.k0 || 1) * (dist / (d.dist || dist))));
    this.userMoved = true;
    this.zoomAt((a.x + b.x) / 2, (a.y + b.y) / 2, k1 / this.target.k);
    this.cam = { ...this.target };
    return;
  }
  const dx = p.x - d.sx, dy = p.y - d.sy;
  if (!d.moved && Math.hypot(dx, dy) > 4) { d.moved = true; this.canvas.style.cursor = "grabbing"; }
  if (!d.moved) return;
  this.userMoved = true;
  this.target.x = d.camX - dx / this.cam.k; this.target.y = d.camY - dy / (this.cam.k * this.cam.t);
  this.cam.x = this.target.x; this.cam.y = this.target.y;
  this.dirty = true;
};
private onUp = (e: PointerEvent) => {
  this.pointers.delete(e.pointerId);
  const d = this.drag;
  if (!d) return;
  if (d.mode === "pinch") { if (this.pointers.size === 0) this.drag = null; return; }
  this.drag = null;
  this.canvas.style.cursor = this.hovered ? "pointer" : "grab";
  if (!d.moved && d.node && d.node.kind !== "core") this.cb.onOpen?.(d.node.spec);
};
private onLeave = () => { if (!this.drag) this.setHover(null); this.pointer.x = 0; this.pointer.y = 0; };
private onWheel = (e: WheelEvent) => {
  e.preventDefault();
  const p = this.local(e);
  const delta = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
  this.userMoved = true;
  this.zoomAt(p.x, p.y, Math.exp(-delta * (e.ctrlKey ? 0.01 : 0.0015)));
};
private onDbl = (e: MouseEvent) => {
  const p = this.local(e);
  const n = this.hit(p.x, p.y);
  if (n && n.kind !== "core") return;
  this.recenter();
};

// ------------------------------------------------------------- frame ----
private frame(now: number) {
  const dt = Math.min(0.05, (now - this.last) / 1000);
  this.last = now;
  const anim = !this.reduced;
  if (anim) this.time += dt;

  // scene transition
  if (this.trans) {
    const u = Math.min(1, (now - this.trans.t0) / this.trans.dur);
    const from = this.trans.from;
    for (const n of [...this.nodes, ...this.sats]) {
      n.alpha = Math.max(0, n.alpha - dt * 3.2);
      if (n !== from) { n.x += (0 - n.x) * Math.min(1, dt * 3); n.y += (0 - n.y) * Math.min(1, dt * 3); }
    }
    this.core.alpha = from ? Math.max(0, 1 - u * 1.6) : 1 - u * 0.4;
    this.dirty = true;
    if (u >= 1) { const next = this.trans.next; this.trans = null; this.core.alpha = 1; this.apply(next, true); }
  }

  // camera
  if (this.tween) {
    const u = Math.min(1, (now - this.tween.t0) / this.tween.dur);
    const e = EASE(u);
    const { from, to } = this.tween;
    this.cam.k = from.k * Math.pow(to.k / from.k, e);
    this.cam.x = from.x + (to.x - from.x) * e; this.cam.y = from.y + (to.y - from.y) * e;
    this.cam.t = from.t + (to.t - from.t) * e;
    this.dirty = true;
    if (u >= 1) { const d = this.tween.done; this.tween = null; d?.(); }
  } else {
    const f = 1 - Math.exp(-dt * 12);
    const dx = this.target.x - this.cam.x, dy = this.target.y - this.cam.y, dk = this.target.k - this.cam.k, dt2 = this.target.t - this.cam.t;
    if (Math.abs(dx) + Math.abs(dy) > 0.01 || Math.abs(dk) > 0.0005 || Math.abs(dt2) > 0.0005) { this.cam.x += dx * f; this.cam.y += dy * f; this.cam.k += dk * f; this.cam.t += dt2 * f; this.dirty = true; }
  }
  // pointer parallax (smoothed)
  const pf = 1 - Math.exp(-dt * 3);
  this.pointer.px += (this.pointer.x - this.pointer.px) * pf;
  this.pointer.py += (this.pointer.y - this.pointer.py) * pf;
  this.energyS += (this.energy - this.energyS) * (1 - Math.exp(-dt * 6));

  if (!this.trans) {
    // nodes ease to their targets (with a gentle drift), fade in after `born`
    const f = this.reduced ? 1 : 1 - Math.exp(-dt * 3.2);
    for (const n of this.nodes) {
      const drift = anim ? 3.5 : 0;
      const gx = n.tx + Math.sin(this.time * 0.31 + n.phase) * drift, gy = n.ty + Math.cos(this.time * 0.27 + n.phase * 1.3) * drift;
      if (this.reduced || this.time >= n.born) {
        n.x += (gx - n.x) * f; n.y += (gy - n.y) * f;
        n.alpha = Math.min(1, n.alpha + (this.reduced ? 1 : dt * 2.6));
      }
    }
    this.layoutSats(dt);
  }

  if (anim) {
    this.updatePulses(dt);
    for (const n of [this.core, ...this.nodes, ...this.sats]) {
      if (n.flash > 0) n.flash = Math.max(0, n.flash - dt * 0.9);
      if (n.ripples.length) n.ripples = n.ripples.map((r) => r + dt).filter((r) => r < 1.6);
    }
    if (this.scanR >= 0) {
      const prevR = this.scanR;
      this.scanR += dt * 260;
      for (const n of this.nodes) { const d = Math.hypot(n.x, n.y); if (d > prevR && d <= this.scanR) n.flash = Math.max(n.flash, 0.9); }
      if (this.scanR > this.outerR * 1.2) this.scanR = -1;
    }
    if (this.bloomT >= 0) { this.bloomT += dt; if (this.bloomT > 1.8) this.bloomT = -1; }
    this.dirty = true;
  }
  if (!this.dirty) return;
  this.dirty = false;
  this.draw();
}

private layoutSats(dt: number) {
  const zoomOpen = this.cam.k > Math.max(1.35, this.fitK * 1.4);
  const hov = this.hovered;
  const clock = performance.now() / 1000;
  const projectMode = this.scene?.mode === "project";
  const f = this.reduced ? 1 : 1 - Math.exp(-dt * 7);
  const owners = new Set(this.sats.map((s) => s.owner!));
  for (const o of owners) {
    const engaged = hov === o || hov?.owner === o || this.focusId === o.id;
    if (engaged) o.holdUntil = clock + 0.9;
    const target = projectMode || this.showSats || zoomOpen || engaged || o.holdUntil > clock ? 1 : 0;
    const v = o.alpha * target;
    if (Math.abs(v - o.expand) > 0.001) { o.expand += (v - o.expand) * f; this.dirty = true; } else o.expand = v;
  }
  const t = this.reduced ? 0 : this.time;
  for (const s of this.sats) {
    const o = s.owner!;
    s.vis = o.expand * (this.reduced || this.time >= s.born ? 1 : 0);
    s.alpha = s.vis;
    const out = Math.hypot(o.x, o.y) > 1 ? Math.atan2(o.y, o.x) : -Math.PI / 2;
    const n = Math.max(1, s.slots), i = s.slot;
    const spread = Math.min(projectMode ? 2.9 : 2.3, 0.42 * (n - 1) + (n > 1 ? 0.3 : 0));
    const a = out + (n > 1 ? -spread / 2 + (i * spread) / (n - 1) : 0) + Math.sin(t * 0.4 + s.phase) * 0.02;
    const tier = projectMode && n > 7 ? (i % 2 ? 26 : 0) : 0;
    const dist = o.r + 6 + s.vis * ((projectMode ? 52 : 34) + tier);
    s.x = o.x + Math.cos(a) * dist;
    s.y = o.y + Math.sin(a) * dist;
  }
}

private updatePulses(dt: number) {
  const home = this.scene?.mode === "home";
  // ambient: a slow trickle on the home web; running nodes keep their thread busy
  for (const s of this.strands) {
    const n = s.node!;
    if (n.alpha < 0.5) continue;
    const run = n.spec.status === "running" || n.spec.live;
    const rate = (home ? (n.kind === "seed" ? 0.006 : 0.028) : 0.012) + (run ? (n.spec.live ? 2.4 : 0.9) : 0);
    if (Math.random() < rate * dt) this.spawn(s, run ? 1 : Math.random() < 0.5 ? 1 : -1, n.spec.live ? HOT_C : n.rgb, run ? 1.1 : 0.75);
  }
  // composer energy (typing, voice) and the AI thinking (planning / repairing / waiting):
  // light runs out along the web's spokes
  const st = this.scene?.mode === "project" ? this.scene.stage?.status : null;
  const thinking = st === "planning" || st === "queued" ? 0.32 : st === "repairing" ? 0.4 : st === "compiling" || st === "scanning" ? 0.12 : 0;
  const e = Math.max(this.energyS, thinking);
  if (e > 0.02 && this.spokes.length) {
    this.emitAcc += e * dt * 9;
    while (this.emitAcc >= 1) {
      this.emitAcc -= 1;
      const s = this.spokes[Math.floor(Math.random() * this.spokes.length)];
      const rgb = st === "repairing" && this.energyS < thinking ? BRAND.warn : Math.random() < 0.5 ? HOT_V : HOT_C;
      this.spawn(s, 1, rgb, 0.7 + e * 0.6);
    }
  }
  const out: Pulse[] = [];
  for (const p of this.pulses) {
    p.t += p.speed * dt;
    if (p.t < 1.1) out.push(p);

      g.addColorStop(1, rgba(n.rgb, breathe * n.alpha));
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
      ctx.lineWidth = (n.spec.live ? 2 : 1.6) * hair; ctx.strokeStyle = g; ctx.stroke();
    }
    // satellite silk
    for (const s of this.satStrands) {
      const n = s.node!;
      if (n.vis < 0.04) continue;
      const on = hovRaw === n || hovRaw === n.owner;
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
      ctx.lineWidth = (on ? 1.3 : 0.8) * hair; ctx.strokeStyle = rgba(n.rgb, (on ? 0.6 : 0.24) * n.vis); ctx.stroke();
    }

    // pulses (additive light), drawn in screen space so they stay round on the tilted disc
    ctx.globalCompositeOperation = "lighter";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    for (const p of this.pulses) {
      const s = p.s;
      if (s.node && s.node.alpha < 0.1) continue;
      const vis = s.kind === "sat" ? s.node!.vis : s.kind === "spoke" ? 0.85 : 1;
      const dim = hov && s.node && s.node !== hov && s.kind !== "spoke" ? 0.45 : 1;
      const spr = this.sprite(p.rgb);
      const trail = k * p.size < 0.55 ? 1 : 4;
      for (let j = 0; j < trail; j++) {
        let t = p.t - j * 0.022;
        if (t < 0 || t > 1) continue;
        if (p.dir === -1) t = 1 - t;
        const u = 1 - t;
        const wx = u * u * s.a.x + 2 * u * t * s.cx + t * t * s.b.x;
        const wy = u * u * s.a.y + 2 * u * t * s.cy + t * t * s.b.y;
        const x = (wx - cam.x) * k + W / 2 + ox, y = (wy - cam.y) * k * cam.t + H / 2 + oy;
        const fadeEnds = s.kind === "spoke" ? Math.sin(Math.PI * Math.min(1, Math.max(0, t))) : 1;
        const sz = (j === 0 ? 14 : 10 - j * 2) * p.size * Math.min(1.25, Math.max(0.7, k));
        ctx.globalAlpha = (j === 0 ? 1 : 0.55 - j * 0.12) * dim * vis * fadeEnds;
        ctx.drawImage(spr, x - sz / 2, y - sz / 2, sz, sz);
      }
    }
    ctx.globalAlpha = 1;
    ctx.setTransform(worldT);

    // halos (additive)
    for (const n of this.nodes) {
      if (n.alpha < 0.05 || n.kind === "ghost" || n.kind === "seed") continue;
      const run = n.spec.status === "running" || n.spec.live;
      const breathe = run ? 1 + 0.2 * Math.sin(this.time * 2.6 + n.phase) : 1 + 0.05 * Math.sin(this.time * 0.9 + n.phase);
      let a = 0.26 + (run ? 0.45 : 0) + n.flash * 0.4 + (n === hov ? 0.25 : 0);
      let rgb = n.rgb;
      if (n.spec.status === "bad") { rgb = BRAND.bad; a = 0.22; }
      const size = (5.4 + n.flash * 1.6) * n.r * breathe;
      if (size * k < 10) continue;
      ctx.globalAlpha = Math.min(1, a) * n.alpha * (hov && hov !== n ? 0.55 : 1);
      this.upright(n, () => ctx.drawImage(this.sprite(rgb, "h"), n.x - size / 2, n.y - size / 2, size, size));
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = "source-over";

    // ripples + scan ring + bloom
    for (const n of [this.core, ...this.nodes]) for (const r of n.ripples) {
      if (r < 0) continue;
      const u = r / 1.6;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.r + u * (n === this.core ? 140 : 60), 0, TAU);
      ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(n === this.core ? HOT_V : n.rgb, 0.5 * (1 - u)); ctx.stroke();
    }
    if (this.scanR >= 0) {
      const u = this.scanR / (this.outerR * 1.2);
      ctx.beginPath(); ctx.arc(0, 0, this.scanR, 0, TAU);
      ctx.lineWidth = 2 * hair; ctx.strokeStyle = rgba(BRAND.cyan, 0.55 * (1 - u)); ctx.stroke();
      ctx.beginPath(); ctx.arc(0, 0, Math.max(0, this.scanR - 14), 0, TAU);
      ctx.lineWidth = 8 * hair; ctx.strokeStyle = rgba(BRAND.cyan, 0.08 * (1 - u)); ctx.stroke();
    }
    if (this.bloomT >= 0) {
      const u = this.bloomT / 1.8;
      const gr = CORE_R * (2 + u * 12);
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.55 * (1 - u);
      ctx.drawImage(this.sprite(HOT_V, "h"), -gr, -gr, gr * 2, gr * 2);
      ctx.globalAlpha = 1; ctx.globalCompositeOperation = "source-over";
    }

    // nodes
    this.labelQ = [];
    for (const n of this.nodes) {
      if (n.alpha < 0.02) continue;
      this.upright(n, () => {
        if (n.kind === "ghost") this.drawGhost(n, hov);
        else if (n.kind === "seed") this.drawSeed(n, hov);
        else this.drawOrb(n, hov);
      });
    }
    this.drawSats(hovRaw);
    this.drawCore();
    // the loom's centre is branded, quietly
    if (this.scene?.mode === "home" && this.core.alpha > 0.5) this.queueLabel(this.core, "C\u2009Y\u2009R\u2009U\u2009S", 0.7 * this.core.alpha, { r: CORE_R + 30, size: 10, weight: 600, color: "#b9c4ff" });

    // labels in screen space
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    for (const l of this.labelQ) {
      const spr = this.labelSprite(l.text, l.size, l.color, l.weight);
      const w = spr.width / dpr, h = spr.height / dpr;
      ctx.globalAlpha = l.alpha;
      ctx.drawImage(spr, Math.round(l.x - w / 2), Math.round(l.above ? l.y - h + 6 : l.y - 6), w, h);
    }
    ctx.globalAlpha = 1;
    this.positionPins();
  }

  private queueLabel(n: N, text: string, alpha: number, o: { color?: string; size?: number; weight?: number; above?: boolean; r?: number } = {}) {
    if (alpha < 0.03) return;
    const p = this.screenPos(n);
    const rr = (o.r ?? n.r) * this.cam.k;
    const above = !!o.above;
    const t = text.length > 26 ? text.slice(0, 25) + "…" : text;
    this.labelQ.push({ x: p.x, y: above ? p.y - rr - 6 : p.y + rr + 6, text: t, alpha, color: o.color ?? PALETTE[this.theme].labelInk, size: o.size ?? 12, weight: o.weight ?? 500, above });
  }

  private drawOrb(n: N, hov: N | null) {
    const { ctx } = this; const hair = 1 / this.cam.k; const t = this.time; const k = this.cam.k;
    const isHov = hov === n;
    const dim = hov && !isHov ? 0.6 : 1;
    const run = n.spec.status === "running" || n.spec.live;
    const bad = n.spec.status === "bad";
    const rgb = n.rgb;
    const grow = Math.min(1, n.alpha * 1.15);
    const breathe = run ? 1 + 0.05 * Math.sin(t * 2.6 + n.phase) : 1;
    const r = n.r * breathe * (0.6 + 0.4 * grow) + (isHov ? 2 : 0);
    ctx.globalAlpha = n.alpha * dim;
    // body: a dark glass bead with a soft top-left highlight (depth)
    const square = n.kind === "res";
    const shape = () => {
      ctx.beginPath();
      if (square) { const s = r * 0.92; const rad = s * 0.38; ctx.roundRect(n.x - s, n.y - s, s * 2, s * 2, rad); }
      else ctx.arc(n.x, n.y, r, 0, TAU);
    };
    shape();
    ctx.fillStyle = PALETTE[this.theme].body; ctx.fill();
    const hl = ctx.createRadialGradient(n.x - r * 0.35, n.y - r * 0.45, 0, n.x, n.y, r * 1.1);
    hl.addColorStop(0, rgba(mix(rgb, [255, 255, 255], 0.35), 0.34)); hl.addColorStop(0.55, rgba(rgb, 0.1)); hl.addColorStop(1, rgba(rgb, 0.02));
    ctx.fillStyle = hl; ctx.fill();
    ctx.lineWidth = (isHov ? 1.9 : 1.35) * hair;
    ctx.strokeStyle = rgba(bad ? BRAND.bad : rgb, 0.6 + (isHov ? 0.3 : 0) + n.flash * 0.25);
    ctx.stroke();
    if (r * k >= 7) {
      // inner ring
      ctx.beginPath();
      if (square) { const s = r * 0.92 - 3.2; ctx.roundRect(n.x - s, n.y - s, s * 2, s * 2, s * 0.34); } else ctx.arc(n.x, n.y, r - 3.4, 0, TAU);
      ctx.lineWidth = 0.6 * hair; ctx.strokeStyle = rgba(rgb, 0.22); ctx.stroke();
      if (n.spec.constellation) {
        // the mod's own constellation, scaled into the orb
        const c = constellation(n.spec.constellation);
        const sc = (r * 0.78) / 15;
        ctx.beginPath();
        for (const [a, b] of c.edges) { ctx.moveTo(n.x + c.pts[a].x * sc, n.y + c.pts[a].y * sc); ctx.lineTo(n.x + c.pts[b].x * sc, n.y + c.pts[b].y * sc); }
        ctx.lineWidth = 0.7 * hair; ctx.strokeStyle = "rgba(170,185,255,0.42)"; ctx.stroke();
        c.pts.forEach((p, i) => {
          const col = CONSTEL_RGB[(i + c.hue) % 3];
          const tw = this.reduced ? 1 : 0.75 + 0.25 * Math.sin(this.time * 1.7 + i * 1.3 + n.phase);
          ctx.beginPath(); ctx.arc(n.x + p.x * sc, n.y + p.y * sc, Math.max(0.6, p.s * sc * 0.9), 0, TAU);
          ctx.fillStyle = rgba(mix(col, [255, 255, 255], 0.25), 0.95 * tw); ctx.fill();
        });
      } else {
        const gl = n.spec.glyph ?? (n.spec.label[0] || "?").toUpperCase();
        ctx.fillStyle = rgba(mix(rgb, [255, 255, 255], 0.55), 0.92);
        ctx.font = `600 ${Math.max(6, r * (gl.length > 1 ? 0.62 : 0.78))}px ${gl.length > 1 ? this.mono : this.font}`;
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText(gl, n.x, n.y + r * 0.04);
      }
    }
    // running: progress ring / sweeping arcs + orbiters
    if (run) {
      const p = n.spec.progress;
      if (p !== undefined && n.kind === "mod") {
        ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(rgb, 0.16); ctx.stroke();
        ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, -Math.PI / 2, -Math.PI / 2 + TAU * Math.max(0.04, Math.min(1, p))); ctx.lineWidth = 1.8 * hair; ctx.strokeStyle = rgba(mix(rgb, [255, 255, 255], 0.25), 0.95); ctx.stroke();
      }
      if (!this.reduced) {
        ctx.beginPath(); ctx.arc(n.x, n.y, r + (p !== undefined ? 10 : 5), t * 2.2 + n.phase, t * 2.2 + n.phase + Math.PI * 0.6);
        ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(n.spec.live ? HOT_C : rgb, 0.8); ctx.stroke();
        for (let i = 0; i < 3; i++) {
          const a = -t * 1.3 + n.phase + (i / 3) * TAU;
          ctx.beginPath(); ctx.arc(n.x + Math.cos(a) * (r + 13), n.y + Math.sin(a) * (r + 13), 1.3 * Math.max(1, hair), 0, TAU);
          ctx.fillStyle = rgba(n.spec.live ? HOT_C : rgb, 0.8); ctx.fill();
        }
      }
    }
    if (bad) {
      ctx.save(); ctx.setLineDash([2 * hair, 3 * hair]);
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = 1.1 * hair; ctx.strokeStyle = rgba(BRAND.bad, 0.65); ctx.stroke(); ctx.restore();
    }
    ctx.globalAlpha = 1;
    // Project webs get busy: label the key files (main class, plugin.yml, config.yml), the one
    // being written, fresh arrivals and the hovered one; zoom in to read every label.
    const building = !!this.scene?.stage && !["succeeded", "failed"].includes(this.scene.stage.status);
    const fresh = building && this.time - n.born < 4.5;
    const showLabel = n.kind === "mod" ? isHov || k > 0.42 : isHov || this.focusId === n.id || n.spec.live || (n.spec.weight ?? 0) >= 3 || fresh || k > 1.3 || this.nodes.length <= 7;
    if (showLabel) this.queueLabel(n, n.spec.label, (isHov ? 1 : 0.86) * n.alpha * dim, { r: r + (run ? 10 : 2), size: n.kind === "mod" ? 12.5 : 12, weight: isHov ? 600 : 500, color: isHov ? "#ffffff" : undefined });
  }

  private drawGhost(n: N, hov: N | null) {
    const { ctx } = this; const hair = 1 / this.cam.k;
    const on = hov === n;
    ctx.globalAlpha = n.alpha;
    ctx.save();
    ctx.setLineDash([3 * hair, 3.5 * hair]); ctx.lineDashOffset = -this.time * 6;
    ctx.beginPath(); ctx.arc(n.x, n.y, n.r + (on ? 2 : 0), 0, TAU);
    ctx.fillStyle = on ? rgba(BRAND.violet, 0.16) : PALETTE[this.theme].body; ctx.fill();
    ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(HOT_V, on ? 0.95 : 0.5); ctx.stroke();
    ctx.restore();
    ctx.beginPath();
    ctx.moveTo(n.x - 5, n.y); ctx.lineTo(n.x + 5, n.y); ctx.moveTo(n.x, n.y - 5); ctx.lineTo(n.x, n.y + 5);
    ctx.lineWidth = 1.6 * hair; ctx.strokeStyle = rgba(HOT_V, on ? 1 : 0.75); ctx.stroke();
    ctx.globalAlpha = 1;
    this.queueLabel(n, n.spec.label, (on ? 1 : 0.62) * n.alpha, { color: on ? "#ffffff" : PALETTE[this.theme].labelDim, size: 12 });
  }

  private drawSeed(n: N, hov: N | null) {
    // A template seed: a small spark with a hairline ring (not a hole); opens up on hover.
    const { ctx } = this; const hair = 1 / this.cam.k;
    const on = hov === n || this.focusId === n.id;
    const tw = this.reduced ? 1 : 0.7 + 0.3 * Math.sin(this.time * 1.3 + n.phase);
    ctx.globalAlpha = n.alpha;
    ctx.globalCompositeOperation = "lighter";
    const s = n.r * (on ? 8 : 4.5);
    ctx.globalAlpha = n.alpha * (on ? 0.9 : 0.45 * tw);
    ctx.drawImage(this.sprite(n.rgb, "h"), n.x - s / 2, n.y - s / 2, s, s);
    ctx.globalCompositeOperation = "source-over";
    ctx.globalAlpha = n.alpha;
    ctx.beginPath(); ctx.arc(n.x, n.y, n.r * (on ? 1.15 : 0.85), 0, TAU);
    ctx.lineWidth = 0.8 * hair; ctx.strokeStyle = rgba(mix(n.rgb, [255, 255, 255], 0.3), on ? 0.9 : 0.35 * tw); ctx.stroke();
    ctx.beginPath(); ctx.arc(n.x, n.y, on ? 2.6 : 1.7, 0, TAU); ctx.fillStyle = rgba(mix(n.rgb, [255, 255, 255], 0.55), on ? 1 : 0.85 * tw); ctx.fill();
    ctx.globalAlpha = 1;
    if (on) this.queueLabel(n, n.spec.label, n.alpha, { color: "#ffffff", size: 11.5 });
  }

  private drawSats(hovRaw: N | null) {
    const { ctx } = this; const k = this.cam.k; const hair = 1 / k;
    const projectMode = this.scene?.mode === "project";
    const many = this.sats.length > 14;
    for (const n of this.sats) {
      const v = n.vis;
      if (v < 0.05) continue;
      const isHov = hovRaw === n;
      const r = n.r * (0.45 + 0.55 * v) * (isHov ? 1.25 : 1);
      ctx.globalAlpha = Math.min(1, 0.25 + 0.75 * v);
      ctx.save();
      if (Math.abs(this.cam.t - 1) > 0.001) { ctx.translate(n.x, n.y); ctx.scale(1, 1 / this.cam.t); ctx.translate(-n.x, -n.y); }
      if (n.kind === "ver") {
        const d = r * 1.3;
        ctx.beginPath(); ctx.moveTo(n.x, n.y - d); ctx.lineTo(n.x + d, n.y); ctx.lineTo(n.x, n.y + d); ctx.lineTo(n.x - d, n.y); ctx.closePath();
        ctx.fillStyle = PALETTE[this.theme].body; ctx.fill();
        ctx.fillStyle = rgba(n.rgb, n.spec.status === "ok" ? 0.32 : 0.12); ctx.fill();
        ctx.lineWidth = (isHov ? 1.5 : 1) * hair; ctx.strokeStyle = rgba(n.spec.status === "bad" ? BRAND.bad : n.rgb, 0.8); ctx.stroke();
        if (n.spec.status === "running") { ctx.beginPath(); ctx.arc(n.x, n.y, d * 0.35, 0, TAU); ctx.fillStyle = rgba(HOT_C, 0.95); ctx.fill(); }
      } else {
        ctx.beginPath(); ctx.arc(n.x, n.y, r, 0, TAU);
        ctx.fillStyle = rgba(n.rgb, 0.85); ctx.fill();
        if (isHov) { ctx.beginPath(); ctx.arc(n.x, n.y, r + 3, 0, TAU); ctx.lineWidth = hair; ctx.strokeStyle = rgba(n.rgb, 0.9); ctx.stroke(); }
      }
      ctx.restore();
      ctx.globalAlpha = 1;
      const show = isHov || (projectMode && v > 0.85 && ((!many && this.sats.length <= 8) || k > 1.3)) || (!projectMode && v > 0.85 && k > 1.6);
      if (show) {
        const above = n.y < n.owner!.y - 1;
        this.queueLabel(n, n.spec.label, (isHov ? 1 : 0.72) * v, { r: r + 1, size: 11, color: isHov ? "#ffffff" : PALETTE[this.theme].labelDim, above, weight: n.kind === "cmd" ? 500 : 450 });
      }
    }
  }

  private drawCore() {
    const n = this.core;
    if (n.alpha < 0.02) return;
    const { ctx } = this; const hair = 1 / this.cam.k; const t = this.reduced ? 0 : this.time;
    const scene = this.scene;
    const offline = !!scene?.offline;
    const rgbA = BRAND.blue, rgbB = n.rgb;
    const e = this.energyS;
    ctx.globalAlpha = n.alpha;
    const hex = (r: number, rot: number) => {
      ctx.beginPath();
      for (let i = 0; i < 6; i++) { const a = rot + (i / 6) * TAU - Math.PI / 2; const x = n.x + Math.cos(a) * r, y = n.y + Math.sin(a) * r; if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y); }
      ctx.closePath();
    };
    // orbits
    ctx.lineWidth = hair;
    for (let i = 0; i < 2; i++) {
      ctx.save(); ctx.setLineDash([2 * hair, 7 * hair]); ctx.lineDashOffset = (i ? -1 : 1) * t * 10;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.r + 15 + i * 12, 0, TAU);
      ctx.strokeStyle = rgba(mix(rgbA, rgbB, 0.5), (0.34 - i * 0.12) * (offline ? 0.5 : 1)); ctx.stroke(); ctx.restore();
    }
    // stage ring (project scene), in the plane of the web
    const st = scene?.mode === "project" ? scene.stage : null;
    if (st) this.drawStageRing(st);
    this.upright(n, () => this.drawCrystal(n, st, offline, rgbA, rgbB, e, t, hair, hex));
    ctx.globalAlpha = 1;
  }

  private drawCrystal(n: N, st: WebStage | null | undefined, offline: boolean, rgbA: Rgb, rgbB: Rgb, e: number, t: number, hair: number, hex: (r: number, rot: number) => void) {
    const { ctx } = this;
    // energy halo
    ctx.globalCompositeOperation = "lighter";
    const hs = n.r * (5.5 + e * 3 + n.flash * 2 + (st && !["succeeded", "failed"].includes(st.status) ? Math.sin(t * 2.4) * 0.5 + 0.5 : 0));
    ctx.globalAlpha = n.alpha * (offline ? 0.25 : 0.55 + e * 0.3);
    ctx.drawImage(this.sprite(mix(rgbB, rgbA, 0.35), "h"), n.x - hs / 2, n.y - hs / 2, hs, hs);
    ctx.globalAlpha = n.alpha;
    ctx.globalCompositeOperation = "source-over";
    // crystal
    const rot = t * (0.15 + e * 0.5);
    hex(n.r, rot);
    ctx.fillStyle = PALETTE[this.theme].body; ctx.fill();
    const g = ctx.createLinearGradient(n.x - n.r, n.y - n.r, n.x + n.r, n.y + n.r);
    g.addColorStop(0, rgba(BRAND.cyan, 0.95)); g.addColorStop(0.5, rgba(rgbA, 0.95)); g.addColorStop(1, rgba(rgbB, 0.95));
    ctx.lineWidth = 1.7 * hair; ctx.strokeStyle = offline ? rgba([140, 150, 190], 0.6) : g; ctx.stroke();
    const fill = ctx.createRadialGradient(n.x, n.y - n.r * 0.3, 0, n.x, n.y, n.r);
    fill.addColorStop(0, rgba(rgbB, 0.22)); fill.addColorStop(1, rgba(rgbA, 0.04));
    ctx.fillStyle = fill; ctx.fill();
    hex(n.r * 0.58, -t * 0.3 * (1 + e));
    ctx.fillStyle = rgba(rgbB, 0.16); ctx.fill();
    ctx.lineWidth = hair; ctx.strokeStyle = rgba(mix(rgbB, BRAND.cyan, 0.3), 0.8); ctx.stroke();
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a1 = rot + (i / 6) * TAU - Math.PI / 2, a2 = -t * 0.3 * (1 + e) + (i / 6) * TAU - Math.PI / 2;
      ctx.moveTo(n.x + Math.cos(a2) * n.r * 0.58, n.y + Math.sin(a2) * n.r * 0.58); ctx.lineTo(n.x + Math.cos(a1) * n.r, n.y + Math.sin(a1) * n.r);
    }
    ctx.strokeStyle = rgba(rgbB, 0.32); ctx.stroke();
    // spark
    const p = 0.8 + 0.2 * Math.sin(t * 2.2) + e * 0.4;
    ctx.globalCompositeOperation = "lighter";
    const s = 28 * p;
    ctx.drawImage(this.sprite(offline ? [150, 160, 200] : HOT_C), n.x - s / 2, n.y - s / 2, s, s);
    ctx.globalCompositeOperation = "source-over";
  }

  private drawStageRing(st: WebStage) {
    const { ctx } = this; const n = this.core; const hair = 1 / this.cam.k; const t = this.time;
    const R = n.r + 44;
    const seg = TAU / STAGES.length;
    const gap = 0.07;
    const cur = STAGES.indexOf(st.status);
    const done = st.status === "succeeded";
    const failed = st.status === "failed";
    STAGES.forEach((key, i) => {
      const a0 = -Math.PI / 2 + i * seg + gap, a1 = -Math.PI / 2 + (i + 1) * seg - gap;
      let state: "done" | "now" | "skip" | "pending" = "pending";
      if (done) state = key === "repairing" && !st.repairs ? "skip" : "done";
      else if (failed) state = st.seen.includes(key) ? "done" : "pending";
      else if (i < cur) state = key === "repairing" && !st.repairs ? "skip" : "done";
      else if (i === cur) state = "now";
      ctx.beginPath(); ctx.arc(n.x, n.y, R, a0, a1);
      ctx.lineWidth = 2.2 * hair;
      ctx.strokeStyle = state === "pending" ? "rgba(150,165,255,0.12)" : state === "skip" ? "rgba(150,165,255,0.2)" : rgba(failed ? BRAND.bad : key === "repairing" ? BRAND.warn : key === "scanning" ? BRAND.cyan : mix(BRAND.blue, BRAND.violet, i / 4), state === "now" ? 0.35 : 0.85);
      if (state === "skip") { ctx.save(); ctx.setLineDash([2 * hair, 4 * hair]); ctx.stroke(); ctx.restore(); } else ctx.stroke();
      if (state === "now") {
        // the current stage fills with a travelling sweep
        const sweep = this.reduced ? 0.5 : (t * 0.45) % 1;
        const b0 = a0 + (a1 - a0) * Math.max(0, sweep - 0.35), b1 = a0 + (a1 - a0) * sweep;
        ctx.beginPath(); ctx.arc(n.x, n.y, R, b0, Math.max(b0 + 0.01, b1));
        ctx.lineWidth = 2.6 * hair; ctx.strokeStyle = rgba(key === "repairing" ? BRAND.warn : HOT_C, 0.95); ctx.stroke();
        ctx.globalCompositeOperation = "lighter";
        const hx = n.x + Math.cos(b1) * R, hy = n.y + Math.sin(b1) * R;
        ctx.drawImage(this.sprite(key === "repairing" ? BRAND.warn : HOT_C), hx - 8 * hair * 1.6, hy - 8 * hair * 1.6, 16 * hair * 1.6, 16 * hair * 1.6);
        ctx.globalCompositeOperation = "source-over";
      }
    });
  }

  private positionPins() {
    const c = this.captionEl;
    if (c) {
      const p = this.screenPos(this.core);
      // project: below the whole weave (files + their satellites); home: just under the core
      const ringR = this.scene?.mode === "project" ? Math.max((CORE_R + 50) * this.cam.t, (this.ringMax + (this.sats.length ? 70 : 34)) * this.cam.t) * this.cam.k : (CORE_R + 30) * this.cam.k;
      c.style.transform = `translate3d(${Math.round(p.x)}px, ${Math.round(p.y + ringR + this.captionDy)}px, 0) translateX(-50%)`;
      c.style.opacity = String(this.core.alpha);
    }
    const el = this.hoverEl;
    const n = this.hovered && this.hovered.kind !== "core" ? this.hovered : null;
    if (!el || !n) return;
    const p = this.screenPos(n);
    const r = n.r * this.cam.k;
    const w = el.offsetWidth || 260, h = el.offsetHeight || 110;
    let x = p.x + r + 26, y = p.y - h / 2;
    if (x + w > this.W - 12) x = p.x - r - 26 - w;
    y = Math.max(12, Math.min(this.H - h - 12, y));
    el.style.transform = `translate3d(${Math.round(x)}px, ${Math.round(y)}px, 0)`;
  }
}

"use client";

// "Explain this mod": everything the build reported, in plain English, set as a
// readable document (type and hairlines, not boxes). Also the request and the images
// Cyrus looked at, and the failure explanation with retry.
import { useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { cyrusModel } from "@/lib/cyrus/models";
import { viewMeta } from "@/lib/cyrus/projects";
import { estimate } from "@/lib/cyrus/estimate";
import { CyIcon } from "./icons";

export function Explain({ b }: { b: ModBuildView }) {
  const r = b.result;
  const s = r?.summary;
  if (b.status !== "succeeded") return <div className="cy-doc">{b.status === "failed" && <FailureDetails b={b} />}<Request b={b} lead={b.status !== "failed"} /></div>;
  return (
    <div className="cy-doc">
      <section className="cy-doc-hero">
        <span className="cy-k"><CyIcon name="sparkle" size={12} /> In plain English</span>
        <h3>{s?.tagline || `${b.pluginName} is built`}</h3>
        {s?.text && <p className="cy-lead">{s.text}</p>}
        {s?.changes && b.changeRequest && <p className="cy-changed"><b>What changed.</b> {s.changes}</p>}
      </section>

      {!!s?.howToUse?.length && (
        <section className="cy-doc-s">
          <h4>How to use it</h4>
          <ol className="cy-steps">{s.howToUse.map((h, i) => <li key={i}><span className="cy-step-n">{i + 1}</span><span>{h}</span></li>)}</ol>
        </section>
      )}

      {!!r?.commands?.length && (
        <section className="cy-doc-s">
          <h4>Commands <span className="cy-count">{r.commands.length}</span></h4>
          <div className="cy-rows">
            {r.commands.map((c, i) => (
              <div key={i} className="cy-row">
                <code className="cy-cmd">{c.usage}</code>
                <span className="cy-row-v">{c.description}</span>
                <span className={`cy-who ${/every/i.test(c.whoCanUse) || (!c.whoCanUse && !c.permission) ? "all" : ""}`}>{c.whoCanUse || (c.permission ? "With permission" : "Everyone")}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {!!r?.config?.length && (
        <section className="cy-doc-s">
          <h4>Settings you can change</h4>
          <p className="cy-sub">In <code className="cy-cmd">plugins/{b.pluginName}/config.yml</code> on your server.</p>
          <div className="cy-rows">
            {r.config.map((c, i) => (
              <div key={i} className="cy-row">
                <b className="cy-anywhere cy-row-k">{c.key}</b>
                <span className="cy-row-v">{c.description}</span>
                <span className="cy-row-d cy-anywhere">{c.default ? `Default ${c.default}` : ""}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {!!r?.permissions?.length && (
        <section className="cy-doc-s">
          <h4>Who can do what</h4>
          <p className="cy-sub">Works with LuckPerms or any permissions plugin.</p>
          <div className="cy-rows">
            {r.permissions.map((p, i) => (
              <div key={i} className="cy-row">
                <b className="cy-anywhere cy-row-k">{p.node}</b>
                <span className="cy-row-v">{p.description}</span>
                <span className={`cy-who ${p.default === "true" ? "all" : ""}`}>{p.default === "true" ? "Everyone" : p.default === "false" ? "Nobody by default" : "Operators"}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      <Safety b={b} />

      {(!!s?.limitations?.length || !!r?.warnings?.length) && (
        <section className="cy-doc-s">
          <h4>Good to know</h4>
          <ul className="cy-bullets">
            {(s?.limitations ?? []).map((l, i) => <li key={`l${i}`}>{l}</li>)}
            {(r?.warnings ?? []).slice(0, 6).map((w, i) => <li key={`w${i}`}>{w}</li>)}
          </ul>
        </section>
      )}

      <Request b={b} />

      <section className="cy-doc-s cy-soon">
        <span className="cy-badge"><CyIcon name="sparkle" size={10} /> Built with Cyrus</span>
        <p className="cy-sub">Coming to Cyrus mods: your server&apos;s Mods tab with an on/off switch, a Cyrus Mods community in NxLabs, and open source so anyone can learn from them.</p>
      </section>
    </div>
  );
}

export function Request({ b, lead }: { b: ModBuildView; lead?: boolean }) {
  const meta = viewMeta(b);
  const atts = meta.attachments ?? [];
  const m = cyrusModel(meta.model);
  const running = !isTerminal(b.status);
  const e = running ? estimate(b.changeRequest || b.prompt, m.id, { change: !!b.changeRequest }) : null;
  return (
    <section className={`cy-doc-s ${lead ? "lead" : ""}`}>
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && <details className="cy-details"><summary>Original description</summary><p>{b.prompt}</p></details>}
      {atts.length > 0 && (
        <div className="cy-refs">
          {atts.map((a) => (
            <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" className="cy-ref" title={a.name}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" />
            </a>
          ))}
          <span className="cy-sub"><CyIcon name="eye" size={12} /> {atts.length === 1 ? "Cyrus looked at this image" : `Cyrus looked at these ${atts.length} images`} while planning.</span>
        </div>
      )}
      {lead && (
        <p className="cy-fine">
          <span className="cy-model-dot" style={{ background: m.hue }} /> {m.name} · Paper {b.mcVersion}
          {e && <> · usually ~{e.minutes[0]}–{e.minutes[1]} min</>}
        </p>
      )}
    </section>
  );
}

function Safety({ b }: { b: ModBuildView }) {
  const sf = b.result?.safety;
  const warns = (sf?.findings ?? []).filter((f) => f.severity === "warn");
  const checks: [string, string][] = [
    ["No internet access", "It can't send your data anywhere."],
    ["Can't run programs", "Nothing outside the game gets started."],
    ["Only its own folder", `Reads and writes only plugins/${b.pluginName || ""}.`],
    ["No hidden admin access", "No secret players with special powers."],
  ];
  return (
    <section className="cy-doc-s cy-safety">
      <h4><span className="cy-shield"><CyIcon name="shield" size={14} /></span> Safety check <span className={`cy-pill ${warns.length ? "warn" : "ok"}`}><i />{warns.length ? "Passed with notes" : "Passed"}</span></h4>
      <ul className="cy-checks">
        {checks.map(([t, d]) => <li key={t}><CyIcon name="check" size={13} strokeWidth={2.2} /><span><b>{t}</b> {d}</span></li>)}
      </ul>
      {warns.length > 0 && <p className="cy-note">This mod {Array.from(new Set(warns.map((w) => w.message))).join("; ")}. That&apos;s allowed, just worth knowing.</p>}
      <p className="cy-fine">An automated scan of the compiled code. It checks for risky behaviour; it doesn&apos;t promise the mod is bug-free.</p>
    </section>
  );
}

const FAIL: Record<string, { title: string; tips: string[] }> = {
  compile: { title: "The code didn't compile, even after fixes", tips: ["Ask for fewer features at once. You can add more as changes afterwards.", "Avoid asking for other plugins (like Vault or WorldEdit). Cyrus builds on plain Paper."] },
  safety: { title: "Blocked by the safety check", tips: ["Remove anything that needs the internet, other programs or files outside the server.", "Webhooks, Discord bots and remote databases can't be built yet."] },
  refused: { title: "Cyrus won't build this one", tips: ["Cyrus only builds mods that are safe for your players and your server."] },
  budget: { title: "This mod is bigger than one build", tips: ["Split the idea into two or three smaller mods, or try Yakko for big systems."] },
  timeout: { title: "This build ran out of time", tips: ["Split the idea into two or three smaller mods."] },
  cancelled: { title: "You stopped this build", tips: ["Start it again whenever you like."] },
  ai_unavailable: { title: "Cyrus had a hiccup", tips: ["Trying again in a minute usually works."] },
  unavailable: { title: "The builder is offline", tips: ["Try again in a few minutes."] },
  interrupted: { title: "The builder restarted mid-build", tips: ["Nothing is lost. Start it again."] },
};

const failInfo = (b: ModBuildView) => FAIL[b.errorCode || ""] ?? { title: "This one didn't build", tips: ["Try again, or describe it a little differently."] };

/** Failure details, at the top of the inspector's Request tab. */
export function FailureDetails({ b }: { b: ModBuildView }) {
  const f = failInfo(b);
  return (
    <section className="cy-doc-s lead cy-faild">
      <span className="cy-fail-k"><CyIcon name={b.errorCode === "cancelled" ? "stop" : "warn"} size={13} /> {b.errorCode === "cancelled" ? "Stopped" : "Why it didn't build"}</span>
      {b.error && <p className="cy-lead">{b.error}</p>}
      <ul className="cy-bullets">{f.tips.map((t) => <li key={t}>{t}</li>)}</ul>
      {b.result?.errorDetail && b.errorCode === "compile" && (
        <details className="cy-details"><summary>What the compiler said</summary><pre className="cy-pre">{b.result.errorDetail}</pre></details>
      )}
    </section>
  );
}

/** Failure, shown under the core on the web: the verdict and the two ways forward. */
export function Failure({ b, onRetry, onEdit }: { b: ModBuildView; onRetry: () => Promise<string | null>; onEdit: () => void }) {
  const f = failInfo(b);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className={`cy-fail code-${b.errorCode}`}>
      <span className="cy-fail-k"><CyIcon name={b.errorCode === "cancelled" ? "stop" : "warn"} size={13} /> {b.errorCode === "cancelled" ? "Stopped" : "Didn't build"}</span>
      <h2 className="cy-fail-t">{f.title}</h2>
      {err && <p className="cy-err" role="alert">{err}</p>}
      <div className="cy-fail-act">
        {b.errorCode !== "refused" && (
          <button type="button" className="cy-btn primary" disabled={busy} onClick={async () => { setBusy(true); setErr(await onRetry()); setBusy(false); }}>
            {busy ? <i className="cy-spin" /> : <CyIcon name="retry" size={14} />} Try again
          </button>
        )}
        <button type="button" className="cy-btn" onClick={onEdit}><CyIcon name="pencil" size={14} /> {b.errorCode === "refused" ? "Describe something else" : "Edit and retry"}</button>
      </div>
    </div>
  );
}
"use client";

// Tiny per-line highlighter (React nodes only, no HTML injection). Same rules as
// components/nx/modbuilder/SourceViewer.tsx, copied so Cyrus can restyle freely.
import type { ReactNode } from "react";

const JAVA_KW = new Set("abstract assert boolean break byte case catch char class const continue default do double else enum extends final finally float for if implements import instanceof int interface long native new null package private protected public return short static super switch synchronized this throw throws transient try var void volatile while true false record yield".split(" "));

/** Tiny per-line highlighter: React nodes only (no HTML injection). Block comments are styled per line. */
export function highlight(line: string, lang: string): ReactNode[] {
  const out: ReactNode[] = [];
  let k = 0;
  if (lang === "yaml") {
    const m = line.match(/^(\s*)(#.*)$/);
    if (m) return [m[1], <span key="c" className="m">{m[2]}</span>];
    const kv = line.match(/^(\s*-?\s*)([\w.\-'"]+)(:)(.*)$/);
    if (kv) return [kv[1], <span key="k" className="t">{kv[2]}</span>, kv[3], <span key="v" className="s">{kv[4]}</span>];
    return [line];
  }
  const re = /(\/\/.*$|\/\*.*?\*\/|^\s*\*.*$|^\s*\/\*.*$)|("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])')|(@\w+)|\b([A-Za-z_]\w*)\b/g;
  let last = 0;
  for (let m; (m = re.exec(line)); ) {
    if (m.index > last) out.push(line.slice(last, m.index));
    if (m[1]) out.push(<span key={k++} className="m">{m[1]}</span>);
    else if (m[2]) out.push(<span key={k++} className="s">{m[2]}</span>);
    else if (m[3]) out.push(<span key={k++} className="a">{m[3]}</span>);
    else if (m[4] && JAVA_KW.has(m[4])) out.push(<span key={k++} className="k">{m[4]}</span>);
    else if (m[4] && /^[A-Z]/.test(m[4])) out.push(<span key={k++} className="t">{m[4]}</span>);
    else out.push(m[0]);
    last = m.index + m[0].length;
  }
  if (last < line.length) out.push(line.slice(last));
  return out;
}

export const langOf = (p: string | null | undefined) => (p?.endsWith(".java") ? "java" : p?.endsWith(".yml") || p?.endsWith(".yaml") ? "yaml" : p?.endsWith(".json") ? "json" : "kts");
"use client";

// React host for the CyrusWeb engine: one canvas for the whole app, a caption pinned
// under the core and a hover card that follows the hovered node.
import { useEffect, useRef, useState, type MutableRefObject, type ReactNode } from "react";
import { CyrusWeb, type WebNodeSpec, type WebScene } from "./engine";

export type Region = { x: number; y: number; w: number; h: number; coreY?: number; fit?: "inner" | "all" };

const sig = (s: WebScene) =>
  s.key + "|" + (s.offline ? 1 : 0) + "|" + (s.stage ? `${s.stage.status}:${s.stage.repairs}` : "") + "|" + s.core.label + "|" +
  s.nodes.map((n) => `${n.id}:${n.status ?? ""}:${n.live ? 1 : 0}:${n.progress?.toFixed(2) ?? ""}:${n.label}`).join(",");

export function CyrusCanvas({ engineRef, scene, fromId, region, energy, focusId, onOpen, caption, captionDy = 30, hoverCard }: {
  engineRef: MutableRefObject<CyrusWeb | null>;
  scene: WebScene;
  fromId?: string | null;
  region: Region;
  energy: number;
  focusId?: string | null;
  onOpen: (n: WebNodeSpec) => void;
  caption?: ReactNode;
  captionDy?: number;
  hoverCard?: (n: WebNodeSpec) => ReactNode;
}) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const cap = useRef<HTMLDivElement>(null);
  const hov = useRef<HTMLDivElement>(null);
  const eng = useRef<CyrusWeb | null>(null);
  const [hover, setHover] = useState<WebNodeSpec | null>(null);
  const openRef = useRef(onOpen);
  openRef.current = onOpen;
  const lastSig = useRef("");
  const fromRef = useRef(fromId);
  fromRef.current = fromId;

  useEffect(() => {
    const e = new CyrusWeb(canvas.current!, { onHover: (n) => setHover(n), onOpen: (n) => openRef.current(n) });
    eng.current = e;
    engineRef.current = e;
    e.setRegion(region);
    e.setScene(scene);
    lastSig.current = sig(scene);
    e.pinCaption(cap.current, captionDy);
    e.pinHover(hov.current);
    try { if (localStorage.getItem("cyDebug") === "1") (window as unknown as { __cyWeb: CyrusWeb }).__cyWeb = e; } catch { /* */ }
    return () => { e.dispose(); eng.current = null; engineRef.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const s = sig(scene);
    if (s === lastSig.current) return;
    lastSig.current = s;
    eng.current?.setScene(scene, { fromId: fromRef.current ?? undefined });
  }, [scene]);
  useEffect(() => { eng.current?.setRegion(region); }, [region]);
  useEffect(() => { eng.current?.setEnergy(energy); }, [energy]);
  useEffect(() => { eng.current?.setFocus(focusId ?? null); }, [focusId]);
  useEffect(() => { eng.current?.pinCaption(cap.current, captionDy); }, [captionDy, caption]);

  return (
    <>
      <canvas ref={canvas} className="cy-canvas" role="img" aria-label={scene.mode === "home" ? "Your mods as a living network around Cyrus. Use the Mods list or press P to open one." : `The ${scene.core.label} mod: its files, commands and settings as a network.`} />
      <div ref={cap} className="cy-caption" aria-live="polite">{caption}</div>
      <div ref={hov} className={`cy-hovercard ${hover && hoverCard ? "on" : ""}`} aria-hidden="true">{hover && hoverCard ? hoverCard(hover) : null}</div>
    </>
  );
}

"use client";

// The code view. While a build runs it shows the REAL workspace filling in (useLive):
// the file being written types itself out at the speed the AI writes it, files that land
// get a check, edited lines glow once. When the build is done it shows the final source.
import { memo, useEffect, useMemo, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { diffLines } from "@/lib/cyrus/diff";
import { CyIcon } from "./icons";
import { highlight, langOf } from "./highlight";
import { useSource } from "./source";
import { useTypewriter, type LiveState } from "./useLive";

const EV = /^(Wrote|Edited|Reading) (.+)$/;

/** File names the AI touched, from the real build events ("Wrote Main.java"). Fallback when live code is unavailable. */
export function touchedFiles(b: ModBuildView): { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }[] {
  const out = new Map<string, { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }>();
  for (const e of b.result?.events ?? []) {
    const m = e.message.match(EV);
    if (!m) continue;
    const verb = m[1] as "Wrote" | "Edited" | "Reading";
    const prev = out.get(m[2]);
    if (verb === "Reading" && prev) continue;
    out.set(m[2], { name: m[2], verb: prev && prev.verb !== "Reading" && verb === "Reading" ? prev.verb : verb, at: e.at });
  }
  return Array.from(out.values());
}

export const visibleSrc = (files: { path: string; size: number }[]) => files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json" || f.path.endsWith(".kts"));

type Row = { path: string; name: string; state: "writing" | "editing" | "written" | "edited" | "base" | "ready" | "named"; src: "live" | "final" | "base" | "none" };

export function LiveCode({ build, base, live, focusPath, onPick }: {
  build: ModBuildView;
  base?: ModBuildView | null;
  live: LiveState;
  /** a file picked on the web */
  focusPath?: string | null;
  onPick?: (path: string) => void;
}) {
  const running = !isTerminal(build.status);
  const finalFiles = visibleSrc(build.result?.files ?? []).filter((f) => !f.path.endsWith(".kts"));

  const rows: Row[] = useMemo(() => {
    if (!running && finalFiles.length) return finalFiles.map((f) => ({ path: f.path, name: f.path.split("/").pop()!, state: "ready" as const, src: "final" as const }));
    const out = new Map<string, Row>();
    for (const f of visibleSrc(base?.result?.files ?? []).filter((x) => x.path.startsWith("src/main/"))) out.set(f.path, { path: f.path, name: f.path.split("/").pop()!, state: "base", src: "base" });
    for (const f of live.files.values()) out.set(f.path, { path: f.path, name: f.path.split("/").pop()!, state: f.state, src: "live" });
    if (live.supported === false) {
      for (const t of touchedFiles(build).filter((x) => x.verb !== "Reading")) {
        if (![...out.values()].some((r) => r.name === t.name)) out.set(t.name, { path: t.name, name: t.name, state: "named", src: "none" });
      }
    }
    return [...out.values()];
  }, [running, finalFiles, base, live, build]);

  const [sel, setSel] = useState<string | null>(null);
  const [follow, setFollow] = useState(true);
  useEffect(() => { if (focusPath) { setSel(focusPath); setFollow(false); } }, [focusPath]);
  useEffect(() => { setFollow(true); setSel(null); }, [build.id]);
  const writing = live.draft && !live.draft.done ? live.draft.path : null;
  const newest = running ? writing ?? [...live.files.values()].sort((a, b) => b.changedAt - a.changedAt)[0]?.path ?? null : null;
  const pickDefault = () => {
    const java = rows.filter((r) => r.name.endsWith(".java"));
    const pn = build.pluginName;
    return (pn && java.find((r) => r.name === `${pn}.java` || r.name === `${pn}Plugin.java`)) || java.find((r) => /Plugin\.java$|Main\.java$/.test(r.name)) || java[0] || rows[0] || null;
  };
  const current = (running && follow && newest ? rows.find((r) => r.path === newest) : null) ?? rows.find((r) => r.path === sel) ?? pickDefault();

  const groups = useMemo(() => {
    const g: Record<string, Row[]> = { Code: [], "Plugin files": [] };
    for (const r of rows) (r.name.endsWith(".java") ? g.Code : g["Plugin files"]).push(r);
    return Object.entries(g).filter(([, v]) => v.length);
  }, [rows]);

  const touched = rows.filter((r) => r.state === "writing" || r.state === "editing" || r.state === "written" || r.state === "edited").length;

  return (
    <div className="cy-code">
      <nav className="cy-tree" aria-label="Files">
        <div className="cy-tree-head">
          {running ? <span className="cy-live"><i />{live.supported === false ? "Building" : "Live"}</span> : <span className="cy-tree-count">{rows.length} files</span>}
          {running && touched > 0 && <span className="cy-tree-count">{touched} written</span>}
        </div>
        {rows.length === 0 && (
          <div className="cy-tree-empty">
            <span className="cy-skel" style={{ width: "72%" }} /><span className="cy-skel" style={{ width: "54%" }} /><span className="cy-skel" style={{ width: "63%" }} />
            <p>{running ? "Files appear the moment Cyrus starts writing them." : "No source for this version."}</p>
          </div>
        )}
        {groups.map(([dir, list]) => (
          <div key={dir} className="cy-tree-g">
            <div className="cy-tree-dir">{dir}</div>
            {list.map((r) => (
              <button key={r.path} type="button" title={r.path} className={`cy-tree-f ${current?.path === r.path ? "on" : ""} st-${r.state}`}
                      onClick={() => { setSel(r.path); setFollow(false); onPick?.(r.path); }}>
                <span className={`cy-fdot ${r.name.endsWith(".java") ? "j" : "y"}`} />
                <span className="cy-tree-n">{r.name}</span>
                {(r.state === "writing" || r.state === "editing") && <span className="cy-fstate run">{r.state === "writing" ? "writing" : "editing"}</span>}
                {(r.state === "written" || r.state === "edited") && <span className="cy-fstate ok"><CyIcon name="check" size={10} strokeWidth={2.6} /></span>}
              </button>
            ))}
          </div>
        ))}
        {running && !follow && rows.length > 0 && (
          <button type="button" className="cy-follow" onClick={() => setFollow(true)}><CyIcon name="eye" size={12} /> Follow Cyrus</button>
        )}
      </nav>
      <div className="cy-view">
        {current ? <Viewer key={`${build.id}:${current.path}`} build={build} base={base ?? null} row={current} live={live} running={running} /> : (
          <div className="cy-view-empty"><Skeleton label={running ? "Cyrus is planning the files" : "No source files"} /></div>
        )}
      </div>
    </div>
  );
}

function Viewer({ build, base, row, live, running }: { build: ModBuildView; base: ModBuildView | null; row: Row; live: LiveState; running: boolean }) {
  const lf = live.files.get(row.path);
  const draft = live.draft && live.draft.path === row.path && !live.draft.done ? live.draft : null;
  const fetched = useSource(row.src === "final" ? build.id : row.src === "base" ? base?.id ?? null : null, row.src === "final" || row.src === "base" ? row.path : null);
  const streaming = !!draft && draft.op === "write";
  const target = streaming ? draft!.text : row.src === "live" ? lf?.text ?? "" : fetched.text ?? "";
  const shown = useTypewriter(target, `${row.path}:${draft?.seq ?? "f"}`, streaming);
  const text = streaming ? target.slice(0, shown) : target;
  const lang = langOf(row.path);
  const lines = text ? text.replace(/\n$/, "").split("\n") : [];
  const scroller = useRef<HTMLDivElement>(null);

  // Lines changed by an edit glow once.
  const changed = useMemo(() => {
    if (!lf || lf.state !== "edited" || !lf.prev || !lf.text) return null;
    const s = new Set<number>();
    for (const op of diffLines(lf.prev, lf.text)) if (op.t === "add" && op.b !== null) s.add(op.b);
    return s;
  }, [lf]);

  useEffect(() => {
    if (!streaming) return;
    const el = scroller.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [streaming, lines.length]);

  const status = draft ? (draft.op === "write" ? "Cyrus is writing this file" : "Cyrus is editing this file")
    : row.state === "edited" ? "Just edited" : row.state === "written" ? "Written" : row.state === "base" && running ? "Previous version" : null;

  return (
    <>
      <div className="cy-view-path">
        <span className="cy-view-file">{row.path.replace(/^src\/main\/(java\/)?/, "")}</span>
        {status && <span className={`cy-view-tag ${draft ? "run" : ""}`}>{draft && <i className="cy-dotpulse" />}{status}</span>}
        {!running && text && (
          <button type="button" className="cy-view-btn" onClick={() => navigator.clipboard?.writeText(text)} aria-label="Copy file"><CyIcon name="copy" size={13} /></button>
        )}
      </div>
      <div className="cy-view-scroll" ref={scroller}>
        {row.state === "named" ? (
          <Skeleton label={`${row.name} is written`} note="This builder shares file names while it works; the code opens when the build finishes." />
        ) : !text && (fetched.error) ? (
          <p className="cy-view-err">Couldn&apos;t load this file right now.</p>
        ) : !text && !draft ? (
          <Skeleton label={running ? "Loading" : "Loading"} compact />
        ) : (
          <div className={`cy-lines ${streaming ? "streaming" : ""}`} role="region" aria-label={`Source of ${row.name}`} aria-live={streaming ? "off" : undefined}>
            {lines.map((l, i) => <Line key={i} n={i + 1} text={l} lang={lang} glow={!!changed?.has(i + 1)} caret={streaming && i === lines.length - 1} />)}
            {draft && draft.op === "edit" && (
              <div className="cy-editing">
                <span className="cy-editing-k"><i className="cy-dotpulse" /> New code going in</span>
                <pre>{draft.text.slice(-600)}</pre>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
}

const Line = memo(function Line({ n, text, lang, glow, caret }: { n: number; text: string; lang: string; glow: boolean; caret: boolean }) {
  return (
    <div className={`cy-ln ${glow ? "glow" : ""}`}>
      <span className="n">{n}</span>
      <span className="c">{highlight(text, lang)}{caret && <i className="cy-caret" />}</span>
    </div>
  );
});

function Skeleton({ label, note, compact }: { label: string; note?: string; compact?: boolean }) {
  const widths = [62, 44, 78, 30, 66, 52, 84, 38, 58, 70];
  return (
    <div className={`cy-weave ${compact ? "compact" : ""}`}>
      <div className="cy-weave-lines" aria-hidden="true">
        {widths.slice(0, compact ? 4 : 10).map((w, i) => <span key={i} className="cy-skel" style={{ width: `${w}%`, marginLeft: `${(i % 4) * 14}px`, animationDelay: `${i * 90}ms` }} />)}
      </div>
      <div className="cy-weave-l"><i className="cy-spin" /> {label}</div>
      {note && <p className="cy-weave-n">{note}</p>}
    </div>
  );
}
"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_STATUS_LABEL } from "@/lib/cyrus/models";
import type { CyrusProject } from "@/lib/cyrus/projects";
import { CyIcon } from "./icons";
import { Glyph } from "./Glyph";

export function Modal({ title, sub, onClose, children, wide }: { title: string; sub?: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", k); document.body.style.overflow = prev; };
  }, [onClose]);
  // Portalled to <body> so it sits above the portal's own top bar; .cy-tokens carries the theme.
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => setHost(document.body), []);
  if (!host) return null;
  return createPortal(
    <div className="cy-tokens cy-modal-back" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className={`cy-modal ${wide ? "wide" : ""}`}>
        <div className="cy-modal-h">
          <div className="flex min-w-0 flex-col gap-1">
            <h2>{title}</h2>
            {sub && <p>{sub}</p>}
          </div>
          <button type="button" className="cy-ib ml-auto" onClick={onClose} aria-label="Close"><CyIcon name="x" size={14} /></button>
        </div>
        {children}
      </div>
    </div>,
    host,
  );
}

export function InstallModal({ build, servers, onClose, onDone }: { build: ModBuildView; servers: MbServer[]; onClose: () => void; onDone: () => void }) {
  const firstOk = servers.find((s) => s.compatible);
  const [sel, setSel] = useState<string | null>(build.lastInstall?.serverId && servers.some((s) => s.id === build.lastInstall!.serverId && s.compatible) ? build.lastInstall.serverId : firstOk?.id ?? null);
  const chosen = servers.find((s) => s.id === sel);
  const [restart, setRestart] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<null | { replaced: string[]; restarted: boolean; restartNote: string | null }>(null);

  async function go() {
    if (!sel) return;
    setBusy(true); setErr(null);
    try {
      const r = await fetch(`/api/mod-builder/builds/${build.id}/install`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ serverId: sel, restart: restart && chosen?.status === "RUNNING" }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { setErr(j.error || "The install didn't go through."); setBusy(false); return; }
      setDone(j); setBusy(false); onDone();
    } catch { setErr("We couldn't reach Nxeon. Try again."); setBusy(false); }
  }

  if (done) {
    return (
      <Modal title="Installed" onClose={onClose}>
        <div className="cy-done">
          <span className="cy-done-orb"><CyIcon name="check" size={22} strokeWidth={2.4} /></span>
          <p className="cy-done-t">{build.jarName} is on {chosen?.name}.</p>
          <p className="cy-sub max-w-[46ch] text-center">
            {done.restarted ? "The server is restarting now. Your mod loads as soon as it's back up (usually under a minute)."
              : done.restartNote ? `We couldn't restart it automatically: ${done.restartNote} Restart it from the server page to load the mod.`
              : "Restart the server to load the mod. Paper doesn't load new plugins while it's running."}
            {done.replaced.length > 0 && ` We replaced ${done.replaced.join(", ")} and kept a backup of it.`}
          </p>
          <div className="flex flex-wrap justify-center gap-2">
            <Link href={`/dashboard/servers/${sel}`} className="cy-btn primary">Open server <CyIcon name="chevr" size={13} /></Link>
            <button type="button" className="cy-btn" onClick={onClose}>Done</button>
          </div>
        </div>
      </Modal>
    );
  }

  return (
    <Modal title="Install to my server" sub={`Copies ${build.jarName} into the server's plugins folder.`} onClose={onClose}>
      {servers.length === 0 ? (
        <div className="cy-done">
          <span className="cy-done-orb dim"><CyIcon name="server" size={20} /></span>
          <p className="cy-done-t">You don&apos;t have a Minecraft server yet</p>
          <p className="cy-sub max-w-[40ch] text-center">Download the .jar and put it in any Paper server&apos;s plugins folder, or start a Paper server on Nxeon.</p>
          <Link href="/dashboard/deploy" className="cy-btn primary">Get a Minecraft server</Link>
        </div>
      ) : (
        <>
          <div className="cy-srvs" role="radiogroup" aria-label="Server">
            {servers.map((s) => (
              <label key={s.id} className={`cy-srv ${sel === s.id ? "on" : ""} ${s.compatible ? "" : "off"}`}>
                <input type="radio" name="cy-srv" className="sr-only" disabled={!s.compatible} checked={sel === s.id} onChange={() => setSel(s.id)} />
                <span className={`cy-srv-dot ${s.status === "RUNNING" ? "up" : ""}`} />
                <span className="flex min-w-0 flex-1 flex-col">
                  <b className="truncate">{s.name}</b>
                  <span className="cy-sub">{s.compatible ? `${cap(s.variant)} · ${s.status === "RUNNING" ? "online" : "stopped"}` : s.reason}</span>
                </span>
                {sel === s.id && <CyIcon name="check" size={15} />}
              </label>
            ))}
          </div>
          {chosen?.status === "RUNNING" && (
            <label className="cy-checkrow">
              <input type="checkbox" checked={restart} onChange={(e) => setRestart(e.target.checked)} />
              <span><b>Restart the server now</b> so the mod loads. Players get a short warning first.</span>
            </label>
          )}
          <p className="cy-sub">If an older version of {build.pluginName} is already there, we back it up before replacing it.</p>
          {err && <p role="alert" className="cy-err">{err}</p>}
          <div className="flex justify-end gap-2">
            <button type="button" className="cy-btn" onClick={onClose}>Cancel</button>
            <button type="button" className="cy-btn primary" disabled={!sel || busy} onClick={go}>
