tsx='''"use client";

// Cyrus icons: one consistent line set, from Lucide (https://lucide.dev), adapted for the
// studio: 24-grid, round caps and joins, a lighter 1.6 stroke at UI sizes, currentColor.
//
// Lucide is ISC licensed (some icons derive from Feather, MIT):
//   ISC License. Copyright (c) 2026 Lucide Icons and Contributors.
//   Permission to use, copy, modify, and/or distribute this software for any purpose with or
//   without fee is hereby granted, provided that the above copyright notice and this
