//   DIRECT, INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES WHATSOEVER RESULTING FROM LOSS
//   OF USE, DATA OR PROFITS, WHETHER IN AN ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS
//   ACTION, ARISING OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS SOFTWARE.
//   Feather: The MIT License (MIT), Copyright (c) 2013-present Cole Bemis.
import { createElement } from "react";

type Node = [string, Record<string, string>];
const I: Record<string, Node[]> = {
__BODY__
};
const ALIAS: Record<string, string> = { sparkle: "build", bolt: "build", folder: "layers", grid: "layers", users: "info", globe: "info" };

export const CY_ICON_NAMES = Object.keys(I);

export function CyIcon({ name, size = 16, className = "", strokeWidth = 1.6, fill }: { name: string; size?: number; className?: string; strokeWidth?: number; fill?: boolean }) {
  const nodes = I[name] ?? I[ALIAS[name] ?? ""] ?? I.info;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={fill ? "currentColor" : "none"} stroke="currentColor" strokeWidth={strokeWidth}
         strokeLinecap="round" strokeLinejoin="round" className={`flex-none ${className}`} aria-hidden="true">
      {nodes.map(([t, a], i) => createElement(t, { key: i, ...a }))}
    </svg>
  );
}

/** The Cyrus mark: a machined hex with a counter-set inner facet and one signal point. Monochrome + accent. */
export function CyrusMark({ size = 28, className = "" }: { size?: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" className={`cy-mark flex-none ${className}`} aria-hidden="true">
      <path d="M16 3.5 26.8 9.75v12.5L16 28.5 5.2 22.25V9.75Z" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" />
      <path d="M16 9.6 21.55 12.8v6.4L16 22.4l-5.55-3.2v-6.4Z" fill="none" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round" opacity=".55" />
      <path d="M16 3.5v6.1M26.8 9.75l-5.25 3.05M26.8 22.25l-5.25-3.05M16 28.5v-6.1M5.2 22.25l5.25-3.05M5.2 9.75l5.25 3.05" stroke="currentColor" strokeWidth=".8" opacity=".35" />
      <circle cx="16" cy="16" r="2.4" fill="var(--cy-accent)" />
    </svg>
  );
}

/** "Built with Cyrus": a small machined plate (hex mark + mono caps), no sparkle. */
export function CyrusBadge({ version, className = "" }: { version?: string | null; className?: string }) {
  return (
    <span className={`cy-badge ${className}`} aria-label={`Built with Cyrus${version ? `, ${version}` : ""}`}>
      <span className="cy-badge-m"><CyrusMark size={12} /></span>
      <span className="cy-badge-t">Built with Cyrus</span>
      {version && <span className="cy-badge-v">{version}</span>}
    </span>
  );
}

/** Model tier mark: three ascending ticks, the model's tier filled. Replaces the old colour dots. */
export function ModelMark({ tier, className = "" }: { tier: 1 | 2 | 3; className?: string }) {
  return (
    <span className={`cy-mm ${className}`} aria-hidden="true">
      {[1, 2, 3].map((i) => <i key={i} className={i <= tier ? "on" : ""} />)}
    </span>
  );
}

/** Neutral game mark: a two-letter text tile (no official logos or art). */
export function GameMark({ mark, size = 22, className = "" }: { mark: string; size?: number; className?: string }) {
  return <span className={`cy-gm ${className}`} style={{ width: size, height: size, fontSize: Math.round(size * 0.4) }} aria-hidden="true">{mark}</span>;
}
'''
open('components/cyrus/icons.tsx','w').write(tsx.replace('__BODY__',body))
EOF
