function LevelMeter({ level }: { level: React.MutableRefObject<number> }) {
  const box = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const bars = Array.from(box.current?.children || []) as HTMLElement[];
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const shape = [0.55, 0.8, 1, 0.8, 0.55];
    let raf = 0, last = 0, smooth = 0;
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (now - last < 60) return;
      last = now;
      smooth += (Math.min(1, level.current * 1.6) - smooth) * 0.35;
      const idle = 0.22 + 0.06 * Math.sin(now / 520);
      bars.forEach((b, i) => { b.style.transform = `scaleY(${Math.max(idle, 0.2 + smooth * shape[i] * 0.8).toFixed(3)})`; });
    };
    if (reduce) bars.forEach((b) => { b.style.transform = "scaleY(.5)"; });
    else raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [level]);
  return <span ref={box} className="cy-level" aria-hidden="true">{Array.from({ length: 5 }, (_, i) => <i key={i} />)}</span>;
}
'''
