      const run = n.spec.status === "running" || n.spec.live;
      if (!run && n.flash < 0.05) continue;
      const a = (run ? 0.32 + 0.08 * Math.sin(this.time * 2 + n.phase) : 0) + n.flash * 0.25;
      const size = (4.2 + n.flash * 1.2) * n.r;
      if (size * k < 10) continue;
      ctx.globalCompositeOperation = P.add;
      ctx.globalAlpha = Math.min(1, a) * n.alpha * P.glowA * (hov && hov !== n ? 0.55 : 1);
