    }
    this.drawSats(hovRaw);
    this.drawCore();
    // the loom's centre is branded, quietly
    if (this.scene?.mode === "home" && this.core.alpha > 0.5) this.queueLabel(this.core, "C\u2009Y\u2009R\u2009U\u2009S", 0.8 * this.core.alpha, { r: CORE_R + 22, size: 10, weight: 600, color: P.labelDim, prio: 3, mono: true });

    // labels in screen space; low-priority ones give way instead of overlapping
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const placed: { x: number; y: number; w: number; h: number }[] = [];
    const order = this.labelQ.map((l, i) => ({ l, i })).sort((a, b) => (b.l.prio - a.l.prio) || (a.i - b.i));
    for (const { l } of order) {
      const spr = this.labelSprite(l.text, l.size, l.color, l.weight, l.mono);
      const w = spr.width / dpr, h = spr.height / dpr;
      const x = Math.round(l.x - w / 2), y = Math.round(l.above ? l.y - h + 6 : l.y - 6);
      const box = { x: x + 6, y: y + 5, w: w - 12, h: h - 10 };
      if (l.prio < 2 && placed.some((b) => box.x < b.x + b.w && box.x + box.w > b.x && box.y < b.y + b.h && box.y + box.h > b.y)) continue;
      placed.push(box);
      ctx.globalAlpha = l.alpha;
      ctx.drawImage(spr, x, y, w, h);
