    ctx.globalAlpha = 1;
    this.positionPins();
  }

  private queueLabel(n: N, text: string, alpha: number, o: { color?: string; size?: number; weight?: number; above?: boolean; r?: number; prio?: number; mono?: boolean } = {}) {
    if (alpha < 0.03) return;
    const p = this.screenPos(n);
    const rr = (o.r ?? n.r) * this.cam.k;
    const above = !!o.above;
    const t = text.length > 26 ? text.slice(0, 25) + "…" : text;
    this.labelQ.push({ x: p.x, y: above ? p.y - rr - 6 : p.y + rr + 6, text: t, alpha, color: o.color ?? this.pal.labelInk, size: o.size ?? 12, weight: o.weight ?? 500, above, prio: o.prio ?? 2, mono: !!o.mono });
  }

  private drawOrb(n: N, hov: N | null) {
    const { ctx } = this; const P = this.pal; const hair = 1 / this.cam.k; const t = this.time; const k = this.cam.k;
    const isHov = hov === n;
    const dim = hov && !isHov ? 0.6 : 1;
    const run = n.spec.status === "running" || n.spec.live;
    const bad = n.spec.status === "bad";
    const tone = this.tone(n);
    const grow = Math.min(1, n.alpha * 1.15);
    const r = n.r * (0.6 + 0.4 * grow) + (isHov ? 1.5 : 0);
    ctx.globalAlpha = n.alpha * dim;
    // body: a flat, machined disc (Java) or square (resource), hairline rim
    const square = n.kind === "res";
    const shape = (rr: number) => {
      ctx.beginPath();
      if (square) { const s = rr * 0.9; ctx.roundRect(n.x - s, n.y - s, s * 2, s * 2, Math.max(1, s * 0.22)); }
      else ctx.arc(n.x, n.y, rr, 0, TAU);
    };
    shape(r);
    ctx.fillStyle = P.body; ctx.fill();
    ctx.lineWidth = (isHov ? 1.5 : 1.1) * hair;
    ctx.strokeStyle = rgba(run || bad ? tone : P.ink, (run || bad ? 0.85 : 0.34) + (isHov ? 0.4 : 0) + n.flash * 0.3);
    ctx.stroke();
    if (r * k >= 7) {
      if (n.spec.constellation) {
        // the mod's own constellation, monochrome (same as the dock glyph)
        const c = constellation(n.spec.constellation);
        const sc = (r * 0.8) / 15;
        ctx.beginPath();
        for (const [a, b] of c.edges) { ctx.moveTo(n.x + c.pts[a].x * sc, n.y + c.pts[a].y * sc); ctx.lineTo(n.x + c.pts[b].x * sc, n.y + c.pts[b].y * sc); }
        ctx.lineWidth = 0.6 * hair; ctx.strokeStyle = rgba(P.ink, 0.3); ctx.stroke();
        const big = c.pts.reduce((m, p, i) => (p.s > c.pts[m].s ? i : m), 0);
        c.pts.forEach((p, i) => {
          ctx.beginPath(); ctx.arc(n.x + p.x * sc, n.y + p.y * sc, Math.max(0.6, p.s * sc * (i === big ? 0.95 : 0.75)), 0, TAU);
          ctx.fillStyle = rgba(i === big && run ? P.accent : P.ink, i === big ? 1 : 0.62); ctx.fill();
        });
      } else {
        const gl = n.spec.glyph ?? (n.spec.label[0] || "?").toUpperCase();
        ctx.fillStyle = rgba(run ? P.accent : P.ink, run ? 1 : 0.82);
        ctx.font = `500 ${Math.max(6, r * (gl.length > 1 ? 0.6 : 0.74))}px ${this.mono}`;
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText(gl, n.x, n.y + r * 0.04);
      }
    }
