    if (run) {
      const p = n.spec.progress;
      if (p !== undefined && n.kind === "mod") {
        ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(P.ink, 0.12); ctx.stroke();
        ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, -Math.PI / 2, -Math.PI / 2 + TAU * Math.max(0.04, Math.min(1, p))); ctx.lineWidth = 1.8 * hair; ctx.strokeStyle = rgba(P.accent, 0.95); ctx.stroke();
      }
      if (!this.reduced) {
        const rr = r + (p !== undefined ? 10 : 5);
        ctx.beginPath(); ctx.arc(n.x, n.y, rr, t * 1.4 + n.phase, t * 1.4 + n.phase + Math.PI * 0.45);
        ctx.lineWidth = hair; ctx.strokeStyle = rgba(P.accent, 0.7); ctx.stroke();
      }
    }
    if (bad) {
      ctx.save(); ctx.setLineDash([2 * hair, 3 * hair]);
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = hair; ctx.strokeStyle = rgba(P.alert, 0.7); ctx.stroke(); ctx.restore();
    }
    ctx.globalAlpha = 1;
    // Project webs get busy: label the key files (main class, plugin.yml, config.yml), the one
    // being written, fresh arrivals and the hovered one; zoom in to read every label.
    const building = !!this.scene?.stage && !["succeeded", "failed"].includes(this.scene.stage.status);
    const fresh = building && this.time - n.born < 4.5;
    const showLabel = n.kind === "mod" ? isHov || k > 0.42 : isHov || this.focusId === n.id || n.spec.live || (n.spec.weight ?? 0) >= 3 || fresh || k > 1.3 || this.nodes.length <= 7;
    if (showLabel) this.queueLabel(n, n.spec.label, (isHov ? 1 : 0.9) * n.alpha * dim, { r: r + (run ? 11 : 3), size: n.kind === "mod" ? 12.5 : 12, weight: isHov ? 600 : 500, color: n.spec.live ? rgba(P.accent, 1) : undefined, prio: 2 });
  }

  private drawGhost(n: N, hov: N | null) {
    const { ctx } = this; const P = this.pal; const hair = 1 / this.cam.k;
    const on = hov === n;
    ctx.globalAlpha = n.alpha;
    ctx.save();
    ctx.setLineDash([2.5 * hair, 3 * hair]); ctx.lineDashOffset = -this.time * 4;
    ctx.beginPath(); ctx.arc(n.x, n.y, n.r + (on ? 1.5 : 0), 0, TAU);
    ctx.fillStyle = P.body; ctx.fill();
    ctx.lineWidth = hair; ctx.strokeStyle = rgba(on ? P.accent : P.ink, on ? 0.95 : 0.45); ctx.stroke();
    ctx.restore();
    ctx.beginPath();
    ctx.moveTo(n.x - 4.5, n.y); ctx.lineTo(n.x + 4.5, n.y); ctx.moveTo(n.x, n.y - 4.5); ctx.lineTo(n.x, n.y + 4.5);
    ctx.lineWidth = 1.4 * hair; ctx.strokeStyle = rgba(on ? P.accent : P.ink, on ? 1 : 0.75); ctx.stroke();
    ctx.globalAlpha = 1;
    this.queueLabel(n, n.spec.label, (on ? 1 : 0.8) * n.alpha, { color: on ? P.labelInk : P.labelDim, size: 12, prio: 2 });
  }

  private drawSeed(n: N, hov: N | null) {
    // A template seed: a small marker (dot + hairline ring); opens up on hover.
    const { ctx } = this; const P = this.pal; const hair = 1 / this.cam.k;
    const on = hov === n || this.focusId === n.id;
    ctx.globalAlpha = n.alpha;
    ctx.beginPath(); ctx.arc(n.x, n.y, n.r * (on ? 1.2 : 0.8), 0, TAU);
    ctx.lineWidth = 0.8 * hair; ctx.strokeStyle = rgba(on ? P.accent : P.ink, on ? 0.9 : 0.22); ctx.stroke();
    ctx.beginPath(); ctx.arc(n.x, n.y, on ? 2.4 : 1.5, 0, TAU); ctx.fillStyle = rgba(on ? P.accent : P.ink, on ? 1 : 0.5); ctx.fill();
    ctx.globalAlpha = 1;
    if (on) this.queueLabel(n, n.spec.label, n.alpha, { size: 11.5, prio: 3 });
  }

  private drawSats(hovRaw: N | null) {
    const { ctx } = this; const P = this.pal; const k = this.cam.k; const hair = 1 / k;
    const projectMode = this.scene?.mode === "project";
    for (const n of this.sats) {
      const v = n.vis;
      if (v < 0.05) continue;
      const isHov = hovRaw === n;
      const r = n.r * (0.45 + 0.55 * v) * (isHov ? 1.25 : 1);
      ctx.globalAlpha = Math.min(1, 0.25 + 0.75 * v);
      ctx.save();
      if (Math.abs(this.cam.t - 1) > 0.001) { ctx.translate(n.x, n.y); ctx.scale(1, 1 / this.cam.t); ctx.translate(-n.x, -n.y); }
      const stroke = rgba(n.spec.status === "bad" ? P.alert : n.spec.status === "running" ? P.accent : P.ink, isHov ? 1 : 0.7);
      ctx.lineWidth = (isHov ? 1.4 : 1) * hair; ctx.strokeStyle = stroke; ctx.fillStyle = P.body;
      if (n.kind === "ver") {
        const d = r * 1.3;
        ctx.beginPath(); ctx.moveTo(n.x, n.y - d); ctx.lineTo(n.x + d, n.y); ctx.lineTo(n.x, n.y + d); ctx.lineTo(n.x - d, n.y); ctx.closePath();
        ctx.fill(); ctx.stroke();
        if (n.spec.status === "ok") { ctx.fillStyle = rgba(P.ink, 0.5); ctx.fill(); }
        if (n.spec.status === "running") { ctx.beginPath(); ctx.arc(n.x, n.y, d * 0.35, 0, TAU); ctx.fillStyle = rgba(P.accent, 1); ctx.fill(); }
      } else if (n.kind === "cmd") {
        // command: a small square
        const s = r * 1.05; ctx.beginPath(); ctx.rect(n.x - s, n.y - s, s * 2, s * 2); ctx.fill(); ctx.stroke();
      } else if (n.kind === "perm") {
        // permission: a diamond
        const d = r * 1.3; ctx.beginPath(); ctx.moveTo(n.x, n.y - d); ctx.lineTo(n.x + d, n.y); ctx.lineTo(n.x, n.y + d); ctx.lineTo(n.x - d, n.y); ctx.closePath(); ctx.fill(); ctx.stroke();
      } else {
        // setting: a ring with a dot
        ctx.beginPath(); ctx.arc(n.x, n.y, r * 1.1, 0, TAU); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.arc(n.x, n.y, Math.max(0.6, r * 0.35), 0, TAU); ctx.fillStyle = stroke; ctx.fill();
      }
      ctx.restore();
      ctx.globalAlpha = 1;
      // satellites are labelled in the project weave (they give way when crowded); on hover always
      const show = isHov || (projectMode && v > 0.85) || (!projectMode && v > 0.85 && k > 1.6);
      if (show) {
        const above = n.y < n.owner!.y - 1;
        this.queueLabel(n, n.spec.label, (isHov ? 1 : 0.85) * v, { r: r + 1, size: 10.5, color: isHov ? P.labelInk : P.labelDim, above, weight: 500, prio: isHov ? 3 : 1, mono: true });
      }
    }
  }

  private drawCore() {
    const n = this.core;
    if (n.alpha < 0.02) return;
    const { ctx } = this; const P = this.pal; const hair = 1 / this.cam.k; const t = this.reduced ? 0 : this.time;
    const scene = this.scene;
    const offline = !!scene?.offline;
    const e = this.energyS;
    ctx.globalAlpha = n.alpha;
    const hex = (r: number, rot: number) => {
      ctx.beginPath();
      for (let i = 0; i < 6; i++) { const a = rot + (i / 6) * TAU - Math.PI / 2; const x = n.x + Math.cos(a) * r, y = n.y + Math.sin(a) * r; if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y); }
      ctx.closePath();
    };
    // orbits: two fine dashed rings, counter-turning very slowly
    ctx.lineWidth = hair;
    for (let i = 0; i < 2; i++) {
      ctx.save(); ctx.setLineDash([1.5 * hair, 6 * hair]); ctx.lineDashOffset = (i ? -1 : 1) * t * 5;
