    if (st) this.drawStageRing(st);
    this.upright(n, () => this.drawCrystal(n, st, offline, e, t, hair, hex));
    ctx.globalAlpha = 1;
  }

  private drawCrystal(n: N, st: WebStage | null | undefined, offline: boolean, e: number, t: number, hair: number, hex: (r: number, rot: number) => void) {
    const { ctx } = this; const P = this.pal;
    const busy = !!st && !["succeeded", "failed"].includes(st.status);
    // a restrained halo of the signal: brighter while you type / talk / it builds
    ctx.globalCompositeOperation = P.add;
    const hs = n.r * (3.6 + e * 2 + n.flash * 1.5 + (busy ? 0.4 + 0.3 * Math.sin(t * 1.8) : 0));
    ctx.globalAlpha = n.alpha * (offline ? 0.08 : 0.2 + e * 0.25 + (busy ? 0.08 : 0)) * P.glowA;
    ctx.drawImage(this.sprite(st?.status === "failed" ? P.alert : P.glow, "h"), n.x - hs / 2, n.y - hs / 2, hs, hs);
    ctx.globalAlpha = n.alpha;
    ctx.globalCompositeOperation = "source-over";
    // machined hex: ink rim, counter-set inner facet, facet lines
    const rot = t * (0.06 + e * 0.35);
    hex(n.r, rot);
    ctx.fillStyle = P.body; ctx.fill();
    ctx.lineWidth = 1.4 * hair; ctx.strokeStyle = rgba(P.ink, offline ? 0.4 : 0.85); ctx.stroke();
    const rot2 = -t * 0.12 * (1 + e);
    hex(n.r * 0.56, rot2);
    ctx.lineWidth = hair; ctx.strokeStyle = rgba(P.ink, 0.45); ctx.stroke();
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a1 = rot + (i / 6) * TAU - Math.PI / 2, a2 = rot2 + (i / 6) * TAU - Math.PI / 2;
      ctx.moveTo(n.x + Math.cos(a2) * n.r * 0.56, n.y + Math.sin(a2) * n.r * 0.56); ctx.lineTo(n.x + Math.cos(a1) * n.r, n.y + Math.sin(a1) * n.r);
    }
    ctx.lineWidth = 0.7 * hair; ctx.strokeStyle = rgba(P.ink, 0.22); ctx.stroke();
    // the signal point
    const p = 1 + 0.12 * Math.sin(t * 1.6) + e * 0.35;
    const cr = 4.2 * p;
    ctx.beginPath(); ctx.arc(n.x, n.y, cr, 0, TAU);
    ctx.fillStyle = offline ? rgba(P.dim, 0.9) : st?.status === "failed" ? rgba(P.alert, 1) : rgba(P.accent, 1); ctx.fill();
    if (!offline) {
      ctx.globalCompositeOperation = P.add;
      ctx.globalAlpha = n.alpha * 0.6 * P.glowA;
      const s = 26 * p;
      ctx.drawImage(this.sprite(P.glow, "h"), n.x - s / 2, n.y - s / 2, s, s);
      ctx.globalAlpha = n.alpha; ctx.globalCompositeOperation = "source-over";
    }
  }

  private drawStageRing(st: WebStage) {
    const { ctx } = this; const P = this.pal; const n = this.core; const hair = 1 / this.cam.k; const t = this.time;
    const R = n.r + 44;
    const seg = TAU / STAGES.length;
    const gap = 0.06;
    const cur = STAGES.indexOf(st.status);
    const done = st.status === "succeeded";
    const failed = st.status === "failed";
    STAGES.forEach((key, i) => {
      const a0 = -Math.PI / 2 + i * seg + gap, a1 = -Math.PI / 2 + (i + 1) * seg - gap;
      let state: "done" | "now" | "skip" | "pending" = "pending";
      if (done) state = key === "repairing" && !st.repairs ? "skip" : "done";
      else if (failed) state = st.seen.includes(key) ? "done" : "pending";
      else if (i < cur) state = key === "repairing" && !st.repairs ? "skip" : "done";
      else if (i === cur) state = "now";
      ctx.beginPath(); ctx.arc(n.x, n.y, R, a0, a1);
      ctx.lineWidth = 2 * hair;
      ctx.strokeStyle = state === "pending" ? rgba(P.ink, 0.1) : state === "skip" ? rgba(P.ink, 0.18)
        : failed ? rgba(P.alert, 0.8) : key === "repairing" && st.repairs ? rgba(P.alert, state === "now" ? 0.3 : 0.75) : state === "now" ? rgba(P.accent, 0.25) : rgba(P.ink, 0.7);
      if (state === "skip") { ctx.save(); ctx.setLineDash([2 * hair, 4 * hair]); ctx.stroke(); ctx.restore(); } else ctx.stroke();
      if (done && i === STAGES.length - 1) { ctx.beginPath(); ctx.arc(n.x, n.y, R, a0, a1); ctx.strokeStyle = rgba(P.accent, 0.9); ctx.stroke(); }
      if (state === "now") {
        // the current stage fills with a slow travelling sweep
        const sweep = this.reduced ? 0.6 : (t * 0.3) % 1;
        const b0 = a0 + (a1 - a0) * Math.max(0, sweep - 0.4), b1 = a0 + (a1 - a0) * sweep;
        ctx.beginPath(); ctx.arc(n.x, n.y, R, b0, Math.max(b0 + 0.01, b1));
        ctx.lineWidth = 2.4 * hair; ctx.strokeStyle = rgba(key === "repairing" ? P.alert : P.accent, 1); ctx.stroke();
      }
      // a tick at each stage boundary (HUD)
      ctx.beginPath(); ctx.moveTo(n.x + Math.cos(a0 - gap) * (R - 4), n.y + Math.sin(a0 - gap) * (R - 4)); ctx.lineTo(n.x + Math.cos(a0 - gap) * (R + 4), n.y + Math.sin(a0 - gap) * (R + 4));
      ctx.lineWidth = hair; ctx.strokeStyle = rgba(P.ink, 0.3); ctx.stroke();
    });
  }

