//   DISCLAIMS ALL WARRANTIES WITH REGARD TO THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF
//   MERCHANTABILITY AND FITNESS. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR ANY SPECIAL,
//   DIRECT, INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES WHATSOEVER RESULTING FROM LOSS
//   OF USE, DATA OR PROFITS, WHETHER IN AN ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS
//   ACTION, ARISING OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS SOFTWARE.
//   Feather: The MIT License (MIT), Copyright (c) 2013-present Cole Bemis.
import { createElement, useId } from "react";

type Node = [string, Record<string, string>];
const I: Record<string, Node[]> = {
__BODY__
};
const ALIAS: Record<string, string> = { sparkle: "generate", bolt: "generate", grid: "grid2", users: "account", restore: "history", note: "notes", notes: "docs", versions: "branch", files: "folder", explain2: "explain" };

export const CY_ICON_NAMES = Object.keys(I);

/** Neon tones: [from, to, glow]. Branch colours of the web use the same hues. */
export const NEON: Record<string, [string, string, string]> = {
  violet: ["#6d7bff", "#c04dff", "rgba(150,90,255,.55)"],
  blue: ["#38bdf8", "#5b6cff", "rgba(70,140,255,.55)"],
  cyan: ["#5ef0ff", "#22a6ee", "rgba(40,200,240,.5)"],
  green: ["#5cffc0", "#22d3a0", "rgba(40,230,170,.5)"],
  pink: ["#ff7ae6", "#c04dff", "rgba(255,80,220,.5)"],
  magenta: ["#ff5ad8", "#8b5cff", "rgba(220,70,255,.5)"],
  amber: ["#ffd36b", "#ff7a3d", "rgba(255,170,70,.5)"],
  red: ["#ff6b6b", "#ff3d7f", "rgba(255,80,110,.5)"],
  ink: ["#e9ecff", "#b9c2ff", "rgba(160,170,255,.35)"],
};

/** One hidden <svg> with every gradient, mounted once by the app (and in portalled modals). */
export function NeonDefs() {
  return (
    <svg width="0" height="0" style={{ position: "absolute", width: 0, height: 0, overflow: "hidden" }} aria-hidden="true" focusable="false">
      <defs>
        {Object.entries(NEON).map(([k, [a, b]]) => (
          <linearGradient key={k} id={`cyg-${k}`} gradientUnits="userSpaceOnUse" x1="2" y1="2" x2="22" y2="22">
            <stop offset="0" stopColor={a} /><stop offset="1" stopColor={b} />
          </linearGradient>
        ))}
        {Object.entries(NEON).map(([k, [a, b]]) => (
          <linearGradient key={`e${k}`} id={`cyge-${k}`} gradientUnits="userSpaceOnUse" x1="4" y1="4" x2="44" y2="44">
            <stop offset="0" stopColor={a} /><stop offset="1" stopColor={b} />
          </linearGradient>
        ))}
      </defs>
    </svg>
  );
}

export function CyIcon({ name, size = 16, className = "", strokeWidth = 1.6, fill, tone }: { name: string; size?: number; className?: string; strokeWidth?: number; fill?: boolean; tone?: string }) {
  const nodes = I[name] ?? I[ALIAS[name] ?? ""] ?? I.info;
  const stroke = tone ? `url(#cyg-${tone})` : "currentColor";
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={fill ? stroke : "none"} stroke={stroke} strokeWidth={strokeWidth}
         strokeLinecap="round" strokeLinejoin="round" className={`flex-none ${tone ? `cy-neon cy-tone-${tone}` : ""} ${className}`} aria-hidden="true">
      {nodes.map(([t, a], i) => createElement(t, { key: i, ...a }))}
    </svg>
  );
}

/** The Cyrus mark = the Nxeon X (the real brand asset), so Cyrus reads as part of Nxeon. */
export function CyrusMark({ size = 28, className = "" }: { size?: number; className?: string }) {
  // eslint-disable-next-line @next/next/no-img-element
  return <img src="/nx-mark.png" alt="" aria-hidden="true" className={`cy-mark flex-none select-none object-contain ${className}`} style={{ height: size, width: "auto" }} />;
}

/** "Built with Cyrus": a small dark plate with the X mark and a hairline neon edge. No sparkle. */
export function CyrusBadge({ version, className = "" }: { version?: string | null; className?: string }) {
  return (
    <span className={`cy-badge ${className}`} aria-label={`Built with Cyrus${version ? `, ${version}` : ""}`}>
      <CyrusMark size={11} />
      <span className="cy-badge-t">Built with Cyrus</span>
      {version && <span className="cy-badge-v">{version}</span>}
    </span>
  );
}

/** Model tier mark: three ascending ticks, the model's tier lit. */
export function ModelMark({ tier, className = "" }: { tier: 1 | 2 | 3; className?: string }) {
  return (
    <span className={`cy-mm ${className}`} aria-hidden="true">
      {[1, 2, 3].map((i) => <i key={i} className={i <= tier ? "on" : ""} />)}
    </span>
  );
}

/** Neutral two-letter game tile (small spaces: lists, chips). */
export function GameMark({ mark, size = 22, className = "" }: { mark: string; size?: number; className?: string }) {
  return <span className={`cy-gm ${className}`} style={{ width: size, height: size, fontSize: Math.max(8, Math.round(size * 0.4)) }} aria-hidden="true">{mark}</span>;
}

/** Isometric mod cube, tinted by its category (top lit, sides shaded, bright edges). */
export function ModCube({ hue = "#8b6dff", size = 18, className = "" }: { hue?: string; size?: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" className={`flex-none cy-cube ${className}`} aria-hidden="true" style={{ ["--hue" as string]: hue }}>
      <path d="M12 2.6 20.6 7.3 12 12 3.4 7.3Z" fill={hue} opacity=".95" />
      <path d="M3.4 7.3 12 12v9.4l-8.6-4.7Z" fill={hue} opacity=".55" />
      <path d="M20.6 7.3 12 12v9.4l8.6-4.7Z" fill={hue} opacity=".3" />
      <path d="M12 2.6 20.6 7.3v9.4L12 21.4 3.4 16.7V7.3Z M3.4 7.3 12 12l8.6-4.7 M12 12v9.4" fill="none" stroke="#fff" strokeOpacity=".75" strokeWidth=".9" strokeLinejoin="round" />
      <path d="M7.2 10.9v4.2l3 1.6v-4.2Z" fill="#fff" opacity=".28" />
    </svg>
  );
}

/** Original game emblems (48-grid). Evocative, not official marks. */
export function GameEmblem({ game, size = 40, className = "" }: { game: string; size?: number; className?: string }) {
  const uid = useId().replace(/:/g, "");
