};

/** One hidden <svg> with every gradient, mounted once by the app (and in portalled modals). */
export function NeonDefs() {
  return (
    <svg width="0" height="0" style={{ position: "absolute", width: 0, height: 0, overflow: "hidden" }} aria-hidden="true" focusable="false">
      <defs>
        {Object.entries(NEON).map(([k, [a, b]]) => (
          <linearGradient key={k} id={`cyg-${k}`} gradientUnits="userSpaceOnUse" x1="2" y1="2" x2="22" y2="22">
            <stop offset="0" stopColor={a} /><stop offset="1" stopColor={b} />
          </linearGradient>
        ))}
        {Object.entries(NEON).map(([k, [a, b]]) => (
          <linearGradient key={`e${k}`} id={`cyge-${k}`} gradientUnits="userSpaceOnUse" x1="4" y1="4" x2="44" y2="44">
            <stop offset="0" stopColor={a} /><stop offset="1" stopColor={b} />
          </linearGradient>
        ))}
      </defs>
    </svg>
  );
}

export function CyIcon({ name, size = 16, className = "", strokeWidth = 1.6, fill, tone }: { name: string; size?: number; className?: string; strokeWidth?: number; fill?: boolean; tone?: string }) {
  const nodes = I[name] ?? I[ALIAS[name] ?? ""] ?? I.info;
  const stroke = tone ? `url(#cyg-${tone})` : "currentColor";
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={fill ? stroke : "none"} stroke={stroke} strokeWidth={strokeWidth}
         strokeLinecap="round" strokeLinejoin="round" className={`flex-none ${tone ? `cy-neon cy-tone-${tone}` : ""} ${className}`} aria-hidden="true">
