// Cyrus web v4: the hierarchy the owner drew. Cyrus core -> game branch -> mod-category branch
// -> mod branch. Pure (no DOM), unit-tested in test/cyrus.test.ts.
//
// World units are CSS px at zoom 1, the core sits at (0, 0). Slots follow the owner's concept
// (/root/agent-notes/cyrus-v4/owner-concept.png): the live game up top with its categories fanned
// across the top-right, games that are coming soon on the left and right, "+ Add Game" bottom-right.
import { isTerminal } from "@/lib/modbuilder/types";
import { CYRUS_GAMES, type CyrusGame } from "@/lib/cyrus/games";
import { CYRUS_CATEGORIES, TEMPLATE_CATEGORY, classifyMod, cyrusCategory, type CyrusCategoryId } from "@/lib/cyrus/categories";
import type { CyrusProject } from "@/lib/cyrus/projects";
import type { CyrusTemplate } from "@/lib/cyrus/templates";

export type TreeKind = "core" | "game" | "cat" | "mod" | "tpl" | "start" | "more" | "leaf" | "dots" | "add";
export type TreeStatus = "idle" | "running" | "ok" | "bad";

export interface TreeNode {
  id: string;
  kind: TreeKind;
  label: string;
  parent: string | null;
  x: number; y: number;
  /** pill width (world px) for pills; radius for circles */
  w: number;
  /** where threads attach: "l" = left edge, "r" = right edge, "c" = centre */
  anchor: "l" | "r" | "c";
  hue: string;
  icon?: string;
  game?: string;
  cat?: CyrusCategoryId;
  status?: TreeStatus;
  progress?: number;
  soon?: boolean;
  /** project root id (mods), template id (tpl), category (start/more) */
  ref?: string;
}

export interface TreeModel { nodes: TreeNode[]; byId: Map<string, TreeNode>; bounds: { x0: number; y0: number; x1: number; y1: number } }

const D2R = Math.PI / 180;
const at = (deg: number, r: number) => ({ x: Math.cos(deg * D2R) * r, y: Math.sin(deg * D2R) * r });

/** Game slots (deg, radius). Live games take the top slot(s); the rest fill the soon slots in order. */
const LIVE_SLOTS = [[-82, 195]];
const SOON_SLOTS = [[208, 240], [176, 215], [145, 255], [-10, 195], [21, 195], [235, 300], [120, 300]];
const ADD_SLOT = [49, 245];
/** Category slots around the live game (deg, radius from the core). */
const CAT_SLOTS: [number, number][] = [[-113, 282], [-61, 289], [-36, 292], [-11, 286], [17, 288], [40, 335], [62, 372]];
/** Branch hue per game (core -> game threads). */
export const GAME_HUE: Record<string, string> = { minecraft: "#34e3a2", ark: "#7c5cff", theisle: "#4f8dff", palworld: "#ff5ad8", rust: "#ff5a6a", valheim: "#ff9a3d" };
/** Placeholder leaves for games that are not live yet (their branch structure, dimmed). */
const SOON_LEAVES: [string, string][] = [["cube", "Mods"], ["paw", "Creatures"], ["sword", "Combat"]];
const LEAF_OFFSETS = [[-100, -82], [-124, -36], [-126, 10]];
const DOTS_OFFSET = [-96, 46];

export const PILL_H = 24;
export const ROW = 31;
/** Rough pill width from its text (11.5px Geist): the DOM uses the same width so threads meet the edge. */
export const pillWidth = (label: string, extra = 0) => Math.round(Math.min(190, 40 + label.length * 6.4 + extra));

const modStatus = (p: CyrusProject): TreeStatus => (p.running ? "running" : p.head ? "ok" : "bad");
const PROGRESS: Record<string, number> = { queued: 0.04, planning: 0.14, coding: 0.4, compiling: 0.62, repairing: 0.72, scanning: 0.88 };

/** The category a project belongs to (its own words; stable across versions). */
export function projectCategory(p: CyrusProject): CyrusCategoryId {
  const b = p.head ?? p.latest;
  const s = b.result?.summary;
  return classifyMod({ title: `${p.title} ${b.pluginName ?? ""}`, text: [s?.tagline, s?.text, p.builds[0]?.prompt].filter(Boolean).join(" ") });
}

export function buildTree(projects: CyrusProject[], templates: CyrusTemplate[], opts: { games?: CyrusGame[]; perCat?: number; selectedRoot?: string | null } = {}): TreeModel {
  const games = opts.games ?? CYRUS_GAMES;
  const per = opts.perCat ?? 3;
  const nodes: TreeNode[] = [];
  nodes.push({ id: "core", kind: "core", label: "Cyrus", parent: null, x: 0, y: 0, w: 64, anchor: "c", hue: "#8b5cff" });

  const live = games.filter((g) => g.status === "live");
  const soon = games.filter((g) => g.status !== "live");
  live.forEach((g, i) => {
    const [deg, r] = LIVE_SLOTS[i] ?? [-82 + i * 30, 200];
    const p = at(deg, r);
    nodes.push({ id: `g:${g.id}`, kind: "game", label: g.name, parent: "core", ...p, w: 36, anchor: "c", hue: GAME_HUE[g.id] ?? "#7c5cff", game: g.id });
  });
  soon.forEach((g, i) => {
    const [deg, r] = SOON_SLOTS[i] ?? [90 + i * 20, 300];
    const p = at(deg, r);
    const hue = GAME_HUE[g.id] ?? "#7c5cff";
    nodes.push({ id: `g:${g.id}`, kind: "game", label: g.name, parent: "core", ...p, w: 34, anchor: "c", hue, game: g.id, soon: true });
    // games on the left show their (future) branches as dimmed leaves
    if (p.x < -60) {
      SOON_LEAVES.forEach(([icon, label], j) => nodes.push({ id: `l:${g.id}:${j}`, kind: "leaf", label, parent: `g:${g.id}`, x: p.x + LEAF_OFFSETS[j][0], y: p.y + LEAF_OFFSETS[j][1], w: 15, anchor: "c", hue, icon, game: g.id, soon: true }));
      nodes.push({ id: `d:${g.id}`, kind: "dots", label: "…", parent: `g:${g.id}`, x: p.x + DOTS_OFFSET[0], y: p.y + DOTS_OFFSET[1], w: 30, anchor: "c", hue, game: g.id, soon: true });
    }
  });
  const add = at(ADD_SLOT[0], ADD_SLOT[1]);
  nodes.push({ id: "add", kind: "add", label: "Add Game", parent: "core", ...add, w: 32, anchor: "c", hue: "#7c5cff" });

  // the live game's categories + mods (all current builds are Minecraft builds)
  const g0 = live[0];
  if (g0) {
    const byCat = new Map<CyrusCategoryId, CyrusProject[]>();
    for (const p of projects) { const c = projectCategory(p); if (!byCat.has(c)) byCat.set(c, []); byCat.get(c)!.push(p); }
    const cats = CYRUS_CATEGORIES.filter((c) => c.id !== "other" || (byCat.get("other")?.length ?? 0) > 0);
    cats.forEach((c, i) => {
      const [deg, r] = CAT_SLOTS[i] ?? [62 + (i - 6) * 20, 380];
      const cp = at(deg, r);
      const cid = `c:${c.id}`;
      nodes.push({ id: cid, kind: "cat", label: c.name, parent: `g:${g0.id}`, ...cp, w: 17, anchor: "c", hue: c.hue, icon: c.icon, cat: c.id, game: g0.id });
      // the column of mod pills: above the category (upper-left slot) or to its right
      const above = deg < -95;
      const mine = byCat.get(c.id) ?? [];
      // the selected mod is always visible in its branch
      const sel = opts.selectedRoot ? mine.find((p) => p.rootId === opts.selectedRoot) : null;
      const shown = sel && mine.indexOf(sel) >= per ? [...mine.slice(0, per - 1), sel] : mine.slice(0, per);
      type Row = { kind: TreeKind; label: string; id: string; ref?: string; status?: TreeStatus; progress?: number };
      const rows: Row[] = shown.map((p) => ({ kind: "mod", label: p.title, id: `m:${p.rootId}`, ref: p.rootId, status: modStatus(p), progress: p.running && !isTerminal(p.running.status) ? PROGRESS[p.running.status] ?? 0.1 : undefined }));
      if (mine.length > shown.length) rows.push({ kind: "more", label: `+${mine.length - shown.length} more`, id: `x:${c.id}`, ref: c.id });
      if (!mine.length) {
        for (const t of templates.filter((t) => TEMPLATE_CATEGORY[t.cat] === c.id).slice(0, 2)) rows.push({ kind: "tpl", label: t.title, id: `t:${t.id}`, ref: t.id });
        rows.push({ kind: "start", label: `New ${c.name.toLowerCase()} mod`, id: `s:${c.id}`, ref: c.id });
      }
      const widths = rows.map((r) => pillWidth(r.label, r.kind === "tpl" ? 34 : r.kind === "more" ? -16 : 0));
      if (above) {
        // column above-left of the category, right edges aligned, bottom row ~56px above it
        const right = cp.x + 30;
        rows.forEach((r, j) => {
          const y = cp.y - 62 - (rows.length - 1 - j) * ROW;
          nodes.push({ id: r.id, kind: r.kind, label: r.label, parent: cid, x: right - widths[j], y, w: widths[j], anchor: "r", hue: c.hue, cat: c.id, game: g0.id, ref: r.ref, status: r.status, progress: r.progress });
        });
      } else {
        const left = cp.x + 84 + (deg < -20 ? 26 : 0);
        const mid = cp.y + Math.max(-100, Math.min(-20, -26 + Math.min(0, deg + 20) * 1.5));
        const top = mid - ((rows.length - 1) * ROW) / 2;
        rows.forEach((r, j) => nodes.push({ id: r.id, kind: r.kind, label: r.label, parent: cid, x: left, y: top + j * ROW, w: widths[j], anchor: "l", hue: c.hue, cat: c.id, game: g0.id, ref: r.ref, status: r.status, progress: r.progress }));
      }
    });
  }

  const byId = new Map(nodes.map((n) => [n.id, n]));
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const n of nodes) {
    const pill = n.kind === "mod" || n.kind === "tpl" || n.kind === "start" || n.kind === "more";
    const l = pill ? n.x : n.x - n.w - (n.kind === "cat" ? 0 : 10), r = pill ? n.x + n.w : n.x + n.w + (n.kind === "cat" ? 130 : 10);
    const t = n.y - (pill ? PILL_H / 2 : n.w + 6), b = n.y + (pill ? PILL_H / 2 : n.w + (n.kind === "game" || n.kind === "core" || n.kind === "add" ? 30 : 6));
    x0 = Math.min(x0, l); x1 = Math.max(x1, r); y0 = Math.min(y0, t); y1 = Math.max(y1, b);
  }
  return { nodes, byId, bounds: { x0, y0, x1, y1 } };
}

/** Ids from the core down to `id` (inclusive). */
export function pathTo(model: TreeModel, id: string | null): string[] {
  const out: string[] = [];
  let n = id ? model.byId.get(id) : undefined;
  while (n) { out.unshift(n.id); n = n.parent ? model.byId.get(n.parent) : undefined; }
  return out;
}

export { cyrusCategory };

