// CyrusTree: the v4 stage. Framework-free Canvas 2D for the space, the aurora and the neon
// threads; the nodes themselves are DOM (crisp text, real buttons, SVG icons) in a layer this
// engine transforms with the camera. Light only travels when something happens (plus a slow
// ambient trickle): the selected branch carries light, a running build streams light down its
// branch, typing makes the core throw light outward. Pauses off-screen / in hidden tabs;
// prefers-reduced-motion renders static frames.
import { PILL_H, type TreeModel, type TreeNode } from "./tree-layout";

type Rgb = [number, number, number];
interface P { x: number; y: number }
interface Edge { a: TreeNode; b: TreeNode; p0: P; c1: P; c2: P; p1: P; ca: Rgb; cb: Rgb; soon: boolean; beads: number[]; key: string; len: number }
interface Pulse { e: Edge; t: number; speed: number; size: number; hot: boolean }
interface Star { x: number; y: number; z: number; s: number; tw: number; c: number }

const TAU = Math.PI * 2;
const EASE = (u: number) => (u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2);
export function hexRgb(h: string): Rgb {
  const m = /^#?([0-9a-f]{6})$/i.exec(h.trim());
  if (!m) return [139, 92, 255];
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
const rgba = (c: Rgb, a: number) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
const mix = (a: Rgb, b: Rgb, t: number): Rgb => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t].map(Math.round) as Rgb;
function rnd(seed: number) { return () => { seed = (seed * 1664525 + 1013904223) | 0; return ((seed >>> 0) % 100000) / 100000; }; }
function hash(s: string) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }

const CORE_HUE: Rgb = [124, 92, 255];
const PILL = new Set(["mod", "tpl", "start", "more"]);

export class CyrusTree {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private layer: HTMLElement;
  private W = 1; private H = 1; private dpr = 1;
  private raf = 0; private last = 0; private time = 0;
  private running = false; private visible = true; private disposed = false; private dirty = true;
  private reduced: boolean;
  private model: TreeModel | null = null;
  private edges: Edge[] = [];
  private pulses: Pulse[] = [];
  private stars: Star[] = [];
  private bg: HTMLCanvasElement | null = null;
  private aur: HTMLCanvasElement | null = null; private aurAt = -1;
  private sprites = new Map<string, HTMLCanvasElement>();
  private cam = { x: 0, y: 0, k: 1 };
  private tween: { from: { x: number; y: number; k: number }; to: { x: number; y: number; k: number }; t0: number; dur: number } | null = null;
  private region = { x: 0, y: 0, w: 1, h: 1 };
  private userMoved = false;
  private hot = new Set<string>();       // edges on the selected path
  private live = new Set<string>();      // edges on running builds' paths
  private hoverPath = new Set<string>();
  private energy = 0; private energyS = 0; private emitAcc = 0;
  private bloomT = -1;
  private drag: { sx: number; sy: number; cx: number; cy: number; moved: boolean } | null = null;
  private ro: ResizeObserver; private io: IntersectionObserver | null = null;

  constructor(canvas: HTMLCanvasElement, layer: HTMLElement) {
    this.canvas = canvas; this.layer = layer;
    this.ctx = canvas.getContext("2d", { alpha: false })!;
    this.reduced = typeof matchMedia !== "undefined" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    const r = rnd(7);
    this.stars = Array.from({ length: 420 }, () => ({ x: r() * 4000, y: r() * 3000, z: r() < 0.7 ? 0.04 : r() < 0.85 ? 0.12 : 0.26, s: r() < 0.05 ? 1.8 : r() < 0.3 ? 1.2 : 0.8, tw: r() * TAU, c: Math.floor(r() * 4) }));
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(canvas);
    if (typeof IntersectionObserver !== "undefined") {
      this.io = new IntersectionObserver((es) => { this.visible = es.some((e) => e.isIntersecting); if (this.visible) this.start(); else this.stop(); });
      this.io.observe(canvas);
    }
    canvas.addEventListener("pointerdown", this.onDown);
    window.addEventListener("pointermove", this.onMove);
    window.addEventListener("pointerup", this.onUp);
    canvas.addEventListener("wheel", this.onWheel, { passive: false });
    canvas.addEventListener("dblclick", this.onDbl);
    document.addEventListener("visibilitychange", this.onVis);
    this.resize();
    this.start();
  }

  // ------------------------------------------------------------------ API --
  setModel(model: TreeModel) {
    const fresh = !this.model;
    this.model = model;
    this.buildEdges();
