    blob(w * 0.95, h * 0.05, w * 0.4, [120, 50, 230], 0.22);
    blob(w * 0.9, h * 0.95, w * 0.45, [60, 40, 190], 0.22);
    blob(w * 0.05, h * 0.92, w * 0.35, [150, 40, 200], 0.16);
    blob(w * 0.48, h * 0.55, w * 0.32, [60, 50, 200], 0.14);
