// CyrusTree: the v4 stage. Framework-free Canvas 2D for the space, the aurora and the neon
// threads; the nodes themselves are DOM (crisp text, real buttons, SVG icons) in a layer this
// engine transforms with the camera. Light only travels when something happens (plus a slow
// ambient trickle): the selected branch carries light, a running build streams light down its
// branch, typing makes the core throw light outward. Pauses off-screen / in hidden tabs;
// prefers-reduced-motion renders static frames.
import { PILL_H, type TreeModel, type TreeNode } from "./tree-layout";

type Rgb = [number, number, number];
interface P { x: number; y: number }
interface Edge { a: TreeNode; b: TreeNode; p0: P; c1: P; c2: P; p1: P; ca: Rgb; cb: Rgb; soon: boolean; beads: number[]; key: string; len: number }
interface Pulse { e: Edge; t: number; speed: number; size: number; hot: boolean }
interface Star { x: number; y: number; z: number; s: number; tw: number; c: number }

const TAU = Math.PI * 2;
const EASE = (u: number) => (u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2);
export function hexRgb(h: string): Rgb {
  const m = /^#?([0-9a-f]{6})$/i.exec(h.trim());
  if (!m) return [139, 92, 255];
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
const rgba = (c: Rgb, a: number) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
const mix = (a: Rgb, b: Rgb, t: number): Rgb => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t].map(Math.round) as Rgb;
function rnd(seed: number) { return () => { seed = (seed * 1664525 + 1013904223) | 0; return ((seed >>> 0) % 100000) / 100000; }; }
function hash(s: string) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }

const CORE_HUE: Rgb = [124, 92, 255];
const PILL = new Set(["mod", "tpl", "start", "more"]);

export class CyrusTree {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private layer: HTMLElement;
  private W = 1; private H = 1; private dpr = 1;
  private raf = 0; private last = 0; private time = 0;
  private running = false; private visible = true; private disposed = false; private dirty = true;
  private reduced: boolean;
  private model: TreeModel | null = null;
  private edges: Edge[] = [];
  private pulses: Pulse[] = [];
  private stars: Star[] = [];
  private bg: HTMLCanvasElement | null = null;
  private aur: HTMLCanvasElement | null = null; private aurAt = -1;
  private sprites = new Map<string, HTMLCanvasElement>();
  private cam = { x: 0, y: 0, k: 1 };
  private tween: { from: { x: number; y: number; k: number }; to: { x: number; y: number; k: number }; t0: number; dur: number } | null = null;
  private region = { x: 0, y: 0, w: 1, h: 1 };
  private userMoved = false;
  private hot = new Set<string>();       // edges on the selected path
  private live = new Set<string>();      // edges on running builds' paths
  private hoverPath = new Set<string>();
  private energy = 0; private energyS = 0; private emitAcc = 0;
  private bloomT = -1;
  private drag: { sx: number; sy: number; cx: number; cy: number; moved: boolean } | null = null;
  private ro: ResizeObserver; private io: IntersectionObserver | null = null;

  constructor(canvas: HTMLCanvasElement, layer: HTMLElement) {
    this.canvas = canvas; this.layer = layer;
    this.ctx = canvas.getContext("2d", { alpha: false })!;
    this.reduced = typeof matchMedia !== "undefined" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    const r = rnd(7);
    this.stars = Array.from({ length: 420 }, () => ({ x: r() * 4000, y: r() * 3000, z: r() < 0.7 ? 0.04 : r() < 0.85 ? 0.12 : 0.26, s: r() < 0.05 ? 1.8 : r() < 0.3 ? 1.2 : 0.8, tw: r() * TAU, c: Math.floor(r() * 4) }));
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(canvas);
    if (typeof IntersectionObserver !== "undefined") {
      this.io = new IntersectionObserver((es) => { this.visible = es.some((e) => e.isIntersecting); if (this.visible) this.start(); else this.stop(); });
      this.io.observe(canvas);
    }
    canvas.addEventListener("pointerdown", this.onDown);
    window.addEventListener("pointermove", this.onMove);
    window.addEventListener("pointerup", this.onUp);
    canvas.addEventListener("wheel", this.onWheel, { passive: false });
    canvas.addEventListener("dblclick", this.onDbl);
    document.addEventListener("visibilitychange", this.onVis);
    this.resize();
    this.start();
  }

  // ------------------------------------------------------------------ API --
  setModel(model: TreeModel) {
    const fresh = !this.model;
    this.model = model;
    this.buildEdges();
    if (fresh || !this.userMoved) this.fit(fresh || this.reduced);
    this.dirty = true;
  }
  /** Selected path (core..mod) and the paths of running builds. */
  setPaths(selected: string[], running: string[][], hover: string[] = []) {
    const key = (p: string[]) => { const s = new Set<string>(); for (let i = 1; i < p.length; i++) s.add(`${p[i - 1]}>${p[i]}`); return s; };
    this.hot = key(selected);
    this.live = new Set(running.flatMap((p) => [...key(p)]));
    this.hoverPath = key(hover);
    this.dirty = true;
  }
  setRegion(r: { x: number; y: number; w: number; h: number }) {
    const o = this.region;
    if (Math.abs(o.x - r.x) + Math.abs(o.y - r.y) + Math.abs(o.w - r.w) + Math.abs(o.h - r.h) < 2) return;
    this.region = { ...r, w: Math.max(120, r.w), h: Math.max(120, r.h) };
    if (!this.userMoved) this.fit(!this.model);
  }
  setEnergy(e: number) { this.energy = Math.max(0, Math.min(1, e)); }
  /** Light down a branch (core -> ... -> id), e.g. streamed code for the running mod. */
  emit(path: string[], count = 1) {
    if (this.reduced) return;
    for (let i = 1; i < path.length; i++) {
      const e = this.edges.find((x) => x.a.id === path[i - 1] && x.b.id === path[i]);
      if (e) for (let j = 0; j < count; j++) this.spawn(e, -i * 0.18 - j * 0.08, true);
    }
  }
  bloom() { this.bloomT = this.reduced ? -1 : 0; this.dirty = true; }
  zoomBy(f: number) { this.userMoved = true; const k = Math.max(0.35, Math.min(2.6, this.cam.k * f)); this.animate({ ...this.cam, k }, 220); }
  recenter() { this.userMoved = false; this.fit(false); }
  focusNode(id: string) {
    const n = this.model?.byId.get(id); if (!n) return;
    this.userMoved = true;
    const k = Math.max(this.cam.k, 1.15);
    const cx = PILL.has(n.kind) ? n.x + n.w / 2 : n.x;
    const rc = this.regionCenter();
    this.animate({ k, x: cx - (rc.x - this.W / 2) / k, y: n.y - (rc.y - this.H / 2) / k }, 700);
  }
  dispose() {
    this.disposed = true; this.stop(); this.ro.disconnect(); this.io?.disconnect();
    this.canvas.removeEventListener("pointerdown", this.onDown); window.removeEventListener("pointermove", this.onMove); window.removeEventListener("pointerup", this.onUp);
    this.canvas.removeEventListener("wheel", this.onWheel); this.canvas.removeEventListener("dblclick", this.onDbl);
    document.removeEventListener("visibilitychange", this.onVis);
  }

  // ------------------------------------------------------------ internals --
  private regionCenter() { return { x: this.region.x + this.region.w / 2, y: this.region.y + this.region.h / 2 }; }
  private fit(instant: boolean) {
    const m = this.model; if (!m) return;
    const b = m.bounds;
    const bw = b.x1 - b.x0 + 40, bh = b.y1 - b.y0 + 40;
    const k = Math.max(0.42, Math.min(1.25, Math.min(this.region.w / bw, this.region.h / bh)));
    const rc = this.regionCenter();
    const mx = (b.x0 + b.x1) / 2, my = (b.y0 + b.y1) / 2;
    this.animate({ k, x: mx - (rc.x - this.W / 2) / k, y: my - (rc.y - this.H / 2) / k }, instant ? 0 : 600);
  }
  private animate(to: { x: number; y: number; k: number }, dur: number) {
    if (dur <= 0 || this.reduced) { this.cam = { ...to }; this.tween = null; this.dirty = true; this.applyLayer(); return; }
    this.tween = { from: { ...this.cam }, to, t0: performance.now(), dur };
  }
  private applyLayer() {
    const { k } = this.cam;
    this.layer.style.transform = `translate3d(${(this.W / 2 - this.cam.x * k).toFixed(2)}px, ${(this.H / 2 - this.cam.y * k).toFixed(2)}px, 0) scale(${k.toFixed(4)})`;
    this.layer.style.setProperty("--k", k.toFixed(3));
  }

  private buildEdges() {
    const m = this.model!;
    const old = new Map(this.edges.map((e) => [e.key, e]));
    this.edges = [];
    for (const n of m.nodes) {
      if (!n.parent) continue;
      const a = m.byId.get(n.parent); if (!a) continue;
      const key = `${a.id}>${n.id}`;
      // anchors: from the parent's centre (circles), to the child's edge (pills) or centre
      const p1: P = PILL.has(n.kind) ? { x: n.anchor === "r" ? n.x + n.w : n.x, y: n.y } : { x: n.x, y: n.y };
      const p0: P = { x: a.x, y: a.y };
      const dx = p1.x - p0.x, dy = p1.y - p0.y, len = Math.hypot(dx, dy) || 1;
      // leave radially (away from the core), arrive along the child's own direction
      const rad = Math.hypot(a.x, a.y) > 1 ? { x: a.x / Math.hypot(a.x, a.y), y: a.y / Math.hypot(a.x, a.y) } : { x: dx / len, y: dy / len };
      const into = PILL.has(n.kind) ? (n.anchor === "r" ? { x: -1, y: 0 } : { x: 1, y: 0 }) : { x: dx / len, y: dy / len };
      const bend = a.kind === "core" ? 0.28 : 0.42;
      const c1 = { x: p0.x + rad.x * len * bend, y: p0.y + rad.y * len * bend };
      const c2 = { x: p1.x - into.x * len * 0.45, y: p1.y - into.y * len * 0.45 };
      const r = rnd(hash(key));
      const prev = old.get(key);
      this.edges.push({ a, b: n, p0, c1, c2, p1, ca: a.kind === "core" ? CORE_HUE : hexRgb(a.hue), cb: hexRgb(n.hue), soon: !!(n.soon || a.soon), beads: prev?.beads ?? Array.from({ length: len > 120 ? 3 : 2 }, () => 0.15 + r() * 0.7), key, len });
    }
    const keep = new Set(this.edges);
    this.pulses = this.pulses.filter((p) => keep.has(p.e));
  }
  private pt(e: Edge, t: number): P {
    const u = 1 - t;
    return {
      x: u * u * u * e.p0.x + 3 * u * u * t * e.c1.x + 3 * u * t * t * e.c2.x + t * t * t * e.p1.x,
      y: u * u * u * e.p0.y + 3 * u * u * t * e.c1.y + 3 * u * t * t * e.c2.y + t * t * t * e.p1.y,
    };
  }
  private spawn(e: Edge, t0 = 0, hot = false) {
    if (this.pulses.length > 320) this.pulses.shift();
    this.pulses.push({ e, t: t0, speed: (150 + Math.random() * 70) / Math.max(80, e.len), size: hot ? 1.15 : 0.8, hot });
  }

  private sprite(c: Rgb, kind: "dot" | "halo" = "dot") {
    const id = kind + c.join(",");
    let s = this.sprites.get(id);
    if (!s) {
      s = document.createElement("canvas");
      const S = kind === "halo" ? 128 : 48; s.width = s.height = S;
      const g = s.getContext("2d")!;
      const gr = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
      if (kind === "halo") { gr.addColorStop(0, rgba(c, 0.55)); gr.addColorStop(0.35, rgba(c, 0.16)); gr.addColorStop(1, rgba(c, 0)); }
      else { gr.addColorStop(0, "rgba(255,255,255,1)"); gr.addColorStop(0.16, rgba(mix(c, [255, 255, 255], 0.45), 0.95)); gr.addColorStop(0.42, rgba(c, 0.3)); gr.addColorStop(1, rgba(c, 0)); }
      g.fillStyle = gr; g.fillRect(0, 0, S, S);
      this.sprites.set(id, s);
    }
    return s;
  }

  private resize() {
    const r = this.canvas.getBoundingClientRect();
    this.W = Math.max(1, r.width); this.H = Math.max(1, r.height);
    let dpr = Math.min(2, window.devicePixelRatio || 1);
    if (this.W * this.H * dpr * dpr > 5e6) dpr = Math.max(1, Math.sqrt(5e6 / (this.W * this.H)));
    this.dpr = dpr;
    this.canvas.width = Math.round(this.W * dpr); this.canvas.height = Math.round(this.H * dpr);
    this.bg = null; this.aur = null;
    if (!this.userMoved) this.fit(true);
    this.applyLayer();
    this.dirty = true;
    if (this.reduced || !this.running) this.frame(performance.now());
  }
  private onVis = () => { if (document.hidden) this.stop(); else if (this.visible) this.start(); };
  private start() { if (this.running || this.disposed) return; this.running = true; this.last = performance.now(); this.raf = requestAnimationFrame(this.loop); }
  private stop() { this.running = false; cancelAnimationFrame(this.raf); }
  private loop = (now: number) => { if (!this.running) return; this.frame(now); this.raf = requestAnimationFrame(this.loop); };

  private onDown = (e: PointerEvent) => { this.drag = { sx: e.clientX, sy: e.clientY, cx: this.cam.x, cy: this.cam.y, moved: false }; this.tween = null; this.canvas.style.cursor = "grabbing"; };
  private onMove = (e: PointerEvent) => {
    const d = this.drag; if (!d) return;
    const dx = e.clientX - d.sx, dy = e.clientY - d.sy;
    if (!d.moved && Math.hypot(dx, dy) > 3) d.moved = true;
    if (!d.moved) return;
    this.userMoved = true;
    this.cam.x = d.cx - dx / this.cam.k; this.cam.y = d.cy - dy / this.cam.k;
    this.applyLayer(); this.dirty = true;
  };
  private onUp = () => { this.drag = null; this.canvas.style.cursor = ""; };
  private onWheel = (e: WheelEvent) => {
    e.preventDefault();
    const r = this.canvas.getBoundingClientRect();
    const sx = e.clientX - r.left, sy = e.clientY - r.top;
    const k0 = this.cam.k, k1 = Math.max(0.35, Math.min(2.6, k0 * Math.exp(-(e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY) * 0.0015)));
    const wx = (sx - this.W / 2) / k0 + this.cam.x, wy = (sy - this.H / 2) / k0 + this.cam.y;
    this.cam = { k: k1, x: wx - (sx - this.W / 2) / k1, y: wy - (sy - this.H / 2) / k1 };
    this.userMoved = true; this.tween = null; this.applyLayer(); this.dirty = true;
  };
  private onDbl = () => this.recenter();

  // ---------------------------------------------------------------- frame --
  private frame(now: number) {
    const dt = Math.min(0.05, (now - this.last) / 1000); this.last = now;
    const anim = !this.reduced;
    if (anim) this.time += dt;
    if (this.tween) {
      const u = Math.min(1, (now - this.tween.t0) / this.tween.dur), e = EASE(u);
      const { from, to } = this.tween;
      this.cam = { x: from.x + (to.x - from.x) * e, y: from.y + (to.y - from.y) * e, k: from.k * Math.pow(to.k / from.k, e) };
      this.applyLayer();
      if (u >= 1) this.tween = null;
      this.dirty = true;
    }
    this.energyS += (this.energy - this.energyS) * (1 - Math.exp(-dt * 5));
    if (anim) {
      // ambient trickle; the selected branch carries light; running builds stream light
      for (const e of this.edges) {
        const k = `${e.a.id}>${e.b.id}`;
        const rate = this.live.has(k) ? 1.4 : this.hot.has(k) ? 0.55 : this.hoverPath.has(k) ? 0.8 : e.soon ? 0.03 : 0.07;
        if (Math.random() < rate * dt) this.spawn(e, 0, this.live.has(k) || this.hot.has(k));
      }
      if (this.energyS > 0.03) {
        this.emitAcc += this.energyS * dt * 6;
        const first = this.edges.filter((e) => e.a.kind === "core");
        while (this.emitAcc >= 1 && first.length) { this.emitAcc -= 1; this.spawn(first[Math.floor(Math.random() * first.length)], 0, true); }
      }
      const keep: Pulse[] = [];
      for (const p of this.pulses) { p.t += p.speed * dt; if (p.t < 1.05) keep.push(p); }
      this.pulses = keep;
      if (this.bloomT >= 0) { this.bloomT += dt; if (this.bloomT > 1.6) this.bloomT = -1; }
      this.dirty = true;
    }
    if (!this.dirty) return;
    this.dirty = false;
    this.draw();
  }

  private paintBg() {
    // deep navy space: a radial ground, two diagonal nebula veils, dust; rendered once per size
    const c = document.createElement("canvas");
    c.width = Math.ceil(this.W / 2); c.height = Math.ceil(this.H / 2);
    const g = c.getContext("2d")!;
    const w = c.width, h = c.height;
    const base = g.createLinearGradient(0, 0, w, h);
    base.addColorStop(0, "#070a24"); base.addColorStop(0.5, "#05061a"); base.addColorStop(1, "#080622");
    g.fillStyle = base; g.fillRect(0, 0, w, h);
    g.globalCompositeOperation = "lighter";
    const blob = (x: number, y: number, r: number, c: Rgb, a: number) => { const gr = g.createRadialGradient(x, y, 0, x, y, r); gr.addColorStop(0, rgba(c, a)); gr.addColorStop(0.5, rgba(c, a * 0.35)); gr.addColorStop(1, rgba(c, 0)); g.fillStyle = gr; g.fillRect(0, 0, w, h); };
    blob(w * 0.08, h * 0.12, w * 0.45, [86, 40, 200], 0.28);
    blob(w * 0.95, h * 0.05, w * 0.4, [120, 50, 230], 0.22);
    blob(w * 0.9, h * 0.95, w * 0.45, [60, 40, 190], 0.22);
    blob(w * 0.05, h * 0.92, w * 0.35, [150, 40, 200], 0.16);
    blob(w * 0.48, h * 0.55, w * 0.32, [60, 50, 200], 0.14);
    // dust
    const r = rnd(99);
    for (let i = 0; i < 900; i++) { g.fillStyle = `rgba(190,200,255,${(0.04 + r() * 0.12).toFixed(3)})`; g.fillRect(r() * w, r() * h, 1, 1); }
    g.globalCompositeOperation = "source-over";
    this.bg = c;
  }
  private paintAurora() {
    // aurora streams: soft diagonal ribbons of violet/blue light drifting very slowly (quarter res)
    const c = this.aur ?? document.createElement("canvas");
    c.width = Math.ceil(this.W / 4); c.height = Math.ceil(this.H / 4);
    const g = c.getContext("2d")!;
    const w = c.width, h = c.height, t = this.time;
    g.clearRect(0, 0, w, h);
    g.globalCompositeOperation = "lighter";
    const ribbons: [number, number, number, number, Rgb, number][] = [
      [-0.1, 0.18, 0.5, -0.12, [140, 70, 255], 0.2], [0.55, -0.05, 1.1, 0.35, [110, 60, 255], 0.16], [0.7, 0.75, 1.15, 0.55, [90, 70, 255], 0.14], [-0.05, 0.8, 0.35, 1.05, [190, 60, 230], 0.12],
    ];
    ribbons.forEach(([x0, y0, x1, y1, col, a], i) => {
      const s = Math.sin(t * 0.06 + i * 1.9) * 0.05;
      g.lineCap = "round";
      for (let j = 0; j < 3; j++) {
        g.beginPath();
        g.moveTo((x0 + s) * w, (y0 + j * 0.03) * h);
        g.bezierCurveTo((x0 + 0.25 + s) * w, (y0 + 0.2 + j * 0.02) * h, (x1 - 0.25) * w, (y1 - 0.15 - s) * h, (x1 + s) * w, (y1 + j * 0.03) * h);
        g.strokeStyle = rgba(col, a * (j === 1 ? 1 : 0.5)); g.lineWidth = (j === 1 ? 10 : 22) * (w / 480); g.stroke();
      }
    });
    g.globalCompositeOperation = "source-over";
    this.aur = c; this.aurAt = this.time;
  }

  private draw() {
    const { ctx, W, H, dpr, cam } = this;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = "source-over";
    if (!this.bg) this.paintBg();
    ctx.drawImage(this.bg!, 0, 0, W, H);
    if (!this.aur || (!this.reduced && this.time - this.aurAt > 0.25)) this.paintAurora();
    ctx.globalCompositeOperation = "lighter";
    ctx.filter = "blur(6px)";
    ctx.drawImage(this.aur!, 0, 0, W, H);
    ctx.filter = "none";
    // stars (parallax with the camera)
    const cols = ["210,220,255", "180,160,255", "160,220,255", "240,180,255"];
    for (const s of this.stars) {
      const px = (((s.x - cam.x * s.z * cam.k) % W) + W) % W, py = (((s.y - cam.y * s.z * cam.k) % H) + H) % H;
      const tw = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(this.time * (0.6 + s.z * 3) + s.tw));
      ctx.fillStyle = `rgba(${cols[s.c]},${(tw * (s.z > 0.2 ? 0.85 : 0.5)).toFixed(3)})`;
      ctx.fillRect(px, py, s.s, s.s);
    }
    if (!this.model) return;
    const k = cam.k;
    ctx.setTransform(dpr * k, 0, 0, dpr * k, dpr * (W / 2 - cam.x * k), dpr * (H / 2 - cam.y * k));
    const hair = 1 / k;

    // radar rings + soft light around the core
    const core = this.model.byId.get("core")!;
    ctx.globalCompositeOperation = "lighter";
    const pool = 260 * (1 + this.energyS * 0.15);
    ctx.globalAlpha = 0.5 + this.energyS * 0.3;
    ctx.drawImage(this.sprite([90, 70, 255], "halo"), core.x - pool, core.y - pool, pool * 2, pool * 2);
    ctx.globalAlpha = 1;
    for (const [r, a] of [[92, 0.16], [128, 0.1], [170, 0.07], [230, 0.05]] as const) {
      ctx.beginPath(); ctx.arc(core.x, core.y, r, 0, TAU); ctx.lineWidth = hair; ctx.strokeStyle = rgba([130, 120, 255], a); ctx.stroke();
    }
    ctx.save(); ctx.setLineDash([2 * hair, 6 * hair]); ctx.lineDashOffset = -this.time * 6;
    ctx.beginPath(); ctx.arc(core.x, core.y, 108, 0, TAU); ctx.lineWidth = hair; ctx.strokeStyle = rgba([150, 130, 255], 0.22); ctx.stroke(); ctx.restore();

    // threads: glow + body + bright core line, hue running parent -> child
    ctx.lineCap = "round";
    for (const e of this.edges) {
      const key = `${e.a.id}>${e.b.id}`;
      const hot = this.hot.has(key) || this.live.has(key), hov = this.hoverPath.has(key);
      const dim = e.soon ? 0.42 : 1;
      const boost = hot ? 1.35 : hov ? 1.2 : 1;
      const g = ctx.createLinearGradient(e.p0.x, e.p0.y, e.p1.x, e.p1.y);
      g.addColorStop(0, rgba(e.ca, 1)); g.addColorStop(1, rgba(e.cb, 1));
      ctx.beginPath(); ctx.moveTo(e.p0.x, e.p0.y); ctx.bezierCurveTo(e.c1.x, e.c1.y, e.c2.x, e.c2.y, e.p1.x, e.p1.y);
      ctx.strokeStyle = g;
      ctx.globalAlpha = 0.07 * dim * boost; ctx.lineWidth = 9; ctx.stroke();
      ctx.globalAlpha = 0.22 * dim * boost; ctx.lineWidth = 3.2; ctx.stroke();
      ctx.globalAlpha = Math.min(1, 0.8 * dim * boost); ctx.lineWidth = hot ? 1.5 : 1.1; ctx.stroke();
    }
    ctx.globalAlpha = 1;
    // beads sitting on the threads (twinkle)
    for (const e of this.edges) {
      const dim = e.soon ? 0.45 : 1;
      e.beads.forEach((t, i) => {
        const p = this.pt(e, t);
        const tw = 0.55 + 0.45 * Math.sin(this.time * 1.7 + i * 2.1 + t * 9);
        const s = (i === 0 ? 7 : 5) * (0.8 + 0.2 * tw);
        ctx.globalAlpha = 0.8 * tw * dim;
        ctx.drawImage(this.sprite(mix(e.ca, e.cb, t)), p.x - s / 2, p.y - s / 2, s, s);
      });
    }
    // travelling light
    for (const p of this.pulses) {
      for (let j = 0; j < 4; j++) {
        const t = p.t - j * 0.02;
        if (t < 0 || t > 1) continue;
        const q = this.pt(p.e, t);
        const s = (j === 0 ? 11 : 8 - j * 1.6) * p.size;
        ctx.globalAlpha = (j === 0 ? 1 : 0.5 - j * 0.1) * (p.e.soon ? 0.5 : 1);
        ctx.drawImage(this.sprite(mix(p.e.ca, p.e.cb, t)), q.x - s / 2, q.y - s / 2, s, s);
      }
    }
    ctx.globalAlpha = 1;
    // halos under circles (the DOM draws the rings themselves)
    for (const n of this.model.nodes) {
      if (n.kind !== "game" && n.kind !== "cat" && n.kind !== "add" && n.kind !== "core") continue;
      const c = n.kind === "core" ? CORE_HUE : hexRgb(n.hue);
      const s = (n.kind === "core" ? 5.2 : n.kind === "game" ? 3.6 : 3) * n.w * (n.kind === "core" ? 1 + 0.06 * Math.sin(this.time * 1.4) + this.energyS * 0.25 : 1);
      ctx.globalAlpha = (n.soon ? 0.3 : 0.7) * (n.kind === "cat" ? 0.7 : 1);
      ctx.drawImage(this.sprite(c, "halo"), n.x - s / 2, n.y - s / 2, s, s);
    }
    if (this.bloomT >= 0) {
      const u = this.bloomT / 1.6, s = 140 + u * 700;
      ctx.globalAlpha = 0.6 * (1 - u);
      ctx.drawImage(this.sprite([160, 110, 255], "halo"), core.x - s / 2, core.y - s / 2, s, s);
    }
    // a soft edge glow under pills so they sit on light, not on void
    for (const n of this.model.nodes) {
      if (!PILL.has(n.kind)) continue;
      ctx.globalAlpha = n.status === "running" ? 0.5 : 0.18;
      const s = n.w * 1.1;
      ctx.drawImage(this.sprite(hexRgb(n.hue), "halo"), n.x + n.w / 2 - s / 2, n.y - PILL_H, s, PILL_H * 2);
    }
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = "source-over";
  }
}

