"use client";

// The stage: CyrusTree draws the space and the neon threads on a canvas; the nodes are real
// buttons in a DOM layer the engine moves with its camera.
import { useEffect, useRef, type MutableRefObject } from "react";
import { CyrusTree } from "./web/tree";
import { PILL_H, type TreeModel, type TreeNode } from "./web/tree-layout";
import { CyIcon, CyrusMark, GameEmblem, ModCube } from "./icons";

export const CAT_TONE: Record<string, string> = { worldgen: "green", biomes: "pink", structures: "blue", gameplay: "magenta", visuals: "violet", utility: "cyan", other: "violet" };
export const GAME_TONE: Record<string, string> = { minecraft: "green", ark: "violet", theisle: "blue", palworld: "pink", rust: "red", valheim: "amber" };

export function Stage({ engineRef, model, selected, running, hover, onNode, onHover, region, building }: {
  engineRef: MutableRefObject<CyrusTree | null>;
  model: TreeModel;
  selected: string[];
  running: string[][];
  hover: string[];
  onNode: (n: TreeNode) => void;
  onHover: (n: TreeNode | null) => void;
  region: { x: number; y: number; w: number; h: number };
  building: number;
}) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const layer = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const e = new CyrusTree(canvas.current!, layer.current!);
    engineRef.current = e;
    try { if (localStorage.getItem("cyDebug") === "1") (window as unknown as { __cyTree: CyrusTree }).__cyTree = e; } catch { /* */ }
    return () => { e.dispose(); engineRef.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { engineRef.current?.setRegion(region); }, [region, engineRef]);
  useEffect(() => { engineRef.current?.setModel(model); }, [model, engineRef]);
  useEffect(() => { engineRef.current?.setPaths(selected, running, hover); }, [selected, running, hover, engineRef]);

  const sel = new Set(selected);
  return (
    <div className="cy-stage">
      <canvas ref={canvas} className="cy-canvas" aria-hidden="true" />
      <div ref={layer} className="cy-layer-world" role="group" aria-label="Your mods: Cyrus, games, categories and mods">
        {model.nodes.map((n) => <NodeView key={n.id} n={n} on={sel.has(n.id)} building={building} onNode={onNode} onHover={onHover} />)}
      </div>
    </div>
  );
}

function NodeView({ n, on, building, onNode, onHover }: { n: TreeNode; on: boolean; building: number; onNode: (n: TreeNode) => void; onHover: (n: TreeNode | null) => void }) {
  const style = { left: n.x, top: n.y, ["--hue" as string]: n.hue } as React.CSSProperties;
  const ev = { onMouseEnter: () => onHover(n), onMouseLeave: () => onHover(null), onFocus: () => onHover(n), onBlur: () => onHover(null), onClick: () => onNode(n) };
  switch (n.kind) {
    case "core":
      return (
        <div className={`cy-n cy-n-core ${building ? "busy" : ""}`} style={style}>
          <span className="cy-core-ring" aria-hidden="true" />
          <CyrusMark size={44} />
          <span className="cy-core-t">Cyrus</span>
          {building > 0 && <span className="cy-core-s">{building} building</span>}
        </div>
      );
    case "game":
      return (
        <button type="button" className={`cy-n cy-n-game ${n.soon ? "soon" : ""} ${on ? "on" : ""}`} style={{ ...style, ["--d" as string]: `${n.w * 2}px` }} {...ev}
                aria-label={`${n.label}${n.soon ? ", coming soon" : ""}`} aria-pressed={on}>
          <span className="cy-n-disc"><GameEmblem game={n.game!} size={Math.round(n.w * 1.25)} /></span>
          <span className="cy-n-name">{n.label}{n.soon && <em>Soon</em>}</span>
        </button>
      );
    case "add":
      return (
        <button type="button" className="cy-n cy-n-game add" style={{ ...style, ["--d" as string]: `${n.w * 2}px` }} {...ev} aria-label="Add a game">
          <span className="cy-n-disc"><CyIcon name="gamepad" size={26} tone="violet" /></span>
          <span className="cy-n-name"><CyIcon name="plus" size={12} /> Add Game</span>
        </button>
      );
    case "cat":
      return (
        <button type="button" className={`cy-n cy-n-cat ${on ? "on" : ""}`} style={style} {...ev} aria-pressed={on}>
          <span className="cy-n-ic"><CyIcon name={n.icon || "cube"} size={17} tone={CAT_TONE[n.cat!] ?? "violet"} /></span>
          <span className="cy-n-lbl">{n.label}</span>
        </button>
      );
    case "leaf":
      return (
        <span className={`cy-n cy-n-leaf`} style={style} title={`${n.label} · coming soon`}>
          <CyIcon name={n.icon || "cube"} size={14} tone={GAME_TONE[n.game!] ?? "violet"} />
        </span>
      );
    case "dots":
      return <span className="cy-n cy-n-dots" style={style} aria-hidden="true">···</span>;
    default: {
      const run = n.status === "running";
      return (
        <button type="button" className={`cy-n cy-n-pill k-${n.kind} ${on ? "on" : ""} st-${n.status ?? "idle"}`} style={{ ...style, width: n.w, height: PILL_H }} {...ev}
                aria-pressed={n.kind === "mod" ? on : undefined} title={n.kind === "tpl" ? `Template: ${n.label}` : n.label}>
          {n.kind === "mod" && (
            <span className={`cy-n-cube ${run ? "run" : ""}`} style={run && n.progress ? { ["--p" as string]: n.progress } : undefined}>
              <ModCube hue={n.hue} size={15} />
            </span>
          )}
          {n.kind === "tpl" && <span className="cy-n-cube tpl"><ModCube hue={n.hue} size={15} /></span>}
          {n.kind === "start" && <CyIcon name="plus" size={12} />}
          <span className="cy-n-t">{n.label}</span>
          {n.kind === "tpl" && <em className="cy-n-tag">Template</em>}
          {n.status === "bad" && <i className="cy-n-bad" aria-label="Last build failed" />}
        </button>
      );
    }
  }
}

