  { label: "Servers", href: "/dashboard/services", icon: "servers" },
  { label: "Hosting", href: "/dashboard/hosting", icon: "hosting" },
  { label: "Domains", href: "/dashboard/domains", icon: "globe" },
  { label: "Cyrus", href: "/dashboard/cyrus", icon: "cube", badge: "Beta", here: true },
  { label: "Billing", href: "/dashboard/billing", icon: "billing" },
  { label: "Account", href: "/dashboard/settings", icon: "account" },
];

export function Sidebar({ game, counts, onGame, onNew, onCustom, onUpgrade, open, onClose }: {
  game: string;
  counts: Record<string, number>;
  onGame: (id: string) => void;
  onNew: () => void;
  onCustom: () => void;
  onUpgrade: () => void;
  open: boolean;
  onClose: () => void;
}) {
  return (
    <>
      {open && <button type="button" className="cy-side-back" aria-label="Close menu" onClick={onClose} />}
      <aside className={`cy-side ${open ? "open" : ""}`} aria-label="Nxeon">
        <Link href="/dashboard" className="cy-side-logo" aria-label="Nxeon dashboard"><Wordmark size={40} /></Link>
        <nav className="cy-side-nav">
          {NAV.map((n) => (
            <Link key={n.href} href={n.href} className={`cy-side-i ${n.here ? "on" : ""}`} aria-current={n.here ? "page" : undefined}>
              <CyIcon name={n.icon} size={19} tone={n.here ? "violet" : undefined} />
              <span>{n.label}</span>
              {n.badge && <em className="cy-beta">{n.badge}</em>}
            </Link>
          ))}
        </nav>
        <div className="cy-side-h">
          <span>Projects</span>
          <button type="button" className="cy-side-add" onClick={onNew} aria-label="New mod (N)" title="New mod  N"><CyIcon name="plus" size={15} /></button>
        </div>
        <nav className="cy-side-proj" aria-label="Projects by game">
          {CYRUS_GAMES.map((g) => {
            const live = g.status === "live";
            return (
              <button key={g.id} type="button" className={`cy-side-p ${game === g.id ? "on" : ""} ${live ? "" : "soon"}`} onClick={() => onGame(g.id)}
                      title={live ? `${g.name} mods` : `${g.name} mods are coming soon`}>
                <GameEmblem game={g.id} size={20} />
                <span>{g.name} Mods</span>
                {live ? (counts[g.id] ? <em className="cy-side-n">{counts[g.id]}</em> : null) : <em className="cy-side-soon">Soon</em>}
              </button>
            );
          })}
          <button type="button" className="cy-side-p" onClick={onCustom} title="Describe any mod from scratch">
            <span className="cy-side-pi"><CyIcon name="layers" size={17} tone="violet" /></span>
            <span>Custom Project</span>
          </button>
        </nav>
        <div className="cy-pro">
          <div className="cy-pro-h"><CyIcon name="crown" size={20} tone="pink" /> Cyrus Pro</div>
          <p>Higher limits, faster models, advanced mod tools.</p>
          <button type="button" className="cy-pro-go" onClick={onUpgrade}>Upgrade <CyIcon name="crown" size={15} /></button>
        </div>
      </aside>
    </>
  );
}

export function TopBar({ name, email, onSearch, onHelp, onMenu }: { name: string; email: string; onSearch: () => void; onHelp: () => void; onMenu: () => void }) {
  return (
    <header className="cy-top">
      <button type="button" className="cy-top-menu" onClick={onMenu} aria-label="Open menu"><CyIcon name="grid2" size={18} /></button>
      <button type="button" className="cy-top-search" onClick={onSearch} aria-label="Search games, mods, files, or ask Cyrus">
        <CyIcon name="search" size={17} />
        <span>Search games, mods, files, or ask Cyrus…</span>
        <kbd>Ctrl K</kbd>
      </button>
      <div className="cy-top-r">
        <span className="cy-top-theme"><ThemeToggle /></span>
        <button type="button" className="cy-top-ib" onClick={onHelp} aria-label="Keyboard shortcuts and help" title="Shortcuts  ?"><CyIcon name="help" size={19} /></button>
        <Link href="/dashboard/activity" className="cy-top-ib" aria-label="Activity and notifications" title="Activity"><CyIcon name="bell" size={19} /></Link>
        <Link href="/dashboard/settings" className="cy-top-me" title={email}>
          <span className="cy-top-av">{(name[0] || "N").toUpperCase()}</span>
          <span className="cy-top-name">{name}</span>
          <CyIcon name="chev" size={15} />
        </Link>
      </div>
    </header>
  );
}

