/** The files of a build: the final source when done; the live workspace (+ the base version) while building. */
export function useCodeRows(build: ModBuildView, base: ModBuildView | null | undefined, live: LiveState): Row[] {
  const running = !isTerminal(build.status);
  const finalFiles = visibleSrc(build.result?.files ?? []).filter((f) => !f.path.endsWith(".kts"));
  return useMemo(() => {
    if (!running && finalFiles.length) return finalFiles.map((f) => ({ path: f.path, name: f.path.split("/").pop()!, state: "ready" as const, src: "final" as const }));
    const out = new Map<string, Row>();
    for (const f of visibleSrc(base?.result?.files ?? []).filter((x) => x.path.startsWith("src/main/"))) out.set(f.path, { path: f.path, name: f.path.split("/").pop()!, state: "base", src: "base" });
    for (const f of live.files.values()) out.set(f.path, { path: f.path, name: f.path.split("/").pop()!, state: f.state, src: "live" });
    if (live.supported === false) {
      for (const t of touchedFiles(build).filter((x) => x.verb !== "Reading")) {
        if (![...out.values()].some((r) => r.name === t.name)) out.set(t.name, { path: t.name, name: t.name, state: "named", src: "none" });
      }
    }
    return [...out.values()];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [running, finalFiles.length, build.id, build.status, base?.id, live, build]);
}

/** Folder of a source path, relative to the plugin's package root ("commands", "resources"). */
export function folderOf(path: string): string {
  if (path.startsWith("src/main/resources/")) return "resources";
  const m = path.match(/^src\\/main\\/java\\/(.+)\\/[^/]+$/);
  if (!m) return "project";
  const parts = m[1].split("/");
  // package root = the deepest directory that holds the main class; approximate: first 3 segments
  return parts.length > 3 ? parts.slice(3).join("/") : "main";
}

/** Code tab: path + file switcher + live / final source (owner concept). */
export function LiveCode({ build, base, live, focusPath, onPick, wide, onWide }: {
  build: ModBuildView;
  base?: ModBuildView | null;
  live: LiveState;
  /** a file picked on the web or in the Files tab */
  focusPath?: string | null;
  onPick?: (path: string) => void;
  wide?: boolean;
  onWide?: () => void;
}) {
  const running = !isTerminal(build.status);
  const rows = useCodeRows(build, base, live);
  const [sel, setSel] = useState<string | null>(null);
  const [follow, setFollow] = useState(true);
  useEffect(() => { if (focusPath) { setSel(focusPath); setFollow(false); } }, [focusPath]);
  useEffect(() => { setFollow(true); setSel(null); }, [build.id]);
  const writing = live.draft && !live.draft.done ? live.draft.path : null;
  const newest = running ? writing ?? [...live.files.values()].sort((a, b) => b.changedAt - a.changedAt)[0]?.path ?? null : null;
  const pickDefault = () => {
    const java = rows.filter((r) => r.name.endsWith(".java"));
    const pn = build.pluginName;
    return (pn && java.find((r) => r.name === `${pn}.java` || r.name === `${pn}Plugin.java`)) || java.find((r) => /Plugin\\.java$|Main\\.java$/.test(r.name)) || java[0] || rows[0] || null;
  };
  const current = (running && follow && newest ? rows.find((r) => r.path === newest) : null) ?? rows.find((r) => r.path === sel) ?? pickDefault();
  const dir = current ? current.path.replace(/[^/]+$/, "") : "";

  return (
    <div className="cy-code">
      <div className="cy-code-h">
        <span className="cy-code-dir" title={dir}>{dir || (running ? "Waiting for the first file" : "")}</span>
        {rows.length > 0 && (
          <label className="cy-code-sel">
            <select value={current?.path ?? ""} onChange={(e) => { setSel(e.target.value); setFollow(false); onPick?.(e.target.value); }} aria-label="File">
              {rows.map((r) => <option key={r.path} value={r.path}>{r.name}{r.state === "writing" ? " · writing" : r.state === "editing" ? " · editing" : ""}</option>)}
            </select>
            <CyIcon name="chev" size={14} />
          </label>
        )}
        {running && !follow && rows.length > 0 && <button type="button" className="cy-code-ib" onClick={() => setFollow(true)} title="Follow Cyrus" aria-label="Follow Cyrus"><CyIcon name="eye" size={15} /></button>}
        {onWide && <button type="button" className="cy-code-ib" onClick={onWide} title={wide ? "Smaller" : "Wider code"} aria-label={wide ? "Smaller code view" : "Wider code view"}><CyIcon name="expand" size={15} /></button>}
      </div>
      <div className="cy-view">
        {current ? <Viewer key={`${build.id}:${current.path}`} build={build} base={base ?? null} row={current} live={live} running={running} /> : (
          <div className="cy-view-empty"><Skeleton label={running ? "Cyrus is planning the files" : "No source files"} /></div>
        )}
      </div>
    </div>
  );
}

/** Files tab: every file grouped by folder, with live states. */
export function FilesList({ build, base, live, onOpen, folder }: { build: ModBuildView; base?: ModBuildView | null; live: LiveState; onOpen: (path: string) => void; folder?: string | null }) {
  const rows = useCodeRows(build, base, live);
  const groups = useMemo(() => {
    const g = new Map<string, Row[]>();
    for (const r of rows) { const f = folderOf(r.path); if (!g.has(f)) g.set(f, []); g.get(f)!.push(r); }
    return [...g.entries()];
  }, [rows]);
  useEffect(() => { if (folder) document.getElementById(`cy-f-${folder}`)?.scrollIntoView({ block: "start" }); }, [folder]);
  if (!rows.length) return <div className="cy-files"><p className="cy-sub">Files appear the moment Cyrus starts writing them.</p></div>;
  return (
    <div className="cy-files">
      {groups.map(([f, list]) => (
        <section key={f} id={`cy-f-${f}`} className={`cy-files-g ${folder === f ? "on" : ""}`}>
          <h4><CyIcon name="folder" size={16} tone="blue" /> {f} <span className="cy-count">{list.length}</span></h4>
          {list.map((r) => (
            <button key={r.path} type="button" className={`cy-files-f st-${r.state}`} onClick={() => onOpen(r.path)} title={r.path}>
              <CyIcon name={r.name.endsWith(".java") ? "code" : "docs"} size={14} />
              <span className="cy-tree-n">{r.name}</span>
              {(r.state === "writing" || r.state === "editing") && <span className="cy-fstate run">{r.state}</span>}
              {(r.state === "written" || r.state === "edited") && <CyIcon name="check" size={12} />}
            </button>
          ))}
        </section>
      ))}
    </div>
  );
}

/** Related folders + counts (mod card). */
export function useFolders(build: ModBuildView, base: ModBuildView | null | undefined, live: LiveState) {
  const rows = useCodeRows(build, base, live);
  return useMemo(() => {
    const m = new Map<string, number>();
    for (const r of rows) m.set(folderOf(r.path), (m.get(folderOf(r.path)) ?? 0) + 1);
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }, [rows]);
}

