          <h4><CyIcon name="folder" size={16} tone="blue" /> {f} <span className="cy-count">{list.length}</span></h4>
          {list.map((r) => (
            <button key={r.path} type="button" className={`cy-files-f st-${r.state}`} onClick={() => onOpen(r.path)} title={r.path}>
              <CyIcon name={r.name.endsWith(".java") ? "code" : "docs"} size={14} />
              <span className="cy-tree-n">{r.name}</span>
              {(r.state === "writing" || r.state === "editing") && <span className="cy-fstate run">{r.state}</span>}
              {(r.state === "written" || r.state === "edited") && <CyIcon name="check" size={12} />}
            </button>
          ))}
        </section>
      ))}
    </div>
  );
}

/** Related folders + counts (mod card). */
export function useFolders(build: ModBuildView, base: ModBuildView | null | undefined, live: LiveState) {
  const rows = useCodeRows(build, base, live);
  return useMemo(() => {
    const m = new Map<string, number>();
    for (const r of rows) m.set(folderOf(r.path), (m.get(folderOf(r.path)) ?? 0) + 1);
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }, [rows]);
}

