head='''"use client";

// The Cyrus composer (owner concept): mode tabs Chat / Generate / Debug / Refactor / Docs, the
// prompt, attach + screenshot + voice, the model picker (Katara / Saka / Yakko) and send.
// Every mode is a real build: Generate starts a new mod; Chat, Debug, Refactor and Docs build the
// next version of the selected mod with the request framed for that mode.
import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { CYRUS_MODELS, cyrusModel, type CyrusModelId } from "@/lib/cyrus/models";
import { CYRUS_DEFAULT_GAME, type CyrusGame } from "@/lib/cyrus/games";
import { estimate, fmtUsd, modelAdvice } from "@/lib/cyrus/estimate";
import { CyIcon, GameMark, ModelMark } from "./icons";
import { useVoice } from "./voice";

export type ComposerMode = "chat" | "generate" | "debug" | "refactor" | "docs";
export const COMPOSER_MODES: { id: ComposerMode; label: string; icon: string; hint: string }[] = [
  { id: "chat", label: "Chat", icon: "chat", hint: "Ask for a change to this mod" },
  { id: "generate", label: "Generate", icon: "generate", hint: "Describe a new mod" },
  { id: "debug", label: "Debug", icon: "debug", hint: "Describe what goes wrong" },
  { id: "refactor", label: "Refactor", icon: "refactor", hint: "Clean up the code, same behaviour" },
  { id: "docs", label: "Docs", icon: "docs", hint: "Document this mod" },
];
/** How each change mode frames the request for the build service (real requests, nothing simulated). */
export function frameRequest(mode: ComposerMode, text: string): string {
  const t = text.trim();
  switch (mode) {
    case "debug": return `Fix this problem in the mod: ${t}`;
    case "refactor": return `Refactor the code without changing what the mod does${t ? `: ${t}` : "."}`;
    case "docs": return `Document this mod: add Javadoc to public classes and methods and a README.md for server owners${t ? `. ${t}` : "."}`;
    default: return t;
  }
}

export type ComposerSubmit = { text: string; model: CyrusModelId; mcVersion: string; attachmentIds: string[]; mode: ComposerMode };
export type ComposerHandle = { focus: () => void; setText: (t: string, model?: CyrusModelId, mode?: ComposerMode) => void; toggleVoice: () => void; setMode: (m: ComposerMode) => void };
type Att = { key: string; name: string; url: string; status: "up" | "ok" | "err"; id?: string; error?: string };

const MAX_IMG = 4;

export const Composer = forwardRef<ComposerHandle, {
  /** the mod a change mode builds on (null = only Generate is possible) */
  target: { title: string; version: string; n: number } | null;
  defaultModel: CyrusModelId;
  defaultMode: ComposerMode;
  disabledReason?: string | null;
  onSubmit: (s: ComposerSubmit) => Promise<string | null>;
  onActivity?: (a: { typing: boolean; listening: boolean; level: number }) => void;
  game?: CyrusGame;
}>(function Composer({ target, defaultModel, defaultMode, disabledReason, onSubmit, onActivity, game = CYRUS_DEFAULT_GAME }, ref) {
  const [mode, setMode] = useState<ComposerMode>(defaultMode);
  const [text, setText] = useState("");
  const [model, setModel] = useState<CyrusModelId>(defaultModel);
  const [version, setVersion] = useState(game.defaultVersion || game.versions[0] || "");
  const [atts, setAtts] = useState<Att[]>([]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [drag, setDrag] = useState(false);
  const [pop, setPop] = useState<null | "model" | "game">(null);
  const ta = useRef<HTMLTextAreaElement>(null);
  const fileIn = useRef<HTMLInputElement>(null);
  const typingT = useRef<number | undefined>(undefined);
  const [typing, setTyping] = useState(false);
  const isNew = mode === "generate";
  const lockVersion = !isNew && target ? target.version : undefined;

  const voice = useVoice((said) => setText((t) => (t && !/\\s$/.test(t) ? t + " " : t) + said));

  useEffect(() => setModel(defaultModel), [defaultModel]);
  useEffect(() => setMode(defaultMode), [defaultMode]);

  useImperativeHandle(ref, () => ({
    focus: () => ta.current?.focus(),
    setText: (t, m, md) => { setText(t); if (m) setModel(m); if (md) setMode(md); requestAnimationFrame(() => { ta.current?.focus(); autosize(); }); },
    toggleVoice: () => voice.toggle(),
    setMode: (m) => { setMode(m); requestAnimationFrame(() => ta.current?.focus()); },
  }));

  useEffect(() => {
    if (!onActivity) return;
    if (!voice.listening) { onActivity({ typing, listening: false, level: 0 }); return; }
    let raf = 0;
    const tick = () => { onActivity({ typing, listening: true, level: voice.level.current }); raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [typing, voice.listening, onActivity, voice.level]);

  const autosize = () => {
    const el = ta.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, 180) + "px";
  };
  useEffect(autosize, [text]);

  const attsRef = useRef<Att[]>([]);
  attsRef.current = atts;
  const addFiles = useCallback((files: File[]) => {
    const imgs = files.filter((f) => /^image\\/(png|jpe?g|webp|gif)$/.test(f.type));
    if (!imgs.length) { if (files.length) setErr("Only PNG, JPG, WebP or GIF images can be attached."); return; }
    const room = MAX_IMG - attsRef.current.length;
    if (room <= 0) { setErr(`Up to ${MAX_IMG} images per request.`); return; }
    if (imgs.length > room) setErr(`Up to ${MAX_IMG} images per request.`);
    const add = imgs.slice(0, room).map((f) => ({ f, a: { key: Math.random().toString(36).slice(2), name: f.name || "pasted image", url: URL.createObjectURL(f), status: "up" as const } }));
    setAtts((cur) => [...cur, ...add.map((x) => x.a)]);
    for (const x of add) upload(x.a.key, x.f);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function upload(key: string, f: File) {
    if (f.size > 5 * 1024 * 1024) { setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "err", error: "Over 5 MB" } : a))); return; }
    const fd = new FormData();
    fd.append("file", f, f.name || "pasted.png");
    try {
      const r = await fetch("/api/mod-builder/uploads", { method: "POST", body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "Upload failed");
      setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "ok", id: j.upload.id } : a)));
    } catch (e) {
      setAtts((c) => c.map((a) => (a.key === key ? { ...a, status: "err", error: (e as Error).message } : a)));
    }
  }

  /** Screenshot: one frame of a screen, window or tab the user picks (getDisplayMedia), attached as an image. */
  async function screenshot() {
    const md = navigator.mediaDevices as MediaDevices & { getDisplayMedia?: (c: unknown) => Promise<MediaStream> };
    if (!md?.getDisplayMedia) { setErr("This browser can't take a screenshot. Paste or drop an image instead."); return; }
    try {
      const stream = await md.getDisplayMedia({ video: true, audio: false });
      const v = document.createElement("video");
      v.srcObject = stream; v.muted = true; await v.play();
      await new Promise((r) => setTimeout(r, 250));
      const c = document.createElement("canvas");
      c.width = v.videoWidth; c.height = v.videoHeight;
      c.getContext("2d")!.drawImage(v, 0, 0);
      stream.getTracks().forEach((t) => t.stop());
      const blob = await new Promise<Blob | null>((r) => c.toBlob(r, "image/png"));
      if (blob) addFiles([new File([blob], "screenshot.png", { type: "image/png" })]);
    } catch { /* cancelled */ }
  }

  const est = useMemo(() => estimate(text, model, { change: !isNew }), [text, model, isNew]);
  const advice = isNew && text.trim().length > 30 ? modelAdvice(est, model) : "ok";
  const minLen = isNew ? 12 : mode === "refactor" || mode === "docs" ? 0 : 4;
  const uploading = atts.some((a) => a.status === "up");
  const needTarget = !isNew && !target;
  const reason = needTarget ? "Pick a mod on the web first, or switch to Generate for a new one." : disabledReason;
  const canSend = !busy && !reason && text.trim().length >= minLen && !uploading;

  async function submit() {
    if (!canSend) {
      if (text.trim().length < minLen && !reason) setErr(isNew ? "Tell Cyrus a bit more about the mod." : "Describe it in a few words.");
      return;
    }
    if (voice.listening) voice.stop();
    setBusy(true); setErr(null);
    const e = await onSubmit({ text: isNew ? text.trim() : frameRequest(mode, text), model, mcVersion: lockVersion || version, attachmentIds: atts.filter((a) => a.status === "ok" && a.id).map((a) => a.id!), mode });
    setBusy(false);
    if (e) { setErr(e); return; }
    atts.forEach((a) => URL.revokeObjectURL(a.url));
    setText(""); setAtts([]);
  }

  const m = cyrusModel(model);
  const listening = voice.listening;
  const placeholder = isNew ? `Ask Cyrus anything… (e.g. "Create a new dimension mod for ${game.name}")`
    : target ? `${COMPOSER_MODES.find((x) => x.id === mode)!.hint}: ${target.title} v${target.n}…` : "Pick a mod on the web to change it";

  return (
    <div
      className={`cy-composer ${listening ? "listening" : ""} ${drag ? "drag" : ""} ${busy ? "busy" : ""}`}
      onDragOver={(e) => { if (e.dataTransfer.types.includes("Files")) { e.preventDefault(); setDrag(true); } }}
      onDragLeave={(e) => { if (e.currentTarget === e.target) setDrag(false); }}
      onDrop={(e) => { e.preventDefault(); setDrag(false); addFiles(Array.from(e.dataTransfer.files)); }}
    >
      <div className="cy-composer-box">
        <div className="cy-rim" aria-hidden="true" />
        <div className="cy-composer-in">
          <div className="cy-modes" role="tablist" aria-label="What Cyrus should do">
            {COMPOSER_MODES.map((x) => (
              <button key={x.id} type="button" role="tab" aria-selected={mode === x.id} className={`cy-mode ${mode === x.id ? "on" : ""}`} onClick={() => { setMode(x.id); setErr(null); ta.current?.focus(); }} title={x.hint}>
                <CyIcon name={x.icon} size={14} tone={mode === x.id ? "violet" : undefined} /> {x.label}
              </button>
            ))}
          </div>
          {atts.length > 0 && (
            <div className="cy-atts" aria-label="Attached images">
              {atts.map((a) => (
                <figure key={a.key} className={`cy-att ${a.status}`} title={a.error || a.name}>
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={a.url} alt={a.name} />
                  {a.status === "up" && <span className="cy-att-veil"><i className="cy-spin" /></span>}
                  {a.status === "err" && <span className="cy-att-veil err"><CyIcon name="warn" size={14} /></span>}
                  <button type="button" aria-label={`Remove ${a.name}`} onClick={() => { URL.revokeObjectURL(a.url); setAtts((c) => c.filter((x) => x.key !== a.key)); }}>
                    <CyIcon name="x" size={10} strokeWidth={2.2} />
                  </button>
                </figure>
              ))}
              <span className="cy-att-note"><CyIcon name="eye" size={12} /> Cyrus looks at {atts.length === 1 ? "this image" : "these images"} while it plans.</span>
