  const list = CYRUS_TEMPLATES.filter((t) => cat === "All" || t.cat === cat);
  return (
    <Modal title="Templates" sub="Every one builds on plain Paper. Pick one, then make it yours in the prompt." onClose={onClose} wide>
      <div className="cy-cats" role="tablist">
        {CYRUS_TEMPLATE_CATS.map((c) => <button key={c} type="button" role="tab" aria-selected={cat === c} className={`cy-cat ${cat === c ? "on" : ""}`} onClick={() => setCat(c)}>{c}</button>)}
      </div>
      <div className="cy-tpls">
        {list.map((t) => {
          const e = estimate(t.prompt, t.model);
          const m = cyrusModel(t.model);
          return (
            <button key={t.id} type="button" className="cy-tpl" onClick={() => onUse(t)}>
              <span className="cy-tpl-top"><ModCube hue="#8b6dff" size={24} /><span className="cy-tpl-cat">{t.cat}</span></span>
              <b className="cy-tpl-t">{t.title}</b>
              <span className="cy-tpl-d">{t.blurb}</span>
              <span className="cy-tpl-f"><ModelMark tier={m.spend} /> {m.name} · ~{e.minutes[0]}–{e.minutes[1]} min</span>
            </button>
          );
        })}
      </div>
    </Modal>
  );
}

/** Info sheets: Cyrus Pro, Add Game. Honest about what exists today. */
export function InfoModal({ kind, onClose }: { kind: "pro" | "addgame"; onClose: () => void }) {
  if (kind === "pro") return (
    <Modal title="Cyrus Pro" sub="Higher limits, faster models, advanced mod tools." onClose={onClose}>
      <ul className="cy-bullets">
        <li>Cyrus is in a free private preview: builds aren&apos;t charged yet.</li>
        <li>Pro arrives with Cyrus token plans: more builds at once, more Yakko time, bigger mods.</li>
      </ul>
      <div className="flex justify-end"><button type="button" className="cy-btn primary" onClick={onClose}>Got it</button></div>
    </Modal>
  );
  return (
    <Modal title="Add a game" sub="Cyrus builds Minecraft (Paper) plugins today. These are next." onClose={onClose}>
      <div className="cy-games">
        {CYRUS_GAMES.map((g) => (
          <div key={g.id} className={`cy-game ${g.status === "live" ? "on" : "soon"}`}>
            <GameEmblem game={g.id} size={30} />
            <span className="cy-game-b"><span className="cy-game-n">{g.name}</span><span className="cy-game-s">{g.builds}</span></span>
            <span className={`cy-tag ${g.status === "live" ? "sig" : ""}`}>{g.status === "live" ? "Live" : "Soon"}</span>
          </div>
        ))}
      </div>
      <p className="cy-sub">Want another game? Tell us from Support and we&apos;ll weigh it for the roadmap.</p>
      <div className="flex justify-end gap-2"><Link href="/dashboard/support" className="cy-btn">Contact support</Link><button type="button" className="cy-btn primary" onClick={onClose}>Done</button></div>
    </Modal>
  );
}
