// Cyrus: pure helpers shared by the stage and the inspector (unit-tested in test/cyrus.test.ts):
// stage progress, stage headlines, and the mapping from real build events to light on the web.
import { hashSeed } from "@/lib/cyrus/projects";

// v3: the web speaks in ink + one signal; the engine picks the tone from status, so these are only
// stable, neutral identities (kept for hover cards and tests).
export const BRAND_HEX = { ink: "#edeef0", dim: "#8e939b", signal: "#cdf24b", alert: "#ff6b4f" } as const;
const MOD_HUES = ["#edeef0", "#d9dbde", "#c4c7cc", "#b3b7be"];

/** A mod's own colour (stable per project). */
export const modColor = (rootId: string) => MOD_HUES[hashSeed(rootId) % MOD_HUES.length];

export const PROGRESS: Record<string, number> = { queued: 0.04, planning: 0.14, coding: 0.4, compiling: 0.62, repairing: 0.72, scanning: 0.88, succeeded: 1, failed: 1 };

export const STAGE_HEADLINE: Record<string, string> = {
  queued: "Waiting for a free builder",
  planning: "Mapping out your mod",
  coding: "Weaving the code",
  compiling: "Compiling it into a real plugin",
  repairing: "Found a problem, fixing it",

