/* ═══ v4 layout ═══════════════════════════════════════════════════════════ */
.cy-app { position: relative; height: 100%; min-height: 560px; display: grid; grid-template-columns: var(--cy-side-w) minmax(0, 1fr); overflow: hidden; isolation: isolate; background: var(--cy-bg0); container: cyapp / inline-size; }
.cy-main { position: relative; min-width: 0; overflow: hidden; }

/* ── sidebar ─────────────────────────────────────────────────────────── */
.cy-side { position: relative; z-index: 20; display: flex; flex-direction: column; min-height: 0; padding: 14px 12px 14px; background: var(--cy-side); border-right: 1px solid var(--cy-line); overflow-y: auto; scrollbar-width: none; }
.cy-side-logo { display: flex; align-items: center; height: 40px; padding: 0 8px; margin-bottom: 14px; }
.cy-side-nav { display: flex; flex-direction: column; gap: 3px; }
.cy-side-i { position: relative; display: flex; align-items: center; gap: 14px; height: 40px; padding: 0 12px; border-radius: var(--cy-r-md); font-size: 13.5px; font-weight: 500; color: var(--cy-ink2); text-decoration: none; transition: background .18s, color .18s; }
.cy-side-i svg { color: var(--cy-ink3); }
.cy-side-i:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-side-i.on { color: #fff; background: linear-gradient(100deg, rgba(64, 108, 255, .42), rgba(139, 61, 255, .3) 70%, rgba(139, 61, 255, .12)); box-shadow: inset 0 0 0 1px rgba(130, 140, 255, .32), 0 8px 26px -12px rgba(90, 90, 255, .8); }
.cy-beta { margin-left: auto; font: 700 9.5px/1 var(--font-sans, inherit); letter-spacing: .06em; text-transform: uppercase; padding: 4px 7px; border-radius: 999px; color: #fff; background: linear-gradient(100deg, #b13dff, #e04dff); font-style: normal; box-shadow: 0 0 12px -2px rgba(224, 77, 255, .7); }
.cy-side-h { display: flex; align-items: center; justify-content: space-between; margin: 22px 4px 8px 10px; padding-top: 16px; border-top: 1px solid var(--cy-line); font-size: 12.5px; font-weight: 500; color: var(--cy-ink3); }
.cy-side-add { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--cy-ink2); border: 1px solid var(--cy-line2); background: var(--cy-raise); }
.cy-side-add:hover { color: var(--cy-ink); border-color: var(--cy-accent-line); }
.cy-side-proj { display: flex; flex-direction: column; gap: 2px; }
.cy-side-p { display: flex; align-items: center; gap: 12px; height: 38px; padding: 0 10px; border-radius: var(--cy-r-md); font-size: 13px; font-weight: 500; color: var(--cy-ink2); text-align: left; transition: background .18s, color .18s; }
.cy-side-p:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-side-p.on { color: #fff; background: linear-gradient(100deg, rgba(139, 61, 255, .45), rgba(110, 70, 255, .22)); box-shadow: inset 0 0 0 1px rgba(160, 120, 255, .35); }
.cy-side-p.soon .cy-emblem { opacity: .7; filter: saturate(.75); }
.cy-side-pi { display: grid; place-items: center; width: 20px; }
.cy-side-n { margin-left: auto; font: 500 10.5px/1 var(--font-mono); font-style: normal; color: var(--cy-ink3); }
.cy-side-soon { margin-left: auto; font-size: 10px; font-style: normal; color: var(--cy-ink4); }
.cy-pro { margin-top: auto; padding: 14px; border-radius: var(--cy-r-lg); background: linear-gradient(160deg, rgba(60, 50, 160, .28), rgba(20, 18, 60, .6)); border: 1px solid rgba(160, 120, 255, .3); box-shadow: 0 0 30px -12px rgba(139, 92, 255, .6), inset 0 1px 0 rgba(255, 255, 255, .06); }
.cy-pro-h { display: flex; align-items: center; gap: 9px; font-size: 15px; font-weight: 600; color: var(--cy-ink); }
.cy-pro p { margin: 6px 0 12px; font-size: 12px; line-height: 1.45; color: var(--cy-ink2); }
.cy-pro-go { display: flex; align-items: center; justify-content: center; gap: 7px; width: 100%; height: 36px; border-radius: var(--cy-r); font-size: 13px; font-weight: 600; color: #fff; background: var(--cy-grad); box-shadow: 0 10px 26px -12px rgba(190, 70, 255, .9); transition: filter .15s, transform .15s var(--cy-ease); }
.cy-pro-go:hover { filter: brightness(1.08); transform: translateY(-1px); }
.cy-side-back { display: none; }

/* ── top bar ─────────────────────────────────────────────────────────── */
.cy-top { position: absolute; z-index: 12; top: 0; left: 0; right: 0; height: 56px; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 14px; }
.cy-top-menu { display: none; }
.cy-top-search { display: flex; align-items: center; gap: 12px; height: 38px; width: min(550px, 46%); padding: 0 8px 0 14px; border-radius: var(--cy-r-md); color: var(--cy-ink3); background: rgba(10, 12, 38, .72); border: 1px solid var(--cy-line2); -webkit-backdrop-filter: var(--cy-blur); backdrop-filter: var(--cy-blur); text-align: left; transition: border-color .18s; }
.cy-top-search:hover { border-color: var(--cy-line3); }
.cy-top-search span { flex: 1; min-width: 0; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cy-top-r { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.cy-top-theme { display: inline-flex; }
.cy-top-ib { display: grid; place-items: center; width: 38px; height: 38px; border-radius: var(--cy-r); color: var(--cy-ink2); transition: background .15s, color .15s; }
.cy-top-ib:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-top-me { display: flex; align-items: center; gap: 9px; margin-left: 6px; padding: 3px 6px 3px 3px; border-radius: 999px; text-decoration: none; color: var(--cy-ink); transition: background .15s; }
.cy-top-me:hover { background: var(--cy-raise-2); }
.cy-top-av { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; font-size: 13px; font-weight: 700; color: #fff; background: linear-gradient(150deg, #3b6be8, #7b3fef 60%, #c04dff); box-shadow: 0 0 14px -3px rgba(139, 92, 255, .8); }
.cy-top-name { font-size: 13px; font-weight: 600; }
.cy-net { position: absolute; z-index: 13; top: 60px; left: 50%; transform: translateX(-50%); display: inline-flex; align-items: center; gap: 8px; padding: 6px 12px; border-radius: 999px; font-size: 12px; color: var(--cy-warn); background: var(--cy-pop); border: 1px solid var(--cy-line2); }

/* ── stage + nodes ───────────────────────────────────────────────────── */
.cy-stage { position: absolute; inset: 0; z-index: 0; }
.cy-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: grab; }
.cy-layer-world { position: absolute; left: 0; top: 0; width: 0; height: 0; transform-origin: 0 0; pointer-events: none; will-change: transform; color: #eef0ff; }
.cy-n { position: absolute; pointer-events: auto; --c: color-mix(in srgb, var(--hue) 75%, white 0%); }
/* core */
.cy-n-core { width: 132px; height: 132px; transform: translate(-50%, -50%); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, rgba(40, 30, 110, .95), rgba(10, 9, 38, .98) 70%); box-shadow: 0 0 40px -6px rgba(110, 80, 255, .85), 0 0 90px -20px rgba(80, 120, 255, .7), inset 0 0 26px rgba(120, 90, 255, .45); pointer-events: none; }
.cy-core-ring { position: absolute; inset: -3px; border-radius: 50%; padding: 3px; background: conic-gradient(from var(--cy-ang), #3b82ff, #8b5cff, #e04dff, #22d3ee, #3b82ff);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); animation: cy-rim 14s linear infinite; filter: drop-shadow(0 0 6px rgba(139, 92, 255, .9)); }
.cy-n-core.busy .cy-core-ring { animation-duration: 5s; }
.cy-n-core .cy-mark { height: 44px; }
.cy-core-t { font-size: 20px; font-weight: 600; letter-spacing: -.01em; color: #fff; text-shadow: 0 0 14px rgba(140, 110, 255, .8); }
.cy-core-s { position: absolute; bottom: -26px; font: 500 10.5px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: #b9a2ff; white-space: nowrap; }
/* game */
.cy-n-game { width: var(--d); height: var(--d); transform: translate(-50%, -50%); display: block; }
.cy-n-disc { position: absolute; inset: 0; display: grid; place-items: center; border-radius: 50%; background: radial-gradient(circle at 50% 40%, #161540, #07081e 72%);
  border: 1.5px solid color-mix(in srgb, var(--hue) 80%, white 10%); box-shadow: 0 0 22px -4px color-mix(in srgb, var(--hue) 75%, transparent), inset 0 0 16px color-mix(in srgb, var(--hue) 30%, transparent); transition: transform .2s var(--cy-ease), box-shadow .2s; }
.cy-n-game:hover .cy-n-disc, .cy-n-game.on .cy-n-disc { transform: scale(1.06); box-shadow: 0 0 30px -2px color-mix(in srgb, var(--hue) 90%, transparent), inset 0 0 18px color-mix(in srgb, var(--hue) 40%, transparent); }
.cy-n-name { position: absolute; left: 50%; top: calc(100% - 6px); transform: translateX(-50%); display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 11px; border-radius: 8px; white-space: nowrap;
  font-size: 13.5px; font-weight: 600; color: #fff; background: rgba(8, 9, 30, .9); border: 1px solid color-mix(in srgb, var(--hue) 35%, transparent); box-shadow: 0 6px 18px -8px rgba(0, 0, 0, .8); }
.cy-n-name em { font: 600 9px/1 var(--font-mono); font-style: normal; letter-spacing: .08em; text-transform: uppercase; color: #aab1e0; padding: 3px 5px; border-radius: 4px; background: rgba(150, 160, 255, .12); }
.cy-n-game.soon .cy-n-disc { filter: saturate(.8) brightness(.85); }
.cy-n-game.add .cy-n-disc { border-color: rgba(150, 130, 255, .6); }
.cy-n-game.add .cy-n-name { font-size: 12.5px; font-weight: 500; color: #dfe3ff; }
/* category */
.cy-n-cat { display: flex; align-items: center; transform: translate(-17px, -50%); }
.cy-n-ic { position: relative; z-index: 1; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: radial-gradient(circle, #121238, #07081e 75%); border: 1.5px solid color-mix(in srgb, var(--hue) 80%, white 10%); box-shadow: 0 0 16px -3px color-mix(in srgb, var(--hue) 75%, transparent); }
.cy-n-lbl { margin-left: -10px; height: 30px; display: inline-flex; align-items: center; padding: 0 12px 0 18px; border-radius: 0 9px 9px 0; white-space: nowrap; font-size: 12.5px; font-weight: 600; color: #fff; background: rgba(8, 9, 30, .9); border: 1px solid color-mix(in srgb, var(--hue) 35%, transparent); border-left: 0; }
.cy-n-cat:hover .cy-n-ic, .cy-n-cat.on .cy-n-ic { box-shadow: 0 0 24px -1px color-mix(in srgb, var(--hue) 90%, transparent); }
