/* mod pills */
.cy-n-pill { transform: translate(0, -50%); display: flex; align-items: center; gap: 7px; padding: 0 9px 0 6px; border-radius: 7px; white-space: nowrap; overflow: hidden;
  font-size: 11.5px; font-weight: 500; color: #e7eaff; background: rgba(9, 10, 32, .9); border: 1px solid color-mix(in srgb, var(--hue) 30%, rgba(150, 160, 255, .12)); box-shadow: 0 0 12px -6px color-mix(in srgb, var(--hue) 70%, transparent);
  transition: border-color .18s, box-shadow .18s, background .18s, transform .18s var(--cy-ease); }
.cy-n-pill:hover { border-color: color-mix(in srgb, var(--hue) 70%, transparent); box-shadow: 0 0 18px -4px color-mix(in srgb, var(--hue) 80%, transparent); transform: translate(2px, -50%); }
.cy-n-pill.on { color: #fff; background: color-mix(in srgb, var(--hue) 18%, rgba(9, 10, 32, .95)); border-color: color-mix(in srgb, var(--hue) 90%, white 10%); box-shadow: 0 0 22px -3px color-mix(in srgb, var(--hue) 90%, transparent); }
.cy-n-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.cy-n-cube { position: relative; display: grid; place-items: center; width: 17px; height: 17px; flex: none; }
.cy-n-cube.run::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; border: 1.5px solid transparent; border-top-color: var(--hue); border-right-color: var(--hue); animation: cy-spin 1.4s linear infinite; }
.cy-n-pill.st-running { border-color: color-mix(in srgb, var(--hue) 75%, transparent); }
.cy-n-bad { width: 6px; height: 6px; border-radius: 50%; flex: none; margin-left: auto; background: var(--cy-alert); box-shadow: 0 0 6px var(--cy-alert); }
