.cy-pro { margin-top: auto; padding: 14px; border-radius: var(--cy-r-lg); background: linear-gradient(160deg, rgba(60, 50, 160, .28), rgba(20, 18, 60, .6)); border: 1px solid rgba(160, 120, 255, .3); box-shadow: 0 0 30px -12px rgba(139, 92, 255, .6), inset 0 1px 0 rgba(255, 255, 255, .06); }
.cy-pro-h { display: flex; align-items: center; gap: 9px; font-size: 15px; font-weight: 600; color: var(--cy-ink); }
.cy-pro p { margin: 6px 0 12px; font-size: 12px; line-height: 1.45; color: var(--cy-ink2); }
.cy-pro-go { display: flex; align-items: center; justify-content: center; gap: 7px; width: 100%; height: 36px; border-radius: var(--cy-r); font-size: 13px; font-weight: 600; color: #fff; background: var(--cy-grad); box-shadow: 0 10px 26px -12px rgba(190, 70, 255, .9); transition: filter .15s, transform .15s var(--cy-ease); }
.cy-pro-go:hover { filter: brightness(1.08); transform: translateY(-1px); }
.cy-side-back { display: none; }

/* ── top bar ─────────────────────────────────────────────────────────── */
.cy-top { position: absolute; z-index: 12; top: 0; left: 0; right: 0; height: 56px; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 14px; }
.cy-top-menu { display: none; }
.cy-top-search { display: flex; align-items: center; gap: 12px; height: 38px; width: min(550px, 46%); padding: 0 8px 0 14px; border-radius: var(--cy-r-md); color: var(--cy-ink3); background: rgba(10, 12, 38, .72); border: 1px solid var(--cy-line2); -webkit-backdrop-filter: var(--cy-blur); backdrop-filter: var(--cy-blur); text-align: left; transition: border-color .18s; }
.cy-top-search:hover { border-color: var(--cy-line3); }
.cy-top-search span { flex: 1; min-width: 0; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cy-top-r { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.cy-top-theme { display: inline-flex; }
.cy-top-ib { display: grid; place-items: center; width: 38px; height: 38px; border-radius: var(--cy-r); color: var(--cy-ink2); transition: background .15s, color .15s; }
.cy-top-ib:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-top-me { display: flex; align-items: center; gap: 9px; margin-left: 6px; padding: 3px 6px 3px 3px; border-radius: 999px; text-decoration: none; color: var(--cy-ink); transition: background .15s; }
.cy-top-me:hover { background: var(--cy-raise-2); }
.cy-top-av { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; font-size: 13px; font-weight: 700; color: #fff; background: linear-gradient(150deg, #3b6be8, #7b3fef 60%, #c04dff); box-shadow: 0 0 14px -3px rgba(139, 92, 255, .8); }
.cy-top-name { font-size: 13px; font-weight: 600; }
.cy-net { position: absolute; z-index: 13; top: 60px; left: 50%; transform: translateX(-50%); display: inline-flex; align-items: center; gap: 8px; padding: 6px 12px; border-radius: 999px; font-size: 12px; color: var(--cy-warn); background: var(--cy-pop); border: 1px solid var(--cy-line2); }

/* ── stage + nodes ───────────────────────────────────────────────────── */
.cy-stage { position: absolute; inset: 0; z-index: 0; }
.cy-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: grab; }
.cy-layer-world { position: absolute; left: 0; top: 0; width: 0; height: 0; transform-origin: 0 0; pointer-events: none; will-change: transform; color: #eef0ff; }
.cy-n { position: absolute; pointer-events: auto; --c: color-mix(in srgb, var(--hue) 75%, white 0%); }
/* core */
.cy-n-core { width: 132px; height: 132px; transform: translate(-50%, -50%); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, rgba(40, 30, 110, .95), rgba(10, 9, 38, .98) 70%); box-shadow: 0 0 40px -6px rgba(110, 80, 255, .85), 0 0 90px -20px rgba(80, 120, 255, .7), inset 0 0 26px rgba(120, 90, 255, .45); pointer-events: none; }
.cy-core-ring { position: absolute; inset: -3px; border-radius: 50%; padding: 3px; background: conic-gradient(from var(--cy-ang), #3b82ff, #8b5cff, #e04dff, #22d3ee, #3b82ff);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); animation: cy-rim 14s linear infinite; filter: drop-shadow(0 0 6px rgba(139, 92, 255, .9)); }
.cy-n-core.busy .cy-core-ring { animation-duration: 5s; }
.cy-n-core .cy-mark { height: 44px; }
.cy-core-t { font-size: 20px; font-weight: 600; letter-spacing: -.01em; color: #fff; text-shadow: 0 0 14px rgba(140, 110, 255, .8); }
.cy-core-s { position: absolute; bottom: -26px; font: 500 10.5px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: #b9a2ff; white-space: nowrap; }
/* game */
.cy-n-game { width: var(--d); height: var(--d); transform: translate(-50%, -50%); display: block; }
.cy-n-disc { position: absolute; inset: 0; display: grid; place-items: center; border-radius: 50%; background: radial-gradient(circle at 50% 40%, #161540, #07081e 72%);
  border: 1.5px solid color-mix(in srgb, var(--hue) 80%, white 10%); box-shadow: 0 0 22px -4px color-mix(in srgb, var(--hue) 75%, transparent), inset 0 0 16px color-mix(in srgb, var(--hue) 30%, transparent); transition: transform .2s var(--cy-ease), box-shadow .2s; }
.cy-n-game:hover .cy-n-disc, .cy-n-game.on .cy-n-disc { transform: scale(1.06); box-shadow: 0 0 30px -2px color-mix(in srgb, var(--hue) 90%, transparent), inset 0 0 18px color-mix(in srgb, var(--hue) 40%, transparent); }
.cy-n-name { position: absolute; left: 50%; top: calc(100% - 6px); transform: translateX(-50%); display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 11px; border-radius: 8px; white-space: nowrap;
  font-size: 13.5px; font-weight: 600; color: #fff; background: rgba(8, 9, 30, .9); border: 1px solid color-mix(in srgb, var(--hue) 35%, transparent); box-shadow: 0 6px 18px -8px rgba(0, 0, 0, .8); }
.cy-n-name em { font: 600 9px/1 var(--font-mono); font-style: normal; letter-spacing: .08em; text-transform: uppercase; color: #aab1e0; padding: 3px 5px; border-radius: 4px; background: rgba(150, 160, 255, .12); }
.cy-n-game.soon .cy-n-disc { filter: saturate(.8) brightness(.85); }
.cy-n-game.add .cy-n-disc { border-color: rgba(150, 130, 255, .6); }
.cy-n-game.add .cy-n-name { font-size: 12.5px; font-weight: 500; color: #dfe3ff; }
/* category */
.cy-n-cat { display: flex; align-items: center; transform: translate(-17px, -50%); }
.cy-n-ic { position: relative; z-index: 1; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: radial-gradient(circle, #121238, #07081e 75%); border: 1.5px solid color-mix(in srgb, var(--hue) 80%, white 10%); box-shadow: 0 0 16px -3px color-mix(in srgb, var(--hue) 75%, transparent); }
.cy-n-lbl { margin-left: -10px; height: 30px; display: inline-flex; align-items: center; padding: 0 12px 0 18px; border-radius: 0 9px 9px 0; white-space: nowrap; font-size: 12.5px; font-weight: 600; color: #fff; background: rgba(8, 9, 30, .9); border: 1px solid color-mix(in srgb, var(--hue) 35%, transparent); border-left: 0; }
.cy-n-cat:hover .cy-n-ic, .cy-n-cat.on .cy-n-ic { box-shadow: 0 0 24px -1px color-mix(in srgb, var(--hue) 90%, transparent); }
.cy-n-cat.on .cy-n-lbl { border-color: color-mix(in srgb, var(--hue) 70%, transparent); }
/* mod pills */
.cy-n-pill { transform: translate(0, -50%); display: flex; align-items: center; gap: 7px; padding: 0 9px 0 6px; border-radius: 7px; white-space: nowrap; overflow: hidden;
  font-size: 11.5px; font-weight: 500; color: #e7eaff; background: rgba(9, 10, 32, .9); border: 1px solid color-mix(in srgb, var(--hue) 30%, rgba(150, 160, 255, .12)); box-shadow: 0 0 12px -6px color-mix(in srgb, var(--hue) 70%, transparent);
  transition: border-color .18s, box-shadow .18s, background .18s, transform .18s var(--cy-ease); }
.cy-n-pill:hover { border-color: color-mix(in srgb, var(--hue) 70%, transparent); box-shadow: 0 0 18px -4px color-mix(in srgb, var(--hue) 80%, transparent); transform: translate(2px, -50%); }
.cy-n-pill.on { color: #fff; background: color-mix(in srgb, var(--hue) 18%, rgba(9, 10, 32, .95)); border-color: color-mix(in srgb, var(--hue) 90%, white 10%); box-shadow: 0 0 22px -3px color-mix(in srgb, var(--hue) 90%, transparent); }
.cy-n-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.cy-n-cube { position: relative; display: grid; place-items: center; width: 17px; height: 17px; flex: none; }
.cy-n-cube.run::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; border: 1.5px solid transparent; border-top-color: var(--hue); border-right-color: var(--hue); animation: cy-spin 1.4s linear infinite; }
.cy-n-pill.st-running { border-color: color-mix(in srgb, var(--hue) 75%, transparent); }
.cy-n-bad { width: 6px; height: 6px; border-radius: 50%; flex: none; margin-left: auto; background: var(--cy-alert); box-shadow: 0 0 6px var(--cy-alert); }
.cy-n-pill.k-more { justify-content: center; padding: 0 10px; color: #aab1e0; font-weight: 500; }
.cy-n-pill.k-tpl, .cy-n-pill.k-start { border-style: dashed; background: rgba(9, 10, 32, .7); color: #c5cbef; }
.cy-n-pill.k-start { color: #aab1e0; gap: 5px; padding-left: 8px; }
.cy-n-tag { margin-left: auto; font: 600 8.5px/1 var(--font-mono); font-style: normal; letter-spacing: .06em; text-transform: uppercase; color: #aab1e0; padding: 2px 4px; border-radius: 3px; background: rgba(150, 160, 255, .12); }
/* soon leaves */
.cy-n-leaf { width: 30px; height: 30px; transform: translate(-50%, -50%); display: grid; place-items: center; border-radius: 50%; background: radial-gradient(circle, #121238, #07081e 75%); border: 1.2px solid color-mix(in srgb, var(--hue) 70%, transparent); box-shadow: 0 0 14px -4px color-mix(in srgb, var(--hue) 70%, transparent); opacity: .8; }
.cy-n-dots { transform: translate(-50%, -50%); height: 20px; padding: 0 9px; display: grid; place-items: center; border-radius: 6px; font-size: 12px; letter-spacing: 1px; color: #aab1e0; background: rgba(9, 10, 32, .85); border: 1px solid rgba(150, 160, 255, .16); opacity: .8; }

/* ── inspector ───────────────────────────────────────────────────────── */
.cy-insp { position: absolute; z-index: 10; top: 64px; right: 12px; bottom: 12px; width: var(--cy-insp-w); display: flex; flex-direction: column; gap: 12px; transition: width .3s var(--cy-ease); }
.cy-insp.wide { width: min(64vw, 900px); }
.cy-insp-act { display: flex; justify-content: flex-end; gap: 8px; flex: none; }
.cy-insp-panel { flex: 1; min-height: 0; display: flex; flex-direction: column; border-radius: var(--cy-r-lg); background: var(--cy-surface); border: 1px solid var(--cy-line2); box-shadow: var(--cy-shadow), 0 0 40px -24px rgba(139, 92, 255, .6); -webkit-backdrop-filter: var(--cy-blur); backdrop-filter: var(--cy-blur); overflow: hidden; }
.cy-insp.empty { top: 120px; }
.cy-tabs { display: flex; align-items: center; gap: 4px; padding: 8px 8px 0; height: 52px; flex: none; border-bottom: 1px solid var(--cy-line); }
.cy-tab { position: relative; display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 13px; border-radius: var(--cy-r); font-size: 13px; font-weight: 500; color: var(--cy-ink3); transition: color .15s, background .15s; }
.cy-tab:hover { color: var(--cy-ink); background: var(--cy-raise); }
.cy-tab.on { color: var(--cy-ink); background: linear-gradient(180deg, rgba(110, 90, 255, .28), rgba(110, 90, 255, .12)); box-shadow: inset 0 0 0 1px rgba(150, 120, 255, .38), 0 6px 18px -10px rgba(139, 92, 255, .9); }
.cy-tab-n { display: inline-grid; place-items: center; min-width: 20px; height: 18px; padding: 0 5px; border-radius: 6px; font: 600 10.5px/1 var(--font-mono); color: var(--cy-ink2); background: var(--cy-raise-3); }
.cy-insp-body { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: flex; flex-direction: column; }
/* code */
.cy-code { flex: none; display: flex; flex-direction: column; height: clamp(260px, 40vh, 380px); }
.cy-insp.wide .cy-code { height: clamp(320px, 52vh, 560px); }
.cy-code-h { display: flex; align-items: center; gap: 8px; height: 50px; flex: none; padding: 0 12px 0 16px; }
.cy-code-dir { flex: 1; min-width: 0; font: 400 11.5px/1 var(--font-mono); color: var(--cy-ink3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; direction: rtl; text-align: left; }
.cy-code-sel { position: relative; display: inline-flex; align-items: center; flex: none; }
.cy-code-sel select { appearance: none; height: 32px; padding: 0 30px 0 12px; max-width: 220px; border-radius: var(--cy-r); font-size: 12.5px; font-weight: 500; color: var(--cy-ink); background: var(--cy-raise-2); border: 1px solid var(--cy-line2); cursor: pointer; }
.cy-code-sel select option { background: var(--cy-pop); color: var(--cy-ink); }
.cy-code-sel svg { position: absolute; right: 9px; pointer-events: none; color: var(--cy-ink3); }
.cy-code-ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: var(--cy-r-sm); color: var(--cy-ink3); }
.cy-code-ib:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-view { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; margin: 0 10px; border-radius: var(--cy-r-md); background: var(--cy-code-bg); border: 1px solid var(--cy-line); }
.cy-view-path { position: absolute; z-index: 2; top: 6px; right: 8px; display: flex; align-items: center; gap: 8px; height: auto; padding: 0; border: 0; }
.cy-view-scroll { padding: 10px 0 14px; }
.cy-lines { font: 400 12.5px/1.72 var(--font-mono); color: var(--cy-code-ink); }
.cy-ln .n { width: 40px; padding-right: 16px; color: var(--cy-code-n); }
:is(.cy-lines, .cy-dl) .k { color: #ff6bd5; font-weight: 400; } :is(.cy-lines, .cy-dl) .s { color: #9df27a; } :is(.cy-lines, .cy-dl) .t { color: #5fd4ff; }
:is(.cy-lines, .cy-dl) .a { color: #4fe3c1; font-style: normal; } :is(.cy-lines, .cy-dl) .m { color: #7480b3; font-style: italic; }
:root.nx-portal[data-theme="light"] :is(.cy-lines, .cy-dl) .k { color: #c0179a; } :root.nx-portal[data-theme="light"] :is(.cy-lines, .cy-dl) .s { color: #2b7a12; }
:root.nx-portal[data-theme="light"] :is(.cy-lines, .cy-dl) .t { color: #0b6fb0; } :root.nx-portal[data-theme="light"] :is(.cy-lines, .cy-dl) .a { color: #0f7d68; }
:root.nx-portal[data-theme="light"] :is(.cy-lines, .cy-dl) .m { color: #6b7097; }
.cy-caret { background: #c49bff; box-shadow: 0 0 8px rgba(196, 155, 255, .9); }
.cy-view-tag { font: 500 10px/1 var(--font-mono); letter-spacing: .06em; text-transform: uppercase; color: #c4a6ff; padding: 4px 7px; border-radius: 5px; background: rgba(10, 12, 38, .9); }
/* mod card */
.cy-mod { margin: 12px 10px 12px; padding: 16px; border-radius: var(--cy-r-lg); background: var(--cy-surface-2); border: 1px solid var(--cy-line2); }
.cy-mod-h { display: flex; align-items: center; gap: 10px; }
.cy-mod-ic { display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: 10px; background: color-mix(in srgb, var(--hue) 16%, transparent); border: 1px solid color-mix(in srgb, var(--hue) 40%, transparent); }
.cy-mod-t { flex: 1; min-width: 0; font-size: 18px; font-weight: 600; letter-spacing: -.015em; color: var(--cy-ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: text; }
.cy-mod .cy-rename { flex: 1; } .cy-mod .cy-rename input { width: 100%; font-size: 16px; font-weight: 600; color: var(--cy-ink); background: var(--cy-raise-2); border: 1px solid var(--cy-line3); border-radius: var(--cy-r); padding: 3px 9px; outline: 0; }
.cy-chip { display: inline-flex; align-items: center; height: 26px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 500; color: var(--cy-ink2); background: var(--cy-raise); border: 1px solid var(--cy-line2); white-space: nowrap; flex: none; }
.cy-chip.ver { color: #7fe3ff; font-variant-numeric: tabular-nums; }
.cy-chip.dim { color: var(--cy-ink3); font: 500 11px/1 var(--font-mono); }
:root.nx-portal[data-theme="light"] .cy-chip.ver { color: #0b6fb0; }
.cy-mod-d { margin-top: 12px; font-size: 13px; line-height: 1.6; color: var(--cy-ink2); display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.cy-mod-older { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; margin-top: 10px; font-size: 12px; color: var(--cy-ink2); }
.cy-mod-older button { font-weight: 600; color: var(--cy-accent-ink); }
.cy-mod-act { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.cy-mod-act .cy-btn { flex: 1 1 auto; }
.cy-soon-t { font: 600 8.5px/1 var(--font-mono); font-style: normal; letter-spacing: .06em; text-transform: uppercase; color: var(--cy-ink3); padding: 2px 4px; border-radius: 3px; background: var(--cy-raise-3); }
.cy-rel { display: flex; flex-direction: column; margin-top: 16px; }
.cy-rel h4, .cy-welcome h4 { font-size: 14px; font-weight: 600; color: var(--cy-ink); margin-bottom: 8px; }
.cy-rel-r { display: flex; align-items: center; gap: 12px; height: 40px; padding: 0 10px; border-top: 1px solid var(--cy-line); font-size: 13px; color: var(--cy-ink); text-align: left; transition: background .15s; border-radius: 0; }
.cy-rel-r:first-of-type { border-top: 0; }
.cy-rel-r:hover { background: var(--cy-raise); }
.cy-rel-r span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cy-rel-r em { font-style: normal; font-size: 12px; color: var(--cy-ink3); white-space: nowrap; max-width: 55%; overflow: hidden; text-overflow: ellipsis; }
.cy-rel-r > svg:last-child { color: var(--cy-ink3); }
.cy-mod-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--cy-line); font-size: 11.5px; color: var(--cy-ink3); }
.cy-mod .cy-fail { width: auto; margin-top: 12px; background: var(--cy-alert-soft); box-shadow: none; }
/* live build strip */
.cy-strip-b { margin-top: 12px; display: flex; flex-direction: column; gap: 10px; }
.cy-stages { display: grid; grid-template-columns: repeat(6, 1fr); gap: 4px; }
.cy-stg { display: flex; flex-direction: column; gap: 6px; font-size: 10.5px; font-weight: 500; color: var(--cy-ink4); }
.cy-stg i { height: 3px; border-radius: 2px; background: var(--cy-raise-3); }
.cy-stg.done { color: var(--cy-ink2); } .cy-stg.done i { background: linear-gradient(90deg, #5b5bff, #8b5cff); }
.cy-stg.skip i { background: repeating-linear-gradient(90deg, var(--cy-line3) 0 3px, transparent 3px 6px); }
.cy-stg.now { color: var(--cy-ink); } .cy-stg.now i { background: linear-gradient(90deg, #8b5cff, #e04dff, #8b5cff); background-size: 200% 100%; animation: cy-shimmer 1.6s linear infinite; box-shadow: 0 0 10px rgba(200, 90, 255, .7); }
.cy-strip-h { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 600; color: var(--cy-ink); }
.cy-strip-h span { margin-left: auto; font: 500 11.5px/1 var(--font-mono); color: var(--cy-ink3); }
.cy-strip-b .cy-thoughts { margin: 0; align-items: stretch; font: 400 11.5px/1.5 var(--font-mono); color: var(--cy-ink2); }
.cy-strip-b .cy-thoughts li { justify-content: flex-start; }
/* files tab */
.cy-files { display: flex; flex-direction: column; gap: 14px; padding: 16px 14px 24px; }
.cy-files-g h4 { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; font-size: 13px; font-weight: 600; color: var(--cy-ink); }
.cy-files-g.on h4 { color: var(--cy-accent-ink); }
.cy-files-f { display: flex; align-items: center; gap: 9px; width: 100%; height: 32px; padding: 0 10px 0 30px; border-radius: var(--cy-r-sm); font: 400 12px/1 var(--font-mono); color: var(--cy-ink2); text-align: left; }
.cy-files-f:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-welcome { padding: 22px; overflow-y: auto; }
.cy-welcome h3 { margin: 10px 0 8px; font-size: 22px; font-weight: 600; letter-spacing: -.02em; }
.cy-welcome p { font-size: 13.5px; line-height: 1.6; color: var(--cy-ink2); margin-bottom: 18px; }

/* ── composer ────────────────────────────────────────────────────────── */
.cy-dockc { position: absolute; z-index: 11; left: 28px; right: calc(var(--cy-insp-w) + 40px); bottom: 12px; display: flex; flex-direction: column; align-items: center; gap: 6px; }
.cy-composer { position: relative; width: 100%; max-width: 760px; text-align: left; }
.cy-composer-box { position: relative; isolation: isolate; border-radius: var(--cy-r-lg); }
.cy-rim { position: absolute; inset: 0; z-index: 2; border-radius: inherit; padding: 1px; pointer-events: none; opacity: .55;
  background: conic-gradient(from var(--cy-ang), rgba(150, 160, 255, .22) 0deg 200deg, #3b82ff 250deg, #8b5cff 290deg, #e04dff 330deg, rgba(150, 160, 255, .22) 360deg);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  animation: cy-rim 8s linear infinite paused; transition: opacity .3s; }
.cy-composer:focus-within .cy-rim, .cy-composer.listening .cy-rim { opacity: 1; animation-play-state: running; }
.cy-composer-in { position: relative; z-index: 1; border-radius: inherit; display: flex; flex-direction: column; background: var(--cy-surface); border: 1px solid var(--cy-line2);
  box-shadow: var(--cy-shadow), 0 0 50px -26px rgba(139, 92, 255, .9); -webkit-backdrop-filter: var(--cy-blur); backdrop-filter: var(--cy-blur); }
.cy-composer.drag .cy-composer-in { border-color: var(--cy-accent-ink); }
.cy-modes { display: flex; gap: 2px; padding: 6px 8px 0; border-bottom: 1px solid var(--cy-line); }
.cy-mode { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 12px; border-radius: 8px 8px 0 0; font-size: 12.5px; font-weight: 500; color: var(--cy-ink3); transition: color .15s, background .15s; }
.cy-mode:hover { color: var(--cy-ink); }
.cy-mode.on { color: var(--cy-ink); background: linear-gradient(180deg, rgba(110, 90, 255, .2), rgba(110, 90, 255, .05)); }
.cy-mode.on::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--cy-grad); box-shadow: 0 0 8px rgba(190, 80, 255, .8); }
.cy-field { position: relative; }
.cy-composer textarea { width: 100%; min-height: 44px; resize: none; background: transparent; border: 0; outline: 0 !important; display: block; color: var(--cy-ink); font-size: 14px; line-height: 1.5; padding: 12px 16px 4px; }
.cy-composer textarea::placeholder { color: var(--cy-ink4); }
.cy-bar { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 10px 10px 10px; }
.cy-bar-l, .cy-bar-r { display: flex; align-items: center; gap: 4px; min-width: 0; }
.cy-bar-r { margin-left: auto; gap: 10px; }
.cy-tool { display: grid; place-items: center; width: 34px; height: 34px; border-radius: var(--cy-r); color: var(--cy-ink2); transition: color .15s, background .15s; }
.cy-tool:hover { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-mic.on { color: #fff; background: var(--cy-grad); }
.cy-mic.unsupported { opacity: .5; }
.cy-pick { display: inline-flex; align-items: center; gap: 8px; height: 34px; margin-left: 4px; padding: 0 10px; border-radius: var(--cy-r); font-size: 12.5px; font-weight: 600; color: var(--cy-ink); background: var(--cy-raise-2); border: 1px solid var(--cy-line2); white-space: nowrap; transition: border-color .15s; }
.cy-pick:hover, .cy-pick[aria-expanded="true"] { border-color: var(--cy-line3); }
.cy-pick > svg:last-child { color: var(--cy-ink3); }
.cy-pick.ver { font-weight: 500; }
.cy-pick-v { color: var(--cy-ink2); font-variant-numeric: tabular-nums; }
.cy-est { font: 500 11px/1 var(--font-mono); color: var(--cy-ink3); white-space: nowrap; }
.cy-go { display: grid; place-items: center; width: 46px; height: 36px; border-radius: var(--cy-r); color: #fff; background: var(--cy-grad); box-shadow: 0 8px 22px -10px rgba(190, 70, 255, .95), inset 0 1px 0 rgba(255, 255, 255, .22); transition: filter .15s, transform .15s var(--cy-ease), opacity .2s; }
.cy-go:hover:not(:disabled) { filter: brightness(1.1); transform: translateY(-1px); }
.cy-go:disabled { opacity: .45; box-shadow: none; }
.cy-composer-msg { padding: 6px 8px 0; font-size: 12px; line-height: 1.45; text-align: center; color: var(--cy-ink3); }
.cy-composer-msg .bad { color: var(--cy-alert); font-weight: 550; } .cy-composer-msg .warn { color: var(--cy-warn); }
.cy-composer-msg button { color: var(--cy-accent-ink); font-weight: 600; text-decoration: underline; text-underline-offset: 3px; }
.cy-legal { font-size: 10px; color: var(--cy-ink4); text-align: center; }
.cy-mm { display: inline-flex; align-items: flex-end; gap: 2px; height: 11px; flex: none; }
.cy-mm i { width: 3px; border-radius: 1px; background: var(--cy-line3); }
.cy-mm i:nth-child(1) { height: 5px; } .cy-mm i:nth-child(2) { height: 8px; } .cy-mm i:nth-child(3) { height: 11px; }
.cy-mm i.on { background: linear-gradient(#e04dff, #8b5cff); }
.cy-gm { display: inline-grid; place-items: center; flex: none; border-radius: 5px; font-family: var(--font-mono); font-weight: 700; color: #fff; background: linear-gradient(135deg, #2fd67f, #1f9f5a); line-height: 1; }
.cy-badge { display: inline-flex; align-items: center; gap: 7px; height: 24px; padding: 0 8px 0 7px; border-radius: 7px; white-space: nowrap; font: 600 10px/1 var(--font-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--cy-ink2); background: rgba(10, 12, 38, .6); border: 1px solid rgba(150, 120, 255, .35); }
:root.nx-portal[data-theme="light"] .cy-badge { background: var(--cy-raise); }
.cy-badge-v { padding-left: 7px; border-left: 1px solid var(--cy-line2); color: var(--cy-ink3); letter-spacing: .02em; }

/* web controls + toasts */
.cy-webctl { position: absolute; z-index: 9; left: 16px; bottom: 16px; display: flex; flex-direction: column; padding: 3px; border-radius: var(--cy-r-md); background: rgba(10, 12, 38, .8); border: 1px solid var(--cy-line2); }
.cy-webctl button { display: grid; place-items: center; width: 30px; height: 30px; border-radius: var(--cy-r-sm); color: #aab1e0; }
.cy-webctl button:hover { color: #fff; background: rgba(150, 160, 255, .12); }
EOF
echo ok

input.command:
S=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad && cat > $S/resp.css <<'EOF'

/* buttons in the v4 style */
.cy-btn { height: 36px; padding: 0 14px; border-radius: var(--cy-r); font-size: 13px; font-weight: 500; color: var(--cy-ink); background: var(--cy-surface); border: 1px solid var(--cy-line2); -webkit-backdrop-filter: var(--cy-blur); backdrop-filter: var(--cy-blur); }
.cy-btn:hover:not(:disabled) { background: var(--cy-raise-3); border-color: var(--cy-line3); }
.cy-btn.icon { width: 40px; padding: 0; }
.cy-btn.primary { color: #fff; border-color: transparent; background: var(--cy-grad); box-shadow: 0 10px 26px -12px rgba(190, 70, 255, .95), inset 0 1px 0 rgba(255, 255, 255, .22); }
.cy-btn.primary:hover:not(:disabled) { filter: brightness(1.08); background: var(--cy-grad); }
.cy-btn:disabled { opacity: .5; }
.cy-insp-act .cy-btn.primary { padding: 0 18px; }
.cy-menu { background: var(--cy-pop); }
.cy-panel { background: var(--cy-pop); }
.cy-opt.on { box-shadow: inset 2px 0 0 var(--cy-violet); background: var(--cy-accent-soft); }
.cy-toasts { position: absolute; left: calc(50% + var(--cy-side-w) / 2 - var(--cy-insp-w) / 2); bottom: 150px; z-index: 85; transform: translateX(-50%); display: flex; flex-direction: column; gap: 8px; align-items: center; }
.cy-toast { display: inline-flex; align-items: center; gap: 10px; padding: 8px 14px 8px 8px; border-radius: 999px; font-size: 13px; font-weight: 550; color: var(--cy-ink); background: var(--cy-pop); border: 1px solid var(--cy-line2); box-shadow: var(--cy-shadow-pop); animation: cy-toast .4s var(--cy-ease) both; }
.cy-toast-orb { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; color: #fff; background: var(--cy-grad); }
.cy-toast.bad .cy-toast-orb { background: var(--cy-alert); }
.cy-toast-go { display: inline-flex; align-items: center; gap: 2px; font-size: 12px; color: var(--cy-ink3); }
.cy-modal { background: var(--cy-pop); border: 1px solid var(--cy-line2); }
.cy-modal-back { background: rgba(3, 4, 18, .6); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.cy-game.on .cy-gm { background: linear-gradient(135deg, #2fd67f, #1f9f5a); }

/* light chrome around the dark space island */
:root.nx-portal[data-theme="light"] .cy-top { background: rgba(255, 255, 255, .96); border-bottom: 1px solid var(--cy-line); }
:root.nx-portal[data-theme="light"] .cy-top-search { background: #f4f5fb; }
:root.nx-portal[data-theme="light"] .cy-pro { background: linear-gradient(160deg, rgba(109, 61, 240, .1), rgba(224, 77, 255, .06)); border-color: rgba(109, 61, 240, .25); box-shadow: none; }
:root.nx-portal[data-theme="light"] .cy-side-i svg { color: var(--cy-ink3); }
:root.nx-portal[data-theme="light"] .cy-tab.on { background: rgba(109, 61, 240, .1); box-shadow: inset 0 0 0 1px rgba(109, 61, 240, .3); }
:root.nx-portal[data-theme="light"] .cy-mode.on { background: rgba(109, 61, 240, .08); }
:root.nx-portal[data-theme="light"] .cy-view-tag { background: #fff; color: #5b2ee0; }

/* ── narrower desktops: icon sidebar ──────────────────────────────────── */
@container cyapp (max-width: 1279px) {
  .cy-app { --cy-side-w: 72px; }
}
@media (max-width: 1279px) {
  .cy-app { --cy-side-w: 72px; --cy-insp-w: clamp(360px, 34vw, 440px); }
  .cy-side { padding: 14px 10px; align-items: center; }
  .cy-side-logo { padding: 0; justify-content: center; }
  .cy-side-logo img { height: 22px !important; width: auto; object-fit: cover; object-position: left; max-width: 34px; }
  .cy-side-i span, .cy-side-p span:not(.cy-side-pi), .cy-beta, .cy-side-n, .cy-side-soon, .cy-side-h span, .cy-pro p, .cy-pro-h { display: none; }
  .cy-side-i, .cy-side-p { width: 44px; justify-content: center; padding: 0; }
  .cy-side-h { justify-content: center; margin: 16px 0 6px; }
  .cy-pro { padding: 6px; } .cy-pro-go { width: 40px; font-size: 0; gap: 0; }
}

/* ── tablets: stacked ────────────────────────────────────────────────── */
@media (max-width: 1023px) {
  .cy-main { overflow-y: auto; overflow-x: hidden; scrollbar-width: none; }
  .cy-stage { position: sticky; top: 0; height: 58vh; min-height: 380px; }
  .cy-insp { position: relative; inset: auto; width: auto; margin: -24px 12px 12px; }
  .cy-insp.wide { width: auto; }
  .cy-dockc { position: sticky; left: auto; right: auto; bottom: 0; margin: 0 12px; padding-bottom: 10px; }
  .cy-webctl { display: none; }
  .cy-toasts { left: 50%; bottom: 140px; }
}
/* ── phones ──────────────────────────────────────────────────────────── */
@media (max-width: 759px) {
  .cy-app { grid-template-columns: minmax(0, 1fr); --cy-side-w: 0px; min-height: 0; }
  .cy-side { position: fixed; z-index: 96; inset: 0 auto 0 0; width: 260px; align-items: stretch; transform: translateX(-104%); transition: transform .26s var(--cy-ease); padding: 14px 12px; }
  .cy-side.open { transform: none; }
  .cy-side .cy-side-i span, .cy-side .cy-side-p span:not(.cy-side-pi), .cy-side .cy-beta, .cy-side .cy-side-n, .cy-side .cy-side-soon, .cy-side .cy-side-h span, .cy-side .cy-pro p, .cy-side .cy-pro-h { display: revert; }
  .cy-side .cy-side-i, .cy-side .cy-side-p { width: auto; justify-content: flex-start; padding: 0 12px; }
  .cy-side .cy-side-h { justify-content: space-between; } .cy-side .cy-pro { padding: 14px; } .cy-side .cy-pro-go { width: 100%; font-size: 13px; gap: 7px; }
  .cy-side .cy-side-logo img { height: 25px !important; max-width: none; }
  .cy-side-back { display: block; position: fixed; inset: 0; z-index: 95; background: rgba(3, 4, 18, .6); }
  .cy-top { padding: 0 10px; gap: 8px; height: 52px; }
  .cy-top-menu { display: grid; place-items: center; width: 38px; height: 38px; flex: none; border-radius: var(--cy-r); color: var(--cy-ink); background: var(--cy-surface); border: 1px solid var(--cy-line2); }
  .cy-top-search { flex: 1; width: auto; }
  .cy-top-search kbd, .cy-top-name, .cy-top-me > svg, .cy-top-ib { display: none; }
  .cy-stage { height: 50vh; min-height: 340px; }
  .cy-insp { margin: -8px 8px 10px; }
  .cy-insp-act { justify-content: stretch; } .cy-insp-act .cy-btn.primary { flex: 1; }
  .cy-tabs { overflow-x: auto; scrollbar-width: none; } .cy-tab { flex: none; padding: 0 10px; }
  .cy-code { height: 46vh; }
  .cy-mod-act .cy-btn { flex: 1 1 100%; }
  .cy-dockc { margin: 0 8px; }
  .cy-modes { overflow-x: auto; scrollbar-width: none; } .cy-mode { flex: none; padding: 0 10px; }
  .cy-est, .cy-legal, .cy-pick.ver { display: none; }
  .cy-pop-back { display: block; position: fixed; inset: 0; z-index: 59; background: rgba(3, 4, 18, .55); animation: cy-fade .18s ease-out; }
  .cy-pop-panel { position: fixed; left: 0; right: 0; bottom: 0; top: auto; width: auto; z-index: 60; }
  .cy-pop-panel .cy-panel { border-radius: 16px 16px 0 0; border-bottom: 0; padding: 4px 8px calc(12px + env(safe-area-inset-bottom)); max-height: 78dvh; overflow-y: auto; animation: cy-sheet .26s var(--cy-ease) both; }
  .cy-sheet-grab { display: block; width: 36px; height: 4px; border-radius: 2px; margin: 6px auto 4px; background: var(--cy-line3); }
  .cy-toasts { bottom: 120px; width: calc(100% - 24px); }
}
EOF
